export default "e).raw\\n\\n                    images.append(Image.open(image_stream).convert(\\\"RGB\\\"))\\n                elif input_item.type == \\\"video_url\\\":\\n                    text_content += VIDEO_PLACEHOLDER\\n                    video_url = input_item.video_url.url\\n                    if re.match(r\\\"^data:video\\\\/(mp4|mkv|avi|mov);base64,(.+)$\\\", video_url):  # base64 video\\n                        video_stream = io.BytesIO(base64.b64decode(video_url.split(\\\",\\\", maxsplit=1)[1]))\\n                    elif os.path.isfile(video_url):  # local file\\n                        check_lfi_path(video_url)\\n                        video_stream = video_url\\n                    else:  # web uri\\n                        check_ssrf_url(video_url)\\n                        video_stream = requests.get(video_url, stream=True).raw\\n\\n                    videos.append(video_stream)\\n                elif input_item.type == \\\"audio_url\\\":\\n                    text_content += AUDIO_PLACEHOLDER\\n                    audio_url = input_item.audio_url.url\\n                    if re.match(r\\\"^data:audio\\\\/(mpeg|mp3|wav|ogg);base64,(.+)$\\\", audio_url):  # base64 audio\\n                        audio_stream = io.BytesIO(base64.b64decode(audio_url.split(\\\",\\\", maxsplit=1)[1]))\\n                    elif os.path.isfile(audio_url):  # local file\\n                        check_lfi_path(audio_url)\\n                        audio_stream = audio_url\\n                    else:  # web uri\\n                        check_ssrf_url(audio_url)\\n                        audio_stream = requests.get(audio_url, stream=True).raw\\n\\n                    audios.append(audio_stream)\\n                else:\\n                    raise HTTPException(\\n                        status_code=status.HTTP_400_BAD_REQUEST, detail=f\\\"Invalid input type {input_item.type}.\\\"\\n                    )\\n\\n            input_messages.append({\\\"role\\\": ROLE_MAPPING[message.role], \\\"content\\\": text_content})\\n        else:\\n            input_messages.append({\\\"role\\\": ROLE_MAPPING[message.role], \\\"content\\\": message.content})\\n\\n    tool_list = request.tools\\n    if isinstance(tool_list, list) and len(tool_list):\\n        try:\\n            tools = json.dumps([dictify(tool.function) for tool in tool_list], ensure_ascii=False)\\n        except json.JSONDecodeError:\\n            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid tools\\\")\\n    else:\\n        tools = None\\n\\n    return input_messages, system, tools, images or None, videos or None, audios or None\\n\\n\\ndef _create_stream_chat_completion_chunk(\\n    completion_id: str,\\n    model: str,\\n    delta: \\\"ChatCompletionMessage\\\",\\n    index: Optional[int] = 0,\\n    finish_reason: Optional[\\\"Finish\\\"] = None,\\n) -> str:\\n    choice_data = ChatCompletionStreamResponseChoice(index=index, delta=delta, finish_reason=finish_reason)\\n    chunk = ChatCompletionStreamResponse(id=completion_id, model=model, choices=[choice_data])\\n    return jsonify(chunk)\\n\\n\\nasync def create_chat_completion_response(\\n    request: \\\"ChatCompletionRequest\\\", chat_model: \\\"ChatModel\\\"\\n) -> \\\"ChatCompletionResponse\\\":\\n    completion_id = f\\\"chatcmpl-{uuid.uuid4().hex}\\\"\\n    input_messages, system, tools, images, videos, audios = _process_request(request)\\n    responses = await chat_model.achat(\\n        input_messages,\\n        system,\\n        tools,\\n        images,\\n        videos,\\n        audios,\\n        do_sample=request.do_sample,\\n        temperature=request.temperature,\\n        top_p=request.top_p,\\n        max_new_tokens=request.max_tokens,\\n        num_return_sequences=request.n,\\n        repetition_penalty=request.presence_penalty,\\n        stop=request.stop,\\n    )\\n\\n    prompt_length, response_length = 0, 0\\n    choices = []\\n    for i, response in enumerate(responses):\\n        if tools:\\n            result = chat_model.engine.template.extract_tool(response.response_text)\\n        else:\\n            result = response.response_text\\n\\n        if isinstance(result, list):\\n            tool_calls = []\\n            for tool in result:\\n                function = Function(name=tool.name, arguments=tool.arguments)\\n                tool_calls.append(FunctionCall(id=f\\\"call_{uuid.uuid4().hex}\\\", function=function))\\n\\n            response_message = ChatCompletionMessage(role=Role.ASSISTANT, tool_calls=tool_calls)\\n            finish_reason = Finish.TOOL\\n        else:\\n            response_message = ChatCompletionMessage(role=Role.ASSISTANT, content=result)\\n            finish_reason = Finish.STOP if response.finish_reason == \\\"stop\\\" else Finish.LENGTH\\n\\n        choices.append(ChatCompletionResponseChoice(index=i, message=response_message, finish_reason=finish_reason))\\n        prompt_length = response.prompt_length\\n        response_length += response.response_length\\n\\n    usage = ChatCompletionResponseUsage(\\n        prompt_tokens=prompt_length,\\n        completion_tokens=response_length,\\n        total_tokens=prompt_length + response_length,\\n    )\\n\\n    return ChatCompletionResponse(id=completion_id, model=request.model, choices=choices, usage=usage)\\n\\n\\nasync def create_stream_chat_completion_response(\\n    request: \\\"ChatCompletionRequest\\\", chat_model: \\\"ChatModel\\\"\\n) -> AsyncGenerator[str, None]:\\n    completion_id = f\\\"chatcmpl-{uuid.uuid4().hex}\\\"\\n    input_messages, system, tools, images, videos, audios = _process_request(request)\\n    if tools:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Cannot stream function calls.\\\")\\n\\n    if request.n > 1:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Cannot stream multiple responses.\\\")\\n\\n    yield _create_stream_chat_completion_chunk(\\n        completion_id=completion_id, model=request.model, delta=ChatCompletionMessage(role=Role.ASSISTANT, content=\\\"\\\")\\n    )\\n    async for new_token in chat_model.astream_chat(\\n        input_messages,\\n        system,\\n        tools,\\n        images,\\n        videos,\\n        audios,\\n        do_sample=request.do_sample,\\n        temperature=request.temperature,\\n        top_p=request.top_p,\\n        max_new_tokens=request.max_tokens,\\n        repetition_penalty=request.presence_penalty,\\n        stop=request.stop,\\n    ):\\n        if len(new_token) != 0:\\n            yield _create_stream_chat_completion_chunk(\\n                completion_id=completion_id, model=request.model, delta=ChatCompletionMessage(content=new_token)\\n            )\\n\\n    yield _create_stream_chat_completion_chunk(\\n        completion_id=completion_id, model=request.model, delta=ChatCompletionMessage(), finish_reason=Finish.STOP\\n    )\\n    yield \\\"[DONE]\\\"\\n\\n\\nasync def create_score_evaluation_response(\\n    request: \\\"ScoreEvaluationRequest\\\", chat_model: \\\"ChatModel\\\"\\n) -> \\\"ScoreEvaluationResponse\\\":\\n    score_id = f\\\"scoreval-{uuid.uuid4().hex}\\\"\\n    if len(request.messages) == 0:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid request\\\")\\n\\n    scores = await chat_model.aget_scores(request.messages, max_length=request.max_length)\\n    return ScoreEvaluationResponse(id=score_id, model=request.model, scores=scores)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/api/common.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"86c278f4bca6ec354364aa108878f04c360e0e97b8163f6f107349b7a3e2ffa3\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport ipaddress\\nimport json\\nimport os\\nimport socket\\nfrom typing import TYPE_CHECKING, Any\\nfrom urllib.parse import urlparse\\n\\nfrom ..extras.misc import is_env_enabled\\nfrom ..extras.packages import is_fastapi_available\\n\\n\\nif is_fastapi_available():\\n    from fastapi import HTTPException, status\\n\\n\\nif TYPE_CHECKING:\\n    from pydantic import BaseModel\\n\\n\\nSAFE_MEDIA_PATH = os.environ.get(\\\"SAFE_MEDIA_PATH\\\", os.path.join(os.path.dirname(__file__), \\\"safe_media\\\"))\\nALLOW_LOCAL_FILES = is_env_enabled(\\\"ALLOW_LOCAL_FILES\\\", \\\"1\\\")\\n\\n\\ndef dictify(data: \\\"BaseModel\\\") -> dict[str, Any]:\\n    try:  # pydantic v2\\n        return data.model_dump(exclude_unset=True)\\n    except AttributeError:  # pydantic v1\\n        return data.dict(exclude_unset=True)\\n\\n\\ndef jsonify(data: \\\"BaseModel\\\") -> str:\\n    try:  # pydantic v2\\n        return json.dumps(data.model_dump(exclude_unset=True), ensure_ascii=False)\\n    except AttributeError:  # pydantic v1\\n        return data.json(exclude_unset=True, ensure_ascii=False)\\n\\n\\ndef check_lfi_path(path: str) -> None:\\n    \\\"\\\"\\\"Checks if a given path is vulnerable to LFI. Raises HTTPException if unsafe.\\\"\\\"\\\"\\n    if not ALLOW_LOCAL_FILES:\\n        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=\\\"Local file access is disabled.\\\")\\n\\n    try:\\n        os.makedirs(SAFE_MEDIA_PATH, exist_ok=True)\\n        real_path = os.path.realpath(path)\\n        safe_path = os.path.realpath(SAFE_MEDIA_PATH)\\n\\n        if not real_path.startswith(safe_path):\\n            raise HTTPException(\\n                status_code=status.HTTP_403_FORBIDDEN, detail=\\\"File access is restricted to the safe media directory.\\\"\\n            )\\n    except Exception:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid or inaccessible file path.\\\")\\n\\n\\ndef check_ssrf_url(url: str) -> None:\\n    \\\"\\\"\\\"Checks if a given URL is vulnerable to SSRF. Raises HTTPException if unsafe.\\\"\\\"\\\"\\n    try:\\n        parsed_url = urlparse(url)\\n        if parsed_url.scheme not in [\\\"http\\\", \\\"https\\\"]:\\n            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Only HTTP/HTTPS URLs are allowed.\\\")\\n\\n        hostname = parsed_url.hostname\\n        if not hostname:\\n            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid URL hostname.\\\")\\n\\n        ip_info = socket.getaddrinfo(hostname, parsed_url.port)\\n        ip_address_str = ip_info[0][4][0]\\n        ip = ipaddress.ip_address(ip_address_str)\\n\\n        if not ip.is_global:\\n            raise HTTPException(\\n                status_code=status.HTTP_403_FORBIDDEN,\\n                detail=\\\"Access to private or reserved IP addresses is not allowed.\\\",\\n            )\\n\\n    except socket.gaierror:\\n        raise HTTPException(\\n            status_code=status.HTTP_400_BAD_REQUEST, detail=f\\\"Could not resolve hostname: {parsed_url.hostname}\\\"\\n        )\\n    except Exception as e:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f\\\"Invalid URL: {e}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/api/protocol.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"454cce01b6569af5b405fbeb52ef46c3865048015094e66d35350c4dcd4068f2\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport time\\nfrom enum import StrEnum, unique\\nfrom typing import Any, Literal\\n\\nfrom pydantic import BaseModel, Field\\n\\n\\n@unique\\nclass Role(StrEnum):\\n    USER = \\\"user\\\"\\n    ASSISTANT = \\\"assistant\\\"\\n    SYSTEM = \\\"system\\\"\\n    FUNCTION = \\\"function\\\"\\n    TOOL = \\\"tool\\\"\\n\\n\\n@unique\\nclass Finish(StrEnum):\\n    STOP = \\\"stop\\\"\\n    LENGTH = \\\"length\\\"\\n    TOOL = \\\"tool_calls\\\"\\n\\n\\nclass ModelCard(BaseModel):\\n    id: str\\n    object: Literal[\\\"model\\\"] = \\\"model\\\"\\n    created: int = Field(default_factory=lambda: int(time.time()))\\n    owned_by: Literal[\\\"owner\\\"] = \\\"owner\\\"\\n\\n\\nclass ModelList(BaseModel):\\n    object: Literal[\\\"list\\\"] = \\\"list\\\"\\n    data: list[ModelCard] = []\\n\\n\\nclass Function(BaseModel):\\n    name: str\\n    arguments: str\\n\\n\\nclass FunctionDefinition(BaseModel):\\n    name: str\\n    description: str\\n    parameters: dict[str, Any]\\n\\n\\nclass FunctionAvailable(BaseModel):\\n    type: Literal[\\\"function\\\", \\\"code_interpreter\\\"] = \\\"function\\\"\\n    function: FunctionDefinition | None = None\\n\\n\\nclass FunctionCall(BaseModel):\\n    id: str\\n    type: Literal[\\\"function\\\"] = \\\"function\\\"\\n    function: Function\\n\\n\\nclass URL(BaseModel):\\n    url: str\\n    detail: Literal[\\\"auto\\\", \\\"low\\\", \\\"high\\\"] = \\\"auto\\\"\\n\\n\\nclass MultimodalInputItem(BaseModel):\\n    type: Literal[\\\"text\\\", \\\"image_url\\\", \\\"video_url\\\", \\\"audio_url\\\"]\\n    text: str | None = None\\n    image_url: URL | None = None\\n    video_url: URL | None = None\\n    audio_url: URL | None = None\\n\\n\\nclass ChatMessage(BaseModel):\\n    role: Role\\n    content: str | list[MultimodalInputItem] | None = None\\n    tool_calls: list[FunctionCall] | None = None\\n\\n\\nclass ChatCompletionMessage(BaseModel):\\n    role: Role | None = None\\n    content: str | None = None\\n    tool_calls: list[FunctionCall] | None = None\\n\\n\\nclass ChatCompletionRequest(BaseModel):\\n    model: str\\n    messages: list[ChatMessage]\\n    tools: list[FunctionAvailable] | None = None\\n    do_sample: bool | None = None\\n    temperature: float | None = None\\n    top_p: float | None = None\\n    n: int = 1\\n    presence_penalty: float | None = None\\n    max_tokens: int | None = None\\n    stop: str | list[str] | None = None\\n    stream: bool = False\\n\\n\\nclass ChatCompletionResponseChoice(BaseModel):\\n    index: int\\n    message: ChatCompletionMessage\\n    finish_reason: Finish\\n\\n\\nclass ChatCompletionStreamResponseChoice(BaseModel):\\n    index: int\\n    delta: ChatCompletionMessage\\n    finish_reason: Finish | None = None\\n\\n\\nclass ChatCompletionResponseUsage(BaseModel):\\n    prompt_tokens: int\\n    completion_tokens: int\\n    total_tokens: int\\n\\n\\nclass ChatCompletionResponse(BaseModel):\\n    id: str\\n    object: Literal[\\\"chat.completion\\\"] = \\\"chat.completion\\\"\\n    created: int = Field(default_factory=lambda: int(time.time()))\\n    model: str\\n    choices: list[ChatCompletionResponseChoice]\\n    usage: ChatCompletionResponseUsage\\n\\n\\nclass ChatCompletionStreamResponse(BaseModel):\\n    id: str\\n    object: Literal[\\\"chat.completion.chunk\\\"] = \\\"chat.completion.chunk\\\"\\n    created: int = Field(default_factory=lambda: int(time.time()))\\n    model: str\\n    choices: list[ChatCompletionStreamResponseChoice]\\n\\n\\nclass ScoreEvaluationRequest(BaseModel):\\n    model: str\\n    messages: list[str]\\n    max_length: int | None = None\\n\\n\\nclass ScoreEvaluationResponse(BaseModel):\\n    id: str\\n    object: Literal[\\\"score.evaluation\\\"] = \\\"score.evaluation\\\"\\n    model: str\\n    scores: list[float]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"15f9960ed2e888daa1d3104a736d138927b3a86f4faf01446d2046da386eed9d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .base_engine import BaseEngine\\nfrom .chat_model import ChatModel\\n\\n\\n__all__ = [\\\"BaseEngine\\\", \\\"ChatModel\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/base_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"21f8f22fe96ee40d480591d419e54fb07b4743e2905d683d297571b668eba55f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom abc import ABC, abstractmethod\\nfrom collections.abc import AsyncGenerator\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Any, Literal, Optional, Union\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, PreTrainedTokenizer\\n    from vllm import AsyncLLMEngine\\n\\n    from ..data import Template\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n    from ..extras.constants import EngineName\\n    from ..hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\n@dataclass\\nclass Response:\\n    response_text: str\\n    response_length: int\\n    prompt_length: int\\n    finish_reason: Literal[\\\"stop\\\", \\\"length\\\"]\\n\\n\\nclass BaseEngine(ABC):\\n    r\\\"\\\"\\\"Base class for inference engine of chat models.\\n\\n    Must implements async methods: chat(), stream_chat() and get_scores().\\n    \\\"\\\"\\\"\\n\\n    name: \\\"EngineName\\\"\\n    model: Union[\\\"PreTrainedModel\\\", \\\"AsyncLLMEngine\\\"]\\n    tokenizer: \\\"PreTrainedTokenizer\\\"\\n    can_generate: bool\\n    template: \\\"Template\\\"\\n    generating_args: dict[str, Any]\\n\\n    @abstractmethod\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        data_args: \\\"DataArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n    ) -> None:\\n        r\\\"\\\"\\\"Initialize an inference engine.\\\"\\\"\\\"\\n        ...\\n\\n    @abstractmethod\\n    async def chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        r\\\"\\\"\\\"Get a list of responses of the chat model.\\\"\\\"\\\"\\n        ...\\n\\n    @abstractmethod\\n    async def stream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncGenerator[str, None]:\\n        r\\\"\\\"\\\"Get the response token-by-token of the chat model.\\\"\\\"\\\"\\n        ...\\n\\n    @abstractmethod\\n    async def get_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        r\\\"\\\"\\\"Get a list of scores of the reward model.\\\"\\\"\\\"\\n        ...\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/chat_model.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b7d1a5051a8f81e9b3b8aa6f0fb1b888d8d7d79a42687dd53209e4f670a04b56\",\"content\":\"# Copyright 2025 THUDM and the LlamaFactory team.\\n#\\n# This code is inspired by the THUDM's ChatGLM implementation.\\n# https://github.com/THUDM/ChatGLM-6B/blob/main/cli_demo.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport asyncio\\nimport os\\nfrom collections.abc import AsyncGenerator, Generator\\nfrom threading import Thread\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nfrom ..extras.constants import EngineName\\nfrom ..extras.misc import torch_gc\\nfrom ..hparams import get_infer_args\\n\\n\\nif TYPE_CHECKING:\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n    from .base_engine import BaseEngine, Response\\n\\n\\ndef _start_background_loop(loop: \\\"asyncio.AbstractEventLoop\\\") -> None:\\n    asyncio.set_event_loop(loop)\\n    loop.run_forever()\\n\\n\\nclass ChatModel:\\n    r\\\"\\\"\\\"General class for chat models. Backed by huggingface or vllm engines.\\n\\n    Supports both sync and async methods.\\n    Sync methods: chat(), stream_chat() and get_scores().\\n    Async methods: achat(), astream_chat() and aget_scores().\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, args: Optional[dict[str, Any]] = None) -> None:\\n        model_args, data_args, finetuning_args, generating_args = get_infer_args(args)\\n\\n        if model_args.infer_backend == EngineName.HF:\\n            from .hf_engine import HuggingfaceEngine\\n\\n            self.engine: BaseEngine = HuggingfaceEngine(model_args, data_args, finetuning_args, generating_args)\\n        elif model_args.infer_backend == EngineName.VLLM:\\n            try:\\n                from .vllm_engine import VllmEngine\\n\\n                self.engine: BaseEngine = VllmEngine(model_args, data_args, finetuning_args, generating_args)\\n            except ImportError as e:\\n                raise ImportError(\\n                    \\\"vLLM not install, you may need to run `pip install vllm`\\\\n\\\"\\n                    \\\"or try to use HuggingFace backend: --infer_backend huggingface\\\"\\n                ) from e\\n        elif model_args.infer_backend == EngineName.SGLANG:\\n            try:\\n                from .sglang_engine import SGLangEngine\\n\\n                self.engine: BaseEngine = SGLangEngine(model_args, data_args, finetuning_args, generating_args)\\n            except ImportError as e:\\n                raise ImportError(\\n                    \\\"SGLang not install, you may need to run `pip install sglang[all]`\\\\n\\\"\\n                    \\\"or try to use HuggingFace backend: --infer_backend huggingface\\\"\\n                ) from e\\n        else:\\n            raise NotImplementedError(f\\\"Unknown backend: {model_args.infer_backend}\\\")\\n\\n        self._loop = asyncio.new_event_loop()\\n        self._thread = Thread(target=_start_background_loop, args=(self._loop,), daemon=True)\\n        self._thread.start()\\n\\n    def chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        r\\\"\\\"\\\"Get a list of responses of the chat model.\\\"\\\"\\\"\\n        task = asyncio.run_coroutine_threadsafe(\\n            self.achat(messages, system, tools, images, videos, audios, **input_kwargs), self._loop\\n        )\\n        return task.result()\\n\\n    async def achat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        r\\\"\\\"\\\"Asynchronously get a list of responses of the chat model.\\\"\\\"\\\"\\n        return await self.engine.chat(messages, system, tools, images, videos, audios, **input_kwargs)\\n\\n    def stream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> Generator[str, None, None]:\\n        r\\\"\\\"\\\"Get the response token-by-token of the chat model.\\\"\\\"\\\"\\n        generator = self.astream_chat(messages, system, tools, images, videos, audios, **input_kwargs)\\n        while True:\\n            try:\\n                task = asyncio.run_coroutine_threadsafe(generator.__anext__(), self._loop)\\n                yield task.result()\\n            except StopAsyncIteration:\\n                break\\n\\n    async def astream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncGenerator[str, None]:\\n        r\\\"\\\"\\\"Asynchronously get the response token-by-token of the chat model.\\\"\\\"\\\"\\n        async for new_token in self.engine.stream_chat(\\n            messages, system, tools, images, videos, audios, **input_kwargs\\n        ):\\n            yield new_token\\n\\n    def get_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        r\\\"\\\"\\\"Get a list of scores of the reward model.\\\"\\\"\\\"\\n        task = asyncio.run_coroutine_threadsafe(self.aget_scores(batch_input, **input_kwargs), self._loop)\\n        return task.result()\\n\\n    async def aget_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        r\\\"\\\"\\\"Asynchronously get a list of scores of the reward model.\\\"\\\"\\\"\\n        return await self.engine.get_scores(batch_input, **input_kwargs)\\n\\n\\ndef run_chat() -> None:\\n    if os.name != \\\"nt\\\":\\n        try:\\n            import readline  # noqa: F401\\n        except ImportError:\\n            print(\\\"Install `readline` for a better experience.\\\")\\n\\n    chat_model = ChatModel()\\n    messages = []\\n    print(\\\"Welcome to the CLI application, use `clear` to remove the history, use `exit` to exit the application.\\\")\\n\\n    while True:\\n        try:\\n            query = input(\\\"\\\\nUser: \\\")\\n        except UnicodeDecodeError:\\n            print(\\\"Detected decoding error at the inputs, please set the terminal encoding to utf-8.\\\")\\n            continue\\n        except Exception:\\n            raise\\n\\n        if query.strip() == \\\"exit\\\":\\n            break\\n\\n        if query.strip() == \\\"clear\\\":\\n            messages = []\\n            torch_gc()\\n            print(\\\"History has been removed.\\\")\\n            continue\\n\\n        messages.append({\\\"role\\\": \\\"user\\\", \\\"content\\\": query})\\n        print(\\\"Assistant: \\\", end=\\\"\\\", flush=True)\\n\\n        response = \\\"\\\"\\n        for new_text in chat_model.stream_chat(messages):\\n            print(new_text, end=\\\"\\\", flush=True)\\n            response += new_text\\n        print()\\n        messages.append({\\\"role\\\": \\\"assistant\\\", \\\"content\\\": response})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/hf_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b620152cf11dcfc653acd2119f7c8e5250e72d5cedcadb82ddd13d95be0b8d60\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport asyncio\\nimport os\\nfrom collections.abc import AsyncGenerator, Callable\\nfrom threading import Thread\\nfrom typing import TYPE_CHECKING, Any, Optional, Union\\n\\nimport torch\\nfrom transformers import GenerationConfig, TextIteratorStreamer, set_seed\\nfrom typing_extensions import override\\n\\nfrom ..data import get_template_and_fix_tokenizer\\nfrom ..extras import logging\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER, EngineName\\nfrom ..model import load_model, load_tokenizer\\nfrom .base_engine import BaseEngine, Response\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, PreTrainedTokenizer, ProcessorMixin\\n    from trl import PreTrainedModelWrapper\\n\\n    from ..data import Template\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n    from ..hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass HuggingfaceEngine(BaseEngine):\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        data_args: \\\"DataArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n    ) -> None:\\n        self.name = EngineName.HF\\n        self.can_generate = finetuning_args.stage == \\\"sft\\\"\\n        tokenizer_module = load_tokenizer(model_args)\\n        self.tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n        self.processor = tokenizer_module[\\\"processor\\\"]\\n        self.tokenizer.padding_side = \\\"left\\\" if self.can_generate else \\\"right\\\"\\n        self.template = get_template_and_fix_tokenizer(self.tokenizer, data_args)\\n        self.model = load_model(\\n            self.tokenizer, model_args, finetuning_args, is_trainable=False, add_valuehead=(not self.can_generate)\\n        )  # must after fixing tokenizer to resize vocab\\n        self.generating_args = generating_args.to_dict()\\n        try:\\n            asyncio.get_event_loop()\\n        except RuntimeError:\\n            logger.warning_rank0_once(\\\"There is no current event loop, creating a new one.\\\")\\n            loop = asyncio.new_event_loop()\\n            asyncio.set_event_loop(loop)\\n\\n        self.semaphore = asyncio.Semaphore(int(os.getenv(\\\"MAX_CONCURRENT\\\", \\\"1\\\")))\\n\\n    @staticmethod\\n    def _process_args(\\n        model: \\\"PreTrainedModel\\\",\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        template: \\\"Template\\\",\\n        generating_args: dict[str, Any],\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        input_kwargs: Optional[dict[str, Any]] = {},\\n    ) -> tuple[dict[str, Any], int]:\\n        mm_input_dict = {\\\"images\\\": [], \\\"videos\\\": [], \\\"audios\\\": [], \\\"imglens\\\": [0], \\\"vidlens\\\": [0], \\\"audlens\\\": [0]}\\n        if images is not None:\\n            mm_input_dict.update({\\\"images\\\": images, \\\"imglens\\\": [len(images)]})\\n            if not any(IMAGE_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n                messages[0][\\\"content\\\"] = IMAGE_PLACEHOLDER * len(images) + messages[0][\\\"content\\\"]\\n\\n        if videos is not None:\\n            mm_input_dict.update({\\\"videos\\\": videos, \\\"vidlens\\\": [len(videos)]})\\n            if not any(VIDEO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n                messages[0][\\\"content\\\"] = VIDEO_PLACEHOLDER * len(videos) + messages[0][\\\"content\\\"]\\n\\n        if audios is not None:\\n            mm_input_dict.update({\\\"audios\\\": audios, \\\"audlens\\\": [len(audios)]})\\n            if not any(AUDIO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n                messages[0][\\\"content\\\"] = AUDIO_PLACEHOLDER * len(audios) + messages[0][\\\"content\\\"]\\n\\n        messages = template.mm_plugin.process_messages(\\n            messages, mm_input_dict[\\\"images\\\"], mm_input_dict[\\\"videos\\\"], mm_input_dict[\\\"audios\\\"], processor\\n        )\\n        paired_messages = messages + [{\\\"role\\\": \\\"assistant\\\", \\\"content\\\": \\\"\\\"}]\\n        prompt_ids, _ = template.encode_oneturn(tokenizer, paired_messages, system, tools)\\n        prompt_ids, _ = template.mm_plugin.process_token_ids(\\n            prompt_ids,\\n            None,\\n            mm_input_dict[\\\"images\\\"],\\n            mm_input_dict[\\\"videos\\\"],\\n            mm_input_dict[\\\"audios\\\"],\\n            tokenizer,\\n            processor,\\n        )\\n        prompt_length = len(prompt_ids)\\n        inputs = torch.tensor([prompt_ids], device=model.device)\\n        attention_mask = torch.ones_like(inputs, dtype=torch.long)\\n\\n        do_sample: Optional[bool] = input_kwargs.pop(\\\"do_sample\\\", None)\\n        temperature: Optional[float] = input_kwargs.pop(\\\"temperature\\\", None)\\n        top_p: Optional[float] = input_kwargs.pop(\\\"top_p\\\", None)\\n        top_k: Optional[float] = input_kwargs.pop(\\\"top_k\\\", None)\\n        num_return_sequences: int = input_kwargs.pop(\\\"num_return_sequences\\\", 1)\\n        repetition_penalty: Optional[float] = input_kwargs.pop(\\\"repetition_penalty\\\", None)\\n        length_penalty: Optional[float] = input_kwargs.pop(\\\"length_penalty\\\", None)\\n        skip_special_tokens: Optional[bool] = input_kwargs.pop(\\\"skip_special_tokens\\\", None)\\n        max_length: Optional[int] = input_kwargs.pop(\\\"max_length\\\", None)\\n        max_new_tokens: Optional[int] = input_kwargs.pop(\\\"max_new_tokens\\\", None)\\n        seed: Optional[int] = input_kwargs.pop(\\\"seed\\\", None)\\n        stop: Optional[Union[str, list[str]]] = input_kwargs.pop(\\\"stop\\\", None)\\n\\n        if stop is not None:\\n            logger.warning_rank0(\\\"Stop parameter is not supported by the huggingface engine yet.\\\")\\n\\n        generating_args = generating_args.copy()\\n        generating_args.update(\\n            dict(\\n                do_sample=do_sample if do_sample is not None else generating_args[\\\"do_sample\\\"],\\n                temperature=temperature if temperature is not None else generating_args[\\\"temperature\\\"],\\n                top_p=top_p if top_p is not None else generating_args[\\\"top_p\\\"],\\n                top_k=top_k if top_k is not None else generating_args[\\\"top_k\\\"],\\n                num_return_sequences=num_return_sequences,\\n                repetition_penalty=repetition_penalty\\n                if repetition_penalty is not None\\n                else generating_args[\\\"repetition_penalty\\\"],\\n                length_penalty=length_penalty if length_penalty is not None else generating_args[\\\"length_penalty\\\"],\\n                skip_special_tokens=skip_special_tokens\\n                if skip_special_tokens is not None\\n                else generating_args[\\\"skip_special_tokens\\\"],\\n                eos_token_id=template.get_stop_token_ids(tokenizer),\\n                pad_token_id=tokenizer.pad_token_id,\\n            )\\n        )\\n\\n        if isinstance(num_return_sequences, int) and num_return_sequences > 1:  # do_sample needs temperature > 0\\n            generating_args[\\\"do_sample\\\"] = True\\n            generating_args[\\\"temperature\\\"] = generating_args[\\\"temperature\\\"] or 1.0\\n\\n        if not generating_args[\\\"temperature\\\"]:\\n            generating_args[\\\"do_sample\\\"] = False\\n\\n        if not generating_args[\\\"do_sample\\\"]:\\n            generating_args.pop(\\\"temperature\\\", None)\\n            generating_args.pop(\\\"top_p\\\", None)\\n\\n        if max_length:\\n            generating_args.pop(\\\"max_new_tokens\\\", None)\\n            generating_args[\\\"max_length\\\"] = max_length\\n\\n        if max_new_tokens:\\n            generating_args.pop(\\\"max_length\\\", None)\\n            generating_args[\\\"max_new_tokens\\\"] = max_new_tokens\\n\\n        gen_kwargs = dict(\\n            inputs=inputs,\\n            attention_mask=attention_mask,\\n            generation_config=GenerationConfig(**generating_args),\\n        )\\n        if seed is not None:\\n            gen_kwargs[\\\"_seed\\\"] = seed\\n\\n        mm_inputs = template.mm_plugin.get_mm_inputs(**mm_input_dict, batch_ids=[prompt_ids], processor=processor)\\n        for key, value in mm_inputs.items():\\n            if isinstance(value, list) and isinstance(value[0], torch.Tensor):  # for pixtral inputs\\n                value = torch.stack(value)  # assume they have same sizes\\n            elif (\\n                isinstance(value, list) and isinstance(value[0], list) and isinstance(value[0][0], torch.Tensor)\\n            ):  # for minicpmv inputs\\n                value = torch.stack([torch.stack(v) for v in value])\\n            elif not isinstance(value, torch.Tensor):\\n                value = torch.tensor(value)\\n\\n            if torch.is_floating_point(value):  # cast data dtype for paligemma\\n                value = value.to(model.dtype)\\n\\n            if key == \\\"second_per_grid_ts\\\":  # qwen2.5vl special case\\n                gen_kwargs[key] = value.tolist()\\n            else:\\n                gen_kwargs[key] = value.to(model.device)\\n\\n        if getattr(model.config, \\\"model_type\\\", None) in [\\\"minicpmv\\\", \\\"minicpmo\\\"]:\\n            gen_kwargs[\\\"input_ids\\\"] = inputs\\n            gen_kwargs[\\\"tokenizer\\\"] = tokenizer\\n            if \\\"audio_feature_lens\\\" in mm_inputs:\\n                gen_kwargs[\\\"audio_feature_lens\\\"] = mm_inputs[\\\"audio_feature_lens\\\"]\\n\\n            gen_kwargs.pop(\\\"image_sizes\\\", None)\\n\\n        return gen_kwargs, prompt_length\\n\\n    @staticmethod\\n    @torch.inference_mode()\\n    def _chat(\\n        model: \\\"PreTrainedModel\\\",\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        template: \\\"Template\\\",\\n        generating_args: dict[str, Any],\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        input_kwargs: Optional[dict[str, Any]] = {},\\n    ) -> list[\\\"Response\\\"]:\\n        gen_kwargs, prompt_length = HuggingfaceEngine._process_args(\\n            model,\\n            tokenizer,\\n            processor,\\n            template,\\n            generating_args,\\n            messages,\\n            system,\\n            tools,\\n            images,\\n            videos,\\n            audios,\\n            input_kwargs,\\n        )\\n        seed = gen_kwargs.pop(\\\"_seed\\\", None)\\n        if seed is not None:\\n            set_seed(seed)\\n\\n        generate_output = model.generate(**gen_kwargs)\\n        if isinstance(generate_output, tuple):\\n            generate_output = generate_output[1][0]  # post-process the minicpm_o output\\n\\n        response_ids = generate_output[:, prompt_length:]\\n        response = tokenizer.batch_decode(\\n            response_ids,\\n            skip_special_tokens=getattr(gen_kwargs[\\\"generation_config\\\"], \\\"skip_special_tokens\\\", True),\\n            clean_up_tokenization_spaces=True,\\n        )\\n        results = []\\n        for i in range(len(response)):\\n            eos_index = (response_ids[i] == tokenizer.eos_token_id).nonzero()\\n            response_length = (eos_index[0].item() + 1) if len(eos_index) else len(response_ids[i])\\n            results.append(\\n                Response(\\n                    response_text=response[i],\\n                    response_length=response_length,\\n                    prompt_length=prompt_length,\\n                    finish_reason=\\\"stop\\\" if len(eos_index) else \\\"length\\\",\\n                )\\n            )\\n\\n        return results\\n\\n    @staticmethod\\n    @torch.inference_mode()\\n    def _stream_chat(\\n        model: \\\"PreTrainedModel\\\",\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        template: \\\"Template\\\",\\n        generating_args: dict[str, Any],\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        input_kwargs: Optional[dict[str, Any]] = {},\\n    ) -> Callable[[], str]:\\n        gen_kwargs, _ = HuggingfaceEngine._process_args(\\n            model,\\n            tokenizer,\\n            processor,\\n            template,\\n            generating_args,\\n            messages,\\n            system,\\n            tools,\\n            images,\\n            videos,\\n            audios,\\n            input_kwargs,\\n        )\\n        seed = gen_kwargs.pop(\\\"_seed\\\", None)\\n        if seed is not None:\\n            set_seed(seed)\\n\\n        streamer = TextIteratorStreamer(\\n            tokenizer,\\n            skip_prompt=True,\\n            skip_special_tokens=getattr(gen_kwargs[\\\"generation_config\\\"], \\\"skip_special_tokens\\\", True),\\n        )\\n        gen_kwargs[\\\"streamer\\\"] = streamer\\n        thread = Thread(target=model.generate, kwargs=gen_kwargs, daemon=True)\\n        thread.start()\\n\\n        def stream():\\n            try:\\n                return streamer.__next__()\\n            except StopIteration:\\n                raise StopAsyncIteration()\\n\\n        return stream\\n\\n    @staticmethod\\n    @torch.inference_mode()\\n    def _get_scores(\\n        model: \\\"PreTrainedModelWrapper\\\",\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        batch_input: list[str],\\n        input_kwargs: Optional[dict[str, Any]] = {},\\n    ) -> list[float]:\\n        max_length: Optional[int] = input_kwargs.pop(\\\"max_length\\\", None)\\n        device = getattr(model.pretrained_model, \\\"device\\\", \\\"cuda\\\")\\n        inputs: dict[str, torch.Tensor] = tokenizer(\\n            batch_input,\\n            padding=True,\\n            truncation=True,\\n            max_length=max_length or getattr(model.config, \\\"max_position_embeddings\\\", 1024),\\n            return_tensors=\\\"pt\\\",\\n            add_special_tokens=False,\\n        ).to(device)\\n        values: torch.Tensor = model(**inputs, return_dict=True, use_cache=False)[-1]\\n        scores = values.gather(dim=-1, index=(inputs[\\\"attention_mask\\\"].sum(dim=-1, keepdim=True) - 1))\\n        return scores\\n\\n    @override\\n    async def chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        if not self.can_generate:\\n            raise ValueError(\\\"The current model does not support `chat`.\\\")\\n\\n        input_args = (\\n            self.model,\\n            self.tokenizer,\\n            self.processor,\\n            self.template,\\n            self.generating_args,\\n            messages,\\n            system,\\n            tools,\\n            images,\\n            videos,\\n            audios,\\n            input_kwargs,\\n        )\\n        async with self.semaphore:\\n            return await asyncio.to_thread(self._chat, *input_args)\\n\\n    @override\\n    async def stream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncGenerator[str, None]:\\n        if not self.can_generate:\\n            raise ValueError(\\\"The current model does not support `stream_chat`.\\\")\\n\\n        input_args = (\\n            self.model,\\n            self.tokenizer,\\n            self.processor,\\n            self.template,\\n            self.generating_args,\\n            messages,\\n            system,\\n            tools,\\n            images,\\n            videos,\\n            audios,\\n            input_kwargs,\\n        )\\n        async with self.semaphore:\\n            stream = self._stream_chat(*input_args)\\n            while True:\\n                try:\\n                    yield await asyncio.to_thread(stream)\\n                except StopAsyncIteration:\\n                    break\\n\\n    @override\\n    async def get_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        if self.can_generate:\\n            raise ValueError(\\\"Cannot get scores using an auto-regressive model.\\\")\\n\\n        input_args = (self.model, self.tokenizer, batch_input, input_kwargs)\\n        async with self.semaphore:\\n            return await asyncio.to_thread(self._get_scores, *input_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/sglang_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8c56958ccb309bfe4774a78d2baf120f5f9d5c0fdb03ca65cdfba4f60c30a724\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport asyncio\\nimport atexit\\nimport json\\nfrom collections.abc import AsyncGenerator, AsyncIterator, Sequence\\nfrom typing import TYPE_CHECKING, Any, Optional, Union\\n\\nimport requests\\nfrom typing_extensions import override\\n\\nfrom ..data import get_template_and_fix_tokenizer\\nfrom ..extras import logging\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER, EngineName\\nfrom ..extras.misc import get_device_count, torch_gc\\nfrom ..extras.packages import is_sglang_available\\nfrom ..hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\nfrom ..model import load_config, load_tokenizer\\nfrom ..model.model_utils.quantization import QuantizationMethod\\nfrom .base_engine import BaseEngine, Response\\n\\n\\nif is_sglang_available():\\n    from sglang.utils import launch_server_cmd, terminate_process, wait_for_server  # type: ignore\\n\\n\\nif TYPE_CHECKING:\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass SGLangEngine(BaseEngine):\\n    \\\"\\\"\\\"Inference engine for SGLang models.\\n\\n    This class wraps the SGLang engine to provide a consistent interface for text generation\\n    that matches LLaMA Factory's requirements. It uses the SGLang HTTP server approach for\\n    better interaction and performance. The engine launches a server process and communicates\\n    with it via HTTP requests.\\n\\n    For more details on the SGLang HTTP server approach, see:\\n    https://docs.sglang.ai/backend/send_request.html\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        data_args: \\\"DataArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n    ) -> None:\\n        self.name = EngineName.SGLANG\\n        self.model_args = model_args\\n        config = load_config(model_args)  # may download model from ms hub\\n        if getattr(config, \\\"quantization_config\\\", None):  # gptq models should use float16\\n            quantization_config: dict[str, Any] = getattr(config, \\\"quantization_config\\\", None)\\n            quant_method = quantization_config.get(\\\"quant_method\\\", \\\"\\\")\\n            if quant_method == QuantizationMethod.GPTQ and model_args.infer_dtype == \\\"auto\\\":\\n                model_args.infer_dtype = \\\"float16\\\"\\n\\n        self.can_generate = finetuning_args.stage == \\\"sft\\\"\\n        tokenizer_module = load_tokenizer(model_args)\\n        self.tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n        self.processor = tokenizer_module[\\\"processor\\\"]\\n        self.tokenizer.padding_side = \\\"left\\\"\\n        self.template = get_template_and_fix_tokenizer(self.tokenizer, data_args)\\n        self.template.mm_plugin.expand_mm_tokens = False  # for sglang generate\\n        self.generating_args = generating_args.to_dict()\\n        if model_args.adapter_name_or_path is not None:\\n            self.lora_request = True\\n        else:\\n            self.lora_request = False\\n\\n        launch_cmd = [\\n            \\\"python3 -m sglang.launch_server\\\",\\n            f\\\"--model-path {model_args.model_name_or_path}\\\",\\n            f\\\"--dtype {model_args.infer_dtype}\\\",\\n            f\\\"--context-length {model_args.sglang_maxlen}\\\",\\n            f\\\"--mem-fraction-static {model_args.sglang_mem_fraction}\\\",\\n            f\\\"--tp-size {model_args.sglang_tp_size if model_args.sglang_tp_size != -1 else get_device_count() or 1}\\\",\\n            f\\\"--download-dir {model_args.cache_dir}\\\",\\n            \\\"--log-level error\\\",\\n        ]\\n        if self.lora_request:\\n            launch_cmd.extend(\\n                [\\n                    \\\"--max-loras-per-batch 1\\\",\\n                    f\\\"--lora-backend {model_args.sglang_lora_backend}\\\",\\n                    f\\\"--lora-paths lora0={model_args.adapter_name_or_path[0]}\\\",\\n                    \\\"--disable-radix-cache\\\",\\n                ]\\n            )\\n        launch_cmd = \\\" \\\".join(launch_cmd)\\n        logger.info_rank0(f\\\"Starting SGLang server with command: {launch_cmd}\\\")\\n        try:\\n            torch_gc()\\n            self.server_process, port = launch_server_cmd(launch_cmd)\\n            self.base_url = f\\\"http://localhost:{port}\\\"\\n            atexit.register(self._cleanup_server)\\n\\n            logger.info_rank0(f\\\"Waiting for SGLang server to be ready at {self.base_url}\\\")\\n            wait_for_server(self.base_url, timeout=300)\\n            logger.info_rank0(f\\\"SGLang server initialized successfully at {self.base_url}\\\")\\n            try:\\n                response = requests.get(f\\\"{self.base_url}/get_model_info\\\", timeout=5)\\n                if response.status_code == 200:\\n                    model_info = response.json()\\n                    logger.info(f\\\"SGLang server model info: {model_info}\\\")\\n            except Exception as e:\\n                logger.debug(f\\\"Note: could not get model info: {str(e)}\\\")\\n\\n        except Exception as e:\\n            logger.error(f\\\"Failed to start SGLang server: {str(e)}\\\")\\n            self._cleanup_server()  # make sure to clean up any started process\\n            raise RuntimeError(f\\\"SGLang server initialization failed: {str(e)}.\\\")\\n\\n    def _cleanup_server(self):\\n        r\\\"\\\"\\\"Clean up the server process when the engine is destroyed.\\\"\\\"\\\"\\n        if hasattr(self, \\\"server_process\\\") and self.server_process:\\n            try:\\n                logger.info(\\\"Terminating SGLang server process\\\")\\n                terminate_process(self.server_process)\\n                logger.info(\\\"SGLang server process terminated\\\")\\n            except Exception as e:\\n                logger.warning(f\\\"Error terminating SGLang server: {str(e)}\\\")\\n\\n    async def _generate(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncIterator[dict[str, Any]]:\\n        if images is not None and not any(IMAGE_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = IMAGE_PLACEHOLDER * len(images) + messages[0][\\\"content\\\"]\\n\\n        if videos is not None and not any(VIDEO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = VIDEO_PLACEHOLDER * len(videos) + messages[0][\\\"content\\\"]\\n\\n        if audios is not None and not any(AUDIO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = AUDIO_PLACEHOLDER * len(audios) + messages[0][\\\"content\\\"]\\n\\n        messages = self.template.mm_plugin.process_messages(\\n            messages, images or [], videos or [], audios or [], self.processor\\n        )\\n        paired_messages = messages + [{\\\"role\\\": \\\"assistant\\\", \\\"content\\\": \\\"\\\"}]\\n        prompt_ids, _ = self.template.encode_oneturn(self.tokenizer, paired_messages, system, tools)\\n        prompt_length = len(prompt_ids)\\n\\n        temperature: Optional[float] = input_kwargs.pop(\\\"temperature\\\", None)\\n        top_p: Optional[float] = input_kwargs.pop(\\\"top_p\\\", None)\\n        top_k: Optional[float] = input_kwargs.pop(\\\"top_k\\\", None)\\n        num_return_sequences: int = input_kwargs.pop(\\\"num_return_sequences\\\", 1)\\n        repetition_penalty: Optional[float] = input_kwargs.pop(\\\"repetition_penalty\\\", None)\\n        skip_special_tokens: Optional[bool] = input_kwargs.pop(\\\"skip_special_tokens\\\", None)\\n        max_length: Optional[int] = input_kwargs.pop(\\\"max_length\\\", None)\\n        max_new_tokens: Optional[int] = input_kwargs.pop(\\\"max_new_tokens\\\", None)\\n        seed: Optional[int] = input_kwargs.pop(\\\"seed\\\", None)\\n        stop: Optional[Union[str, list[str]]] = input_kwargs.pop(\\\"stop\\\", None)\\n\\n        if num_return_sequences != 1:\\n            raise NotImplementedError(\\\"SGLang only supports n=1.\\\")\\n\\n        if \\\"max_new_tokens\\\" in self.generating_args:\\n            max_tokens = self.generating_args[\\\"max_new_tokens\\\"]\\n        elif \\\"max_length\\\" in self.generating_args:\\n            if self.generating_args[\\\"max_length\\\"] > prompt_length:\\n                max_tokens = self.generating_args[\\\"max_length\\\"] - prompt_length\\n            else:\\n                max_tokens = 1\\n\\n        if max_length:\\n            max_tokens = max_length - prompt_length if max_length > prompt_length else 1\\n\\n        if max_new_tokens:\\n            max_tokens = max_new_tokens\\n\\n        sampling_params = {\\n            \\\"temperature\\\": temperature if temperature is not None else self.generating_args[\\\"temperature\\\"],\\n            \\\"top_p\\\": (top_p if top_p is not None else self.generating_args[\\\"top_p\\\"]) or 1.0,  # top_p must > 0\\n            \\\"top_k\\\": (top_k if top_k is not None else self.generating_args[\\\"top_k\\\"]) or -1,  # top_k must > 0\\n            \\\"stop\\\": stop,\\n            \\\"stop_token_ids\\\": self.template.get_stop_token_ids(self.tokenizer),\\n            \\\"max_new_tokens\\\": max_tokens,\\n            \\\"repetition_penalty\\\": (\\n                repetition_penalty if repetition_penalty is not None else self.generating_args[\\\"repetition_penalty\\\"]\\n            )\\n            or 1.0,  # repetition_penalty must > 0\\n            \\\"skip_special_tokens\\\": skip_special_tokens\\n            if skip_special_tokens is not None\\n            else self.generating_args[\\\"skip_special_tokens\\\"],\\n        }\\n        if seed is not None:\\n            sampling_params[\\\"seed\\\"] = seed\\n\\n        def stream_request():\\n            json_data = {\\n                \\\"input_ids\\\": prompt_ids,\\n                \\\"sampling_params\\\": sampling_params,\\n                \\\"stream\\\": True,\\n            }\\n            if self.lora_request:\\n                json_data[\\\"lora_request\\\"] = [\\\"lora0\\\"]\\n            response = requests.post(f\\\"{self.base_url}/generate\\\", json=json_data, stream=True)\\n            if response.status_code != 200:\\n                raise RuntimeError(f\\\"SGLang server error: {response.status_code}, {response.text}\\\")\\n\\n            for chunk in response.iter_lines(decode_unicode=False):\\n                chunk = str(chunk.decode(\\\"utf-8\\\"))\\n                if chunk == \\\"data: [DONE]\\\":\\n                    break\\n\\n                if chunk and chunk.startswith(\\\"data:\\\"):\\n                    yield json.loads(chunk[5:].strip(\\\"\\\\n\\\"))\\n\\n        return await asyncio.to_thread(stream_request)\\n\\n    @override\\n    async def chat(\\n        self,\\n        messages: Sequence[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[Sequence[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[Sequence[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[Sequence[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        final_output = None\\n        generator = await self._generate(messages, system, tools, images, videos, audios, **input_kwargs)\\n        for request_output in generator:\\n            final_output = request_output\\n\\n        results = [\\n            Response(\\n                response_text=final_output[\\\"text\\\"],\\n                response_length=final_output[\\\"meta_info\\\"][\\\"completion_tokens\\\"],\\n                prompt_length=final_output[\\\"meta_info\\\"][\\\"prompt_tokens\\\"],\\n                finish_reason=\\\"stop\\\" if final_output[\\\"meta_info\\\"][\\\"finish_reason\\\"] == \\\"stop\\\" else \\\"length\\\",\\n            )\\n        ]\\n        return results\\n\\n    @override\\n    async def stream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncGenerator[str, None]:\\n        generated_text = \\\"\\\"\\n        generator = await self._generate(messages, system, tools, images, videos, audios, **input_kwargs)\\n        for result in generator:\\n            delta_text = result[\\\"text\\\"][len(generated_text) :]\\n            generated_text = result[\\\"text\\\"]\\n            yield delta_text\\n\\n    @override\\n    async def get_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        raise NotImplementedError(\\\"SGLang engine does not support `get_scores`.\\\")\\n\\n    def __del__(self):\\n        r\\\"\\\"\\\"Ensure server is cleaned up when object is deleted.\\\"\\\"\\\"\\n        self._cleanup_server()\\n        try:\\n            atexit.unregister(self._cleanup_server)\\n        except Exception:\\n            pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/chat/vllm_engine.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0cad59eb0b6cc5146c6403cb16032395e9ecbc4391d2e5728235beef0d35f92c\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport uuid\\nfrom collections.abc import AsyncGenerator, AsyncIterator\\nfrom typing import TYPE_CHECKING, Any, Optional, Union\\n\\nfrom packaging import version\\nfrom typing_extensions import override\\n\\nfrom ..data import get_template_and_fix_tokenizer\\nfrom ..extras import logging\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER, EngineName\\nfrom ..extras.misc import get_device_count\\nfrom ..extras.packages import is_vllm_available\\nfrom ..model import load_config, load_tokenizer\\nfrom ..model.model_utils.quantization import QuantizationMethod\\nfrom ..model.model_utils.visual import LlavaMultiModalProjectorForYiVLForVLLM\\nfrom .base_engine import BaseEngine, Response\\n\\n\\nif is_vllm_available():\\n    from vllm import AsyncEngineArgs, AsyncLLMEngine, RequestOutput, SamplingParams\\n    from vllm.lora.request import LoRARequest\\n\\n\\nif TYPE_CHECKING:\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n    from ..hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass VllmEngine(BaseEngine):\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        data_args: \\\"DataArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n    ) -> None:\\n        self.name = EngineName.VLLM\\n        self.model_args = model_args\\n        config = load_config(model_args)  # may download model from ms hub\\n        if getattr(config, \\\"quantization_config\\\", None):  # gptq models should use float16\\n            quantization_config: dict[str, Any] = getattr(config, \\\"quantization_config\\\", None)\\n            quant_method = quantization_config.get(\\\"quant_method\\\", \\\"\\\")\\n            if quant_method == QuantizationMethod.GPTQ and model_args.infer_dtype == \\\"auto\\\":\\n                model_args.infer_dtype = \\\"float16\\\"\\n\\n        self.can_generate = finetuning_args.stage == \\\"sft\\\"\\n        tokenizer_module = load_tokenizer(model_args)\\n        self.tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n        self.processor = tokenizer_module[\\\"processor\\\"]\\n        self.tokenizer.padding_side = \\\"left\\\"\\n        self.template = get_template_and_fix_tokenizer(self.tokenizer, data_args)\\n        self.template.mm_plugin.expand_mm_tokens = False  # for vllm generate\\n        self.generating_args = generating_args.to_dict()\\n\\n        engine_args = {\\n            \\\"model\\\": model_args.model_name_or_path,\\n            \\\"trust_remote_code\\\": model_args.trust_remote_code,\\n            \\\"download_dir\\\": model_args.cache_dir,\\n            \\\"dtype\\\": model_args.infer_dtype,\\n            \\\"max_model_len\\\": model_args.vllm_maxlen,\\n            \\\"tensor_parallel_size\\\": get_device_count() or 1,\\n            \\\"gpu_memory_utilization\\\": model_args.vllm_gpu_util,\\n            \\\"disable_log_stats\\\": True,\\n            \\\"enforce_eager\\\": model_args.vllm_enforce_eager,\\n            \\\"enable_lora\\\": model_args.adapter_name_or_path is not None,\\n            \\\"max_lora_rank\\\": model_args.vllm_max_lora_rank,\\n        }\\n\\n        import vllm\\n\\n        if version.parse(vllm.__version__) <= version.parse(\\\"0.10.0\\\"):\\n            engine_args[\\\"disable_log_requests\\\"] = True\\n        else:\\n            engine_args[\\\"enable_log_requests\\\"] = False\\n\\n        if self.template.mm_plugin.__class__.__name__ != \\\"BasePlugin\\\":\\n            engine_args[\\\"limit_mm_per_prompt\\\"] = {\\\"image\\\": 4, \\\"video\\\": 2, \\\"audio\\\": 2}\\n\\n        if isinstance(model_args.vllm_config, dict):\\n            engine_args.update(model_args.vllm_config)\\n\\n        if getattr(config, \\\"is_yi_vl_derived_model\\\", None):\\n            import vllm.model_executor.models.llava\\n\\n            logger.info_rank0(\\\"Detected Yi-VL model, applying projector patch.\\\")\\n            vllm.model_executor.models.llava.LlavaMultiModalProjector = LlavaMultiModalProjectorForYiVLForVLLM\\n\\n        self.model = AsyncLLMEngine.from_engine_args(AsyncEngineArgs(**engine_args))\\n        if model_args.adapter_name_or_path is not None:\\n            self.lora_request = LoRARequest(\\\"default\\\", 1, model_args.adapter_name_or_path[0])\\n        else:\\n            self.lora_request = None\\n\\n    async def _generate(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncIterator[\\\"RequestOutput\\\"]:\\n        request_id = f\\\"chatcmpl-{uuid.uuid4().hex}\\\"\\n        if images is not None and not any(IMAGE_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = IMAGE_PLACEHOLDER * len(images) + messages[0][\\\"content\\\"]\\n\\n        if videos is not None and not any(VIDEO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = VIDEO_PLACEHOLDER * len(videos) + messages[0][\\\"content\\\"]\\n\\n        if audios is not None and not any(AUDIO_PLACEHOLDER in message[\\\"content\\\"] for message in messages):\\n            messages[0][\\\"content\\\"] = AUDIO_PLACEHOLDER * len(audios) + messages[0][\\\"content\\\"]\\n\\n        messages = self.template.mm_plugin.process_messages(\\n            messages, images or [], videos or [], audios or [], self.processor\\n        )\\n        paired_messages = messages + [{\\\"role\\\": \\\"assistant\\\", \\\"content\\\": \\\"\\\"}]\\n        prompt_ids, _ = self.template.encode_oneturn(self.tokenizer, paired_messages, system, tools)\\n        prompt_length = len(prompt_ids)\\n\\n        temperature: Optional[float] = input_kwargs.pop(\\\"temperature\\\", None)\\n        top_p: Optional[float] = input_kwargs.pop(\\\"top_p\\\", None)\\n        top_k: Optional[float] = input_kwargs.pop(\\\"top_k\\\", None)\\n        num_return_sequences: int = input_kwargs.pop(\\\"num_return_sequences\\\", 1)\\n        repetition_penalty: Optional[float] = input_kwargs.pop(\\\"repetition_penalty\\\", None)\\n        length_penalty: Optional[float] = input_kwargs.pop(\\\"length_penalty\\\", None)\\n        skip_special_tokens: Optional[bool] = input_kwargs.pop(\\\"skip_special_tokens\\\", None)\\n        max_length: Optional[int] = input_kwargs.pop(\\\"max_length\\\", None)\\n        max_new_tokens: Optional[int] = input_kwargs.pop(\\\"max_new_tokens\\\", None)\\n        seed: Optional[int] = input_kwargs.pop(\\\"seed\\\", None)\\n        stop: Optional[Union[str, list[str]]] = input_kwargs.pop(\\\"stop\\\", None)\\n\\n        if length_penalty is not None:\\n            logger.warning_rank0(\\\"Length penalty is not supported by the vllm engine yet.\\\")\\n\\n        if \\\"max_new_tokens\\\" in self.generating_args:\\n            max_tokens = self.generating_args[\\\"max_new_tokens\\\"]\\n        elif \\\"max_length\\\" in self.generating_args:\\n            if self.generating_args[\\\"max_length\\\"] > prompt_length:\\n                max_tokens = self.generating_args[\\\"max_length\\\"] - prompt_length\\n            else:\\n                max_tokens = 1\\n\\n        if max_length:\\n            max_tokens = max_length - prompt_length if max_length > prompt_length else 1\\n\\n        if max_new_tokens:\\n            max_tokens = max_new_tokens\\n\\n        sampling_kwargs = dict(\\n            n=num_return_sequences,\\n            repetition_penalty=(\\n                repetition_penalty if repetition_penalty is not None else self.generating_args[\\\"repetition_penalty\\\"]\\n            )\\n            or 1.0,  # repetition_penalty must > 0\\n            temperature=temperature if temperature is not None else self.generating_args[\\\"temperature\\\"],\\n            top_p=(top_p if top_p is not None else self.generating_args[\\\"top_p\\\"]) or 1.0,  # top_p must > 0\\n            top_k=(top_k if top_k is not None else self.generating_args[\\\"top_k\\\"]) or -1,  # top_k must > 0\\n            stop=stop,\\n            stop_token_ids=self.template.get_stop_token_ids(self.tokenizer),\\n            max_tokens=max_tokens,\\n            skip_special_tokens=skip_special_tokens\\n            if skip_special_tokens is not None\\n            else self.generating_args[\\\"skip_special_tokens\\\"],\\n        )\\n        if seed is not None:\\n            sampling_kwargs[\\\"seed\\\"] = seed\\n\\n        sampling_params = SamplingParams(**sampling_kwargs)\\n\\n        multi_modal_data = {}\\n        if images is not None:  # add image features\\n            multi_modal_data[\\\"image\\\"] = self.template.mm_plugin._regularize_images(\\n                images,\\n                image_max_pixels=self.model_args.image_max_pixels,\\n                image_min_pixels=self.model_args.image_min_pixels,\\n            )[\\\"images\\\"]\\n\\n        if videos is not None:\\n            multi_modal_data[\\\"video\\\"] = self.template.mm_plugin._regularize_videos(\\n                videos,\\n                image_max_pixels=self.model_args.video_max_pixels,\\n                image_min_pixels=self.model_args.video_min_pixels,\\n                video_fps=self.model_args.video_fps,\\n                video_maxlen=self.model_args.video_maxlen,\\n            )[\\\"videos\\\"]\\n\\n        if audios is not None:\\n            audio_data = self.template.mm_plugin._regularize_audios(\\n                audios,\\n                sampling_rate=self.model_args.audio_sampling_rate,\\n            )\\n            multi_modal_data[\\\"audio\\\"] = zip(audio_data[\\\"audios\\\"], audio_data[\\\"sampling_rates\\\"])\\n\\n        result_generator = self.model.generate(\\n            {\\\"prompt_token_ids\\\": prompt_ids, \\\"multi_modal_data\\\": multi_modal_data or None},\\n            sampling_params=sampling_params,\\n            request_id=request_id,\\n            lora_request=self.lora_request,\\n        )\\n        return result_generator\\n\\n    @override\\n    async def chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> list[\\\"Response\\\"]:\\n        final_output = None\\n        generator = await self._generate(messages, system, tools, images, videos, audios, **input_kwargs)\\n        async for request_output in generator:\\n            final_output = request_output\\n\\n        results = []\\n        for output in final_output.outputs:\\n            results.append(\\n                Response(\\n                    response_text=output.text,\\n                    response_length=len(output.token_ids),\\n                    prompt_length=len(final_output.prompt_token_ids),\\n                    finish_reason=output.finish_reason,\\n                )\\n            )\\n\\n        return results\\n\\n    @override\\n    async def stream_chat(\\n        self,\\n        messages: list[dict[str, str]],\\n        system: Optional[str] = None,\\n        tools: Optional[str] = None,\\n        images: Optional[list[\\\"ImageInput\\\"]] = None,\\n        videos: Optional[list[\\\"VideoInput\\\"]] = None,\\n        audios: Optional[list[\\\"AudioInput\\\"]] = None,\\n        **input_kwargs,\\n    ) -> AsyncGenerator[str, None]:\\n        generated_text = \\\"\\\"\\n        generator = await self._generate(messages, system, tools, images, videos, audios, **input_kwargs)\\n        async for result in generator:\\n            delta_text = result.outputs[0].text[len(generated_text) :]\\n            generated_text = result.outputs[0].text\\n            yield delta_text\\n\\n    @override\\n    async def get_scores(\\n        self,\\n        batch_input: list[str],\\n        **input_kwargs,\\n    ) -> list[float]:\\n        raise NotImplementedError(\\\"vLLM engine does not support `get_scores`.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/cli.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d32b69e0b379718a9d0cf7bbf7032e6104f234cf53b13ad9e276a4a3fe7530d8\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\ndef main():\\n    from .extras.misc import is_env_enabled\\n\\n    if is_env_enabled(\\\"USE_V1\\\"):\\n        from .v1 import launcher\\n    else:\\n        from . import launcher\\n\\n    launcher.launch()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    from multiprocessing import freeze_support\\n\\n    freeze_support()\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e00ca55d2a9a73063c69a334d1595480b1802ace8a1589f5e59fa40493021c3a\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .collator import (\\n    KTODataCollatorWithPadding,\\n    MultiModalDataCollatorForSeq2Seq,\\n    PairwiseDataCollatorWithPadding,\\n    SFTDataCollatorWith4DAttentionMask,\\n)\\nfrom .data_utils import Role, split_dataset\\nfrom .loader import get_dataset\\nfrom .template import TEMPLATES, Template, get_template_and_fix_tokenizer\\n\\n\\n__all__ = [\\n    \\\"TEMPLATES\\\",\\n    \\\"KTODataCollatorWithPadding\\\",\\n    \\\"MultiModalDataCollatorForSeq2Seq\\\",\\n    \\\"PairwiseDataCollatorWithPadding\\\",\\n    \\\"Role\\\",\\n    \\\"SFTDataCollatorWith4DAttentionMask\\\",\\n    \\\"Template\\\",\\n    \\\"get_dataset\\\",\\n    \\\"get_template_and_fix_tokenizer\\\",\\n    \\\"split_dataset\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/collator.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d9c0c4d5583001c9e2f9825de7dbf2f57cd7c724d0b3c70b4e9cd61cda08edb2\",\"content\":\"# Copyright 2025 OpenAccess AI Collective and the LlamaFactory team.\\n#\\n# This code is inspired by the OpenAccess AI Collective's axolotl library.\\n# https://github.com/OpenAccess-AI-Collective/axolotl/blob/main/src/axolotl/monkeypatch/utils.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport copy\\nimport inspect\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Any, Literal, Optional\\n\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\nfrom peft import PeftModel\\nfrom transformers import DataCollatorForSeq2Seq\\n\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IGNORE_INDEX, IMAGE_PLACEHOLDER, MROPE_MODELS\\nfrom ..extras.packages import is_pillow_available\\n\\n\\nif is_pillow_available():\\n    from PIL import Image\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import ProcessorMixin\\n\\n    from .template import Template\\n\\n\\ndef _slice_mm_inputs_for_sample(\\n    mm_inputs: dict[str, Any],\\n    batch_imglens: list[int],\\n    batch_vidlens: list[int],\\n    batch_idx: int,\\n    images_per_subseq: Optional[list[int]] = None,\\n    videos_per_subseq: Optional[list[int]] = None,\\n    subseq_idx: Optional[int] = None,\\n) -> dict[str, Any]:\\n    r\\\"\\\"\\\"Slice mm_inputs for one batch sample, optionally for a single sub-sequence when packing.\\n\\n    image_grid_thw / video_grid_thw have shape [num_items, 3]. Indices for sample batch_idx\\n    are batch_imglens[batch_idx] images and batch_vidlens[batch_idx] videos. When subseq_idx\\n    is given, further restrict to that sub-seq's counts via packed_*_counts.\\n    has_dummy_image=True means only batch[0] will be concated with fake image and no multimodal data.\\n    \\\"\\\"\\\"\\n    image_start_idx = sum(batch_imglens[:batch_idx])\\n    image_end_idx = sum(batch_imglens[: batch_idx + 1])\\n    video_start_idx = sum(batch_vidlens[:batch_idx])\\n    video_end_idx = sum(batch_vidlens[: batch_idx + 1])\\n\\n    if subseq_idx is not None and images_per_subseq is not None:\\n        image_start_idx += sum(images_per_subseq[:subseq_idx])\\n        image_end_idx = image_start_idx + images_per_subseq[subseq_idx]\\n\\n    if subseq_idx is not None and videos_per_subseq is not None:\\n        video_start_idx += sum(videos_per_subseq[:subseq_idx])\\n        video_end_idx = video_start_idx + videos_per_subseq[subseq_idx]\\n\\n    sliced_mm_inputs: dict[str, Any] = {}\\n    key_to_slice_meta = {\\n        \\\"image_grid_thw\\\": (image_start_idx, image_end_idx, True),\\n        \\\"video_grid_thw\\\": (video_start_idx, video_end_idx, True),\\n        \\\"second_per_grid_ts\\\": (video_start_idx, video_end_idx, False),  # qwen2.5vl\\n        \\\"video_second_per_grid\\\": (video_start_idx, video_end_idx, False),  # qwen omni\\n    }\\n\\n    for key, (start_idx, end_idx, assign_none_when_empty) in key_to_slice_meta.items():\\n        if key not in mm_inputs:\\n            continue\\n\\n        mm_value = mm_inputs[key]\\n        if mm_value is not None and end_idx > start_idx:\\n            sliced_mm_inputs[key] = mm_value[start_idx:end_idx]\\n        elif assign_none_when_empty:\\n            sliced_mm_inputs[key] = None\\n\\n    return sliced_mm_inputs\\n\\n\\ndef prepare_4d_attention_mask(attention_mask_with_indices: \\\"torch.Tensor\\\", dtype: \\\"torch.dtype\\\") -> \\\"torch.Tensor\\\":\\n    r\\\"\\\"\\\"Expand 2d attention mask to 4d attention mask.\\n\\n    Expand the attention mask with indices from (batch_size, seq_len) to (batch_size, 1, seq_len, seq_len),\\n    handle packed sequences and transforms the mask to lower triangular form to prevent future peeking.\\n\\n    e.g.\\n    ```python\\n    # input\\n    [[1, 1, 2, 2, 2, 0]]\\n    # output\\n    [\\n        [\\n            [\\n                [o, x, x, x, x, x],\\n                [o, o, x, x, x, x],\\n                [x, x, o, x, x, x],\\n                [x, x, o, o, x, x],\\n                [x, x, o, o, o, x],\\n                [x, x, x, x, x, x],\\n            ]\\n        ]\\n    ]\\n    ```\\n    where `o` equals to `0.0`, `x` equals to `min_dtype`.\\n    \\\"\\\"\\\"\\n    _, seq_len = attention_mask_with_indices.size()\\n    min_dtype = torch.finfo(dtype).min\\n    zero_tensor = torch.tensor(0, dtype=dtype)\\n\\n    # Create a non-padding mask.\\n    non_padding_mask = (attention_mask_with_indices != 0).unsqueeze(1).unsqueeze(2)\\n    # Create indices for comparison.\\n    indices = attention_mask_with_indices.unsqueeze(1).unsqueeze(2)  # [bsz, 1, 1, seq_len]\\n    indices_t = attention_mask_with_indices.unsqueeze(1).unsqueeze(3)  # [bsz, 1, seq_len, 1]\\n    # Create a lower triangular mask.\\n    tril_mask = torch.tril(torch.ones((seq_len, seq_len), dtype=torch.bool))\\n    attention_mask_4d = (indices == indices_t) & non_padding_mask & tril_mask\\n    # Invert the attention mask.\\n    attention_mask_4d = torch.where(attention_mask_4d, zero_tensor, min_dtype)\\n    return attention_mask_4d\\n\\n\\n@dataclass\\nclass MultiModalDataCollatorForSeq2Seq(DataCollatorForSeq2Seq):\\n    r\\\"\\\"\\\"Data collator that supports VLMs.\\n\\n    Features should contain input_ids, attention_mask, labels, and optionally contain images, videos and audios.\\n    \\\"\\\"\\\"\\n\\n    template: Optional[\\\"Template\\\"] = None\\n    processor: Optional[\\\"ProcessorMixin\\\"] = None\\n\\n    def __post_init__(self):\\n        if self.template is None:\\n            raise ValueError(\\\"Template is required for MultiModalDataCollator.\\\")\\n\\n        if isinstance(self.model, PeftModel):\\n            self.model = self.model.base_model.model\\n\\n        if getattr(getattr(self.model, \\\"config\\\", None), \\\"model_type\\\", None) == \\\"moss_vl\\\":\\n            self.get_rope_func = None  # MOSS-VL computes its own XRoPE positions in model.forward.\\n        elif self.model is not None and hasattr(self.model, \\\"get_rope_index\\\"):  # for qwen2vl mrope\\n            self.get_rope_func = self.model.get_rope_index  # transformers < 4.52.0 or qwen2.5 omni\\n        elif self.model is not None and hasattr(self.model, \\\"model\\\") and hasattr(self.model.model, \\\"get_rope_index\\\"):\\n            self.get_rope_func = self.model.model.get_rope_index  # transformers >= 4.52.0\\n        else:\\n            self.get_rope_func = None\\n\\n    def _compute_rope_position_ids(self, features: dict[str, \\\"torch.Tensor\\\"], mm_inputs: dict[str, Any]) -> None:\\n        r\\\"\\\"\\\"Compute position_ids and rope_deltas via get_rope_func for VLMs.\\\"\\\"\\\"\\n        rope_index_kwargs = {\\n            \\\"input_ids\\\": features[\\\"input_ids\\\"],\\n            \\\"image_grid_thw\\\": mm_inputs.get(\\\"image_grid_thw\\\"),\\n            \\\"video_grid_thw\\\": mm_inputs.get(\\\"video_grid_thw\\\"),\\n            \\\"attention_mask\\\": (features[\\\"attention_mask\\\"] >= 1).float(),\\n        }\\n        if features[\\\"attention_mask\\\"].sum() == 0:  # for pad tokens\\n            seq_len = features[\\\"input_ids\\\"].shape[-1]\\n            features[\\\"position_ids\\\"] = (\\n                torch.arange(seq_len).view(1, 1, seq_len).expand(3, *features[\\\"input_ids\\\"].shape).contiguous()\\n            )\\n            features[\\\"rope_deltas\\\"] = torch.zeros(features[\\\"input_ids\\\"].shape[0])\\n            return\\n\\n        if \\\"mm_token_type_ids\\\" in inspect.signature(self.get_rope_func).parameters:\\n            image_token_id = getattr(self.model.config, \\\"image_token_id\\\", None)\\n            video_token_id = getattr(self.model.config, \\\"video_token_id\\\", None)\\n            if image_token_id is not None or video_token_id is not None:\\n                mm_token_type_ids = torch.zeros_like(features[\\\"input_ids\\\"])\\n                if image_token_id is not None:\\n                    mm_token_type_ids[features[\\\"input_ids\\\"] == image_token_id] = 1\\n                if video_token_id is not None:\\n                    mm_token_type_ids[features[\\\"input_ids\\\"] == video_token_id] = 2\\n                rope_index_kwargs[\\\"mm_token_type_ids\\\"] = mm_token_type_ids\\n\\n        if \\\"second_per_grid_ts\\\" in mm_inputs:  # for qwen2vl\\n            rope_index_kwargs[\\\"second_per_grid_ts\\\"] = mm_inputs.get(\\\"second_per_grid_ts\\\")\\n        elif \\\"video_second_per_grid\\\" in mm_inputs:  # for qwen2.5 omni\\n            rope_index_kwargs[\\\"second_per_grids\\\"] = mm_inputs.get(\\\"video_second_per_grid\\\")\\n\\n        if getattr(self.model.config, \\\"model_type\\\", None) in [\\\"qwen2_5_omni_thinker\\\", \\\"qwen3_omni_moe_thinker\\\"]:\\n            rope_index_kwargs[\\\"use_audio_in_video\\\"] = getattr(self.processor, \\\"use_audio_in_video\\\", False)\\n            feature_attention_mask = mm_inputs.get(\\\"feature_attention_mask\\\", None)\\n            if feature_attention_mask is not None:  # FIXME: need to get video image lengths\\n                audio_feature_lengths = torch.sum(feature_attention_mask, dim=1)\\n                rope_index_kwargs[\\\"audio_seqlens\\\"] = audio_feature_lengths  # prepare for input\\n\\n            features[\\\"position_ids\\\"], rope_deltas = self.get_rope_func(**rope_index_kwargs)\\n            features[\\\"rope_deltas\\\"] = rope_deltas - (1 - rope_index_kwargs[\\\"attention_mask\\\"]).sum(dim=-1).unsqueeze(-1)\\n        else:  # for qwen vl\\n            features[\\\"position_ids\\\"], features[\\\"rope_deltas\\\"] = self.get_rope_func(**rope_index_kwargs)\\n\\n    def _compute_rope_position_ids_with_packing(\\n        self,\\n        features: dict[str, \\\"torch.Tensor\\\"],\\n        mm_inputs: dict[str, Any],\\n        packing_params_list: list[dict[str, Any] | None],\\n        batch_imglens: list[int],\\n        batch_vidlens: list[int],\\n        batch_audlens: list[int],\\n        has_dummy_image: bool,\\n    ) -> None:\\n        r\\\"\\\"\\\"Compute position_ids and rope_deltas per sample (or per sub-sequence when packed), then merge and validate.\\\"\\\"\\\"\\n        bsz = features[\\\"input_ids\\\"].size(0)\\n        seq_len = features[\\\"input_ids\\\"].size(1)\\n        all_position_ids: list[torch.Tensor] = []\\n        all_rope_deltas: list[torch.Tensor] = []\\n\\n        if has_dummy_image:\\n            # for [0, seq_len] = [0, unpadded_length + right_padding_length + fake_input_ids_len + collator_padding_length]\\n            # FIXME: maybe right_padding_length is large, with improper max_cutoff_len\\n            unpadded_length = int(features[\\\"attention_mask\\\"][0].bool().sum().item())\\n            right_padding_length = int((packing_params_list[0] or {}).get(\\\"right_padding_length\\\") or 0)\\n            fake_input_padding_length = max(0, seq_len - unpadded_length - right_padding_length)\\n            # avoid continual cuseqlens breaking varlen attention @kuangdd\\n            # https://github.com/hiyouga/LlamaFactory/issues/10452\\n            dummy_image_right_padding_mrope = (\\n                torch.arange(fake_input_padding_length)\\n                .view(1, 1, fake_input_padding_length)\\n                .expand(3, bsz, fake_input_padding_length)\\n            )\\n            dummy_image_right_padding_attention_mask = torch.zeros((bsz, fake_input_padding_length))\\n            assert self.tokenizer.padding_side == \\\"right\\\", \\\"padding_side should be right when fake image is injected\\\"\\n            dummy_mm_inputs = copy.deepcopy(mm_inputs)\\n\\n        for sample_idx in range(bsz):\\n            sample_packing = (packing_params_list[sample_idx] or {}) if sample_idx < len(packing_params_list) else {}\\n            sequence_boundaries = sample_packing.get(\\\"sequence_boundaries\\\")\\n            num_sub_seqs = (\\n                (len(sequence_boundaries) - 1) if sequence_boundaries and len(sequence_boundaries) > 1 else 1\\n            )\\n            image_subseq_ids = sample_packing.get(\\\"image_subseq_ids\\\") or []\\n            video_subseq_ids = sample_packing.get(\\\"video_subseq_ids\\\") or []\\n            images_per_subseq = (\\n                [image_subseq_ids.count(i) for i in range(num_sub_seqs)]\\n                if image_subseq_ids and num_sub_seqs > 1\\n                else None\\n            )\\n            videos_per_subseq = (\\n                [video_subseq_ids.count(i) for i in range(num_sub_seqs)]\\n                if video_subseq_ids and num_sub_seqs > 1\\n                else None\\n            )\\n            if has_dummy_image:\\n                mm_inputs = {}\\n\\n            if num_sub_seqs <= 1:\\n                sample_features = {\\n                    \\\"input_ids\\\": features[\\\"input_ids\\\"],\\n                    \\\"attention_mask\\\": features[\\\"attention_mask\\\"][sample_idx : sample_idx + 1],\\n                }\\n                mm_inputs_for_sample = _slice_mm_inputs_for_sample(\\n                    mm_inputs, batch_imglens, batch_vidlens, sample_idx=sample_idx\\n                )\\n                self._compute_rope_position_ids(sample_features, mm_inputs_for_sample)\\n                all_position_ids.append(sample_features[\\\"position_ids\\\"])\\n                all_rope_deltas.append(sample_features[\\\"rope_deltas\\\"])\\n            else:\\n                # when we do packing, don't need rope_deltas when training.\\n                sample_position_ids: list[torch.Tensor] = []\\n                for subseq_idx in range(num_sub_seqs):\\n                    subseq_start = sequence_boundaries[subseq_idx]\\n                    subseq_end = sequence_boundaries[subseq_idx + 1]\\n                    subseq_features = {\\n                        \\\"input_ids\\\": features[\\\"input_ids\\\"][sample_idx : sample_idx + 1, subseq_start:subseq_end],\\n                        \\\"attention_mask\\\": features[\\\"attention_mask\\\"][\\n                            sample_idx : sample_idx + 1, subseq_start:subseq_end\\n                        ],\\n                    }\\n                    mm_inputs_for_subseq = _slice_mm_inputs_for_sample(\\n                        mm_inputs,\\n                        batch_imglens,\\n                        batch_vidlens,\\n                        sample_idx,\\n                        images_per_subseq,\\n                        videos_per_subseq,\\n                        subseq_idx,\\n                    )\\n                    self._compute_rope_position_ids(subseq_features, mm_inputs_for_subseq)\\n                    sample_position_ids.append(subseq_features[\\\"position_ids\\\"])\\n\\n                all_position_ids.append(torch.cat(sample_position_ids, dim=-1))\\n\\n        batch_dim_for_position_ids = 1 if all_position_ids[0].dim() == 3 else 0\\n\\n        features[\\\"position_ids\\\"] = torch.cat(all_position_ids, dim=batch_dim_for_position_ids)\\n        if has_dummy_image:\\n            mm_inputs = dummy_mm_inputs\\n\\n        expected_position_ids_shape = (\\n            (bsz, seq_len)\\n            if all_position_ids[0].dim() == 2\\n            else (\\n                all_position_ids[0].size(0),\\n                bsz,\\n                seq_len,\\n            )\\n        )\\n        # Check if position_ids shape matches expected shape.\\n        # for further usage, we should padding to the right when some padding token on the right.\\n        if has_dummy_image:\\n            features[\\\"position_ids\\\"] = torch.cat([features[\\\"position_ids\\\"], dummy_image_right_padding_mrope], dim=-1)\\n            features[\\\"attention_mask\\\"] = torch.cat(\\n                [features[\\\"attention_mask\\\"], dummy_image_right_padding_attention_mask], dim=-1\\n            )\\n\\n        # Mirror the non-FA2 packing fix (#10737) for the packed-mrope path. The merged position_ids\\n        # is built from per-subseq sequence_boundaries, which end at cutoff_len, while\\n        # `DataCollatorForSeq2Seq(pad_to_multiple_of=...)` right-pads input_ids/attention_mask past\\n        # cutoff_len. Right-pad the trailing (masked) positions with 0 so the merged position_ids\\n        # matches seq_len before validating. Works for both 2D and 3D (mrope) position_ids since the\\n        # sequence axis is last, and is idempotent with the has_dummy_image cat above.\\n        pad_len = seq_len - features[\\\"position_ids\\\"].shape[-1]\\n        if pad_len > 0:\\n            features[\\\"position_ids\\\"] = F.pad(features[\\\"position_ids\\\"], (0, pad_len), value=0)\\n\\n        if features[\\\"position_ids\\\"].shape != expected_position_ids_shape:\\n            raise ValueError(\\n                \\\"Merged position_ids shape mismatch: \\\"\\n                f\\\"got {features['position_ids'].shape}, expected {expected_position_ids_shape}.\\\"\\n            )\\n\\n    def __call__(self, features: list[dict[str, Any]]) -> dict[str, \\\"torch.Tensor\\\"]:\\n        model_type = getattr(getattr(self.model, \\\"config\\\", None), \\\"model_type\\\", None)\\n        is_moss_vl = model_type == \\\"moss_vl\\\"\\n        batch_images, batch_videos, batch_audios = [], [], []\\n        batch_imglens, batch_vidlens, batch_audlens, batch_input_ids = [], [], [], []\\n        packing_params_list: list[dict[str, Any] | None] = []\\n        for feature in features:\\n            images = feature.pop(\\\"images\\\", None) or []\\n            videos = feature.pop(\\\"videos\\\", None) or []\\n            audios = feature.pop(\\\"audios\\\", None) or []\\n            batch_images.extend(images)\\n            batch_videos.extend(videos)\\n            batch_audios.extend(audios)\\n            batch_imglens.append(len(images))\\n            batch_vidlens.append(len(videos))\\n            batch_audlens.append(len(audios))\\n            batch_input_ids.append(feature[\\\"input_ids\\\"])\\n            packing_params_list.append(feature.pop(\\\"packing_params\\\", None))\\n\\n        fake_input_ids = []\\n        has_dummy_image = False\\n        if (\\n            self.template.mm_plugin.image_token is not None\\n            and sum(batch_imglens) == 0\\n            and sum(batch_vidlens) == 0\\n            and not is_moss_vl  # MOSS-VL builds one native zero-valued dummy per text-only sample in its plugin.\\n        ):  # avoid process hanging in zero3/fsdp case\\n            fake_messages = [{\\\"role\\\": \\\"user\\\", \\\"content\\\": IMAGE_PLACEHOLDER}]\\n            fake_images = [Image.new(\\\"RGB\\\", (64, 64), (255, 255, 255))]\\n            fake_messages = self.template.mm_plugin.process_messages(\\n                fake_messages, fake_images, [], [], self.processor\\n            )\\n            _fake_input_ids = self.tokenizer.encode(fake_messages[0][\\\"content\\\"], add_special_tokens=False)\\n            _fake_input_ids, _ = self.template.mm_plugin.process_token_ids(\\n                _fake_input_ids, None, fake_images, [], [], self.tokenizer, self.processor\\n            )\\n            fake_input_ids.extend(_fake_input_ids)\\n            batch_images = fake_images\\n            batch_imglens[0] = 1\\n            has_dummy_image = True\\n\\n        if (\\n            self.template.mm_plugin.audio_token is not None and sum(batch_audlens) == 0\\n        ):  # avoid process hanging in zero3/fsdp case\\n            fake_messages = [{\\\"role\\\": \\\"user\\\", \\\"content\\\": AUDIO_PLACEHOLDER}]\\n            fake_audios = [np.zeros(1600)]\\n            fake_messages = self.template.mm_plugin.process_messages(\\n                fake_messages, [], [], fake_audios, self.processor\\n            )\\n            _fake_input_ids = self.tokenizer.encode(fake_messages[0][\\\"content\\\"], add_special_tokens=False)\\n            _fake_input_ids, _ = self.template.mm_plugin.process_token_ids(\\n                _fake_input_ids, None, [], [], fake_audios, self.tokenizer, self.processor\\n            )\\n            fake_input_ids.extend(_fake_input_ids)\\n            batch_audios = fake_audios\\n            batch_audlens[0] = 1\\n\\n        if len(fake_input_ids) != 0:\\n            if self.tokenizer.padding_side == \\\"right\\\":\\n                features[0][\\\"input_ids\\\"] = features[0][\\\"input_ids\\\"] + fake_input_ids\\n                features[0][\\\"attention_mask\\\"] = features[0][\\\"attention_mask\\\"] + [0] * len(fake_input_ids)\\n                features[0][\\\"labels\\\"] = features[0][\\\"labels\\\"] + [IGNORE_INDEX] * len(fake_input_ids)\\n            else:\\n                features[0][\\\"input_ids\\\"] = fake_input_ids + features[0][\\\"input_ids\\\"]\\n                features[0][\\\"attention_mask\\\"] = [0] * len(fake_input_ids) + features[0][\\\"attention_mask\\\"]\\n                features[0][\\\"labels\\\"] = [IGNORE_INDEX] * len(fake_input_ids) + features[0][\\\"labels\\\"]\\n\\n            batch_input_ids[0] = features[0][\\\"input_ids\\\"]\\n\\n        mm_inputs = self.template.mm_plugin.get_mm_inputs(\\n            batch_images,\\n            batch_videos,\\n            batch_audios,\\n            batch_imglens,\\n            batch_vidlens,\\n            batch_audlens,\\n            batch_input_ids,\\n            self.processor,\\n        )\\n        if \\\"token_type_ids\\\" in mm_inputs:\\n            token_type_ids = mm_inputs.pop(\\\"token_type_ids\\\")\\n            for i, feature in enumerate(features):\\n                feature[\\\"token_type_ids\\\"] = token_type_ids[i]\\n\\n        if \\\"mm_token_type_ids\\\" in mm_inputs:  # need tensor-like for gemma4\\n            mm_token_type_ids = mm_inputs.pop(\\\"mm_token_type_ids\\\")\\n            max_len = max(len(ids) for ids in mm_token_type_ids)\\n            padded = []\\n            for ids in mm_token_type_ids:\\n                pad_len = max_len - len(ids)\\n                if self.tokenizer.padding_side == \\\"right\\\":\\n                    padded.append(ids + [0] * pad_len)\\n                else:\\n                    padded.append([0] * pad_len + ids)\\n\\n            mm_inputs[\\\"mm_token_type_ids\\\"] = torch.tensor(padded, dtype=torch.long)\\n\\n        features: dict[str, torch.Tensor] = super().__call__(features)\\n\\n        bsz, seq_len = features[\\\"input_ids\\\"].shape[:2]\\n        is_omni = model_type in [\\n            \\\"qwen2_5_omni_thinker\\\",\\n            \\\"qwen3_omni_moe_thinker\\\",\\n        ]\\n\\n        if self.get_rope_func is not None:\\n            # for mmrope situation, we should calculate position_ids and rope_deltas per sample.\\n            # When neat_packing is on, each sample has packing_params; None means no packing for that sample.\\n            boundaries_list = [p.get(\\\"sequence_boundaries\\\") if p is not None else None for p in packing_params_list]\\n            has_packing = any(b is not None and len(b) > 2 for b in boundaries_list)\\n            if has_dummy_image and has_packing:\\n                # FIXME: too tricky, need to be refactored @kuangdd\\n                features[\\\"has_dummy_image\\\"] = True\\n\\n            # When fake image/audio was injected, sequence_boundaries no longer match the tensor; use non-packing path.\\n            if not has_packing:\\n                self._compute_rope_position_ids(features, mm_inputs)\\n            else:\\n                if is_omni:  # TODO: support omni models for packed sequences @kuangdd\\n                    raise RuntimeError(\\\"Omni models are not supported for packed sequences for now.\\\")\\n\\n                self._compute_rope_position_ids_with_packing(\\n                    features,\\n                    mm_inputs,\\n                    packing_params_list,\\n                    batch_imglens,\\n                    batch_vidlens,\\n                    batch_audlens,\\n                    has_dummy_image,\\n                )\\n\\n            # For transformers compatibility, after https://github.com/huggingface/transformers/issues/39400\\n            if features[\\\"position_ids\\\"].dim() == 3:\\n                features[\\\"position_ids\\\"] = torch.cat(\\n                    [features[\\\"position_ids\\\"][0].unsqueeze(0), features[\\\"position_ids\\\"]], dim=0\\n                )\\n\\n        if (\\n            self.model is not None\\n            and getattr(self.model.config, \\\"model_type\\\", None) in MROPE_MODELS\\n            and (\\\"position_ids\\\" not in features or features[\\\"position_ids\\\"].dim() != 3)\\n        ):\\n            raise ValueError(f\\\"{self.model.config.model_type} requires 3D position ids for mrope.\\\")\\n\\n        if (\\n            \\\"cross_attention_mask\\\" in mm_inputs and mm_inputs[\\\"cross_attention_mask\\\"].dtype != torch.bool\\n        ):  # for mllama inputs when pad_to_multiple_of is enabled\\n            cross_attention_mask = mm_inputs.pop(\\\"cross_attention_mask\\\")\\n            seq_len = features[\\\"input_ids\\\"].size(1)\\n            orig_len = cross_attention_mask.size(1)\\n            mm_inputs[\\\"cross_attention_mask\\\"] = F.pad(cross_attention_mask, (0, 0, 0, 0, 0, seq_len - orig_len))\\n\\n        if is_moss_vl:\\n            mm_inputs = self.template.mm_plugin.post_process_mossvl_inputs(features, mm_inputs, self.processor)\\n\\n        features.update(mm_inputs)\\n\\n        if \\\"image_bound\\\" in features:  # for minicpmv inputs\\n            bsz, seq_length = features[\\\"input_ids\\\"].shape\\n            features[\\\"position_ids\\\"] = torch.arange(seq_length).long().repeat(bsz, 1)\\n            return {\\\"data\\\": features, \\\"input_ids\\\": features[\\\"input_ids\\\"], \\\"labels\\\": features[\\\"labels\\\"]}\\n\\n        return features\\n\\n\\n@dataclass\\nclass SFTDataCollatorWith4DAttentionMask(MultiModalDataCollatorForSeq2Seq):\\n    r\\\"\\\"\\\"Data collator for 4d attention mask.\\\"\\\"\\\"\\n\\n    block_diag_attn: bool = False\\n    attn_implementation: Literal[\\\"eager\\\", \\\"sdpa\\\", \\\"flash_attention_2\\\"] = \\\"eager\\\"\\n    compute_dtype: \\\"torch.dtype\\\" = torch.float32\\n    neat_packing: bool = False\\n\\n    def __post_init__(self):\\n        super().__post_init__()\\n        if self.neat_packing and self.attn_implementation == \\\"flash_attention_2\\\":\\n            if self.model is not None and getattr(self.model.config, \\\"model_type\\\", None) in [\\\"gemma4\\\", \\\"gpt_oss\\\"]:\\n                raise ValueError(\\\"Neat packing is not supported for gemma4, gpt_oss models for now.\\\")\\n\\n    @staticmethod\\n    def _unpad_packed_features(features: dict[str, Any]) -> None:\\n        r\\\"\\\"\\\"Trim padded positions for packed FA2 batches.\\\"\\\"\\\"\\n        attention_mask = features.get(\\\"attention_mask\\\")\\n        if not torch.is_tensor(attention_mask) or attention_mask.dim() != 2 or attention_mask.size(0) != 1:\\n            return\\n\\n        seq_len = attention_mask.size(1)\\n        non_padding_indices = torch.nonzero(attention_mask[0] != 0, as_tuple=False).flatten()\\n        if non_padding_indices.numel() == seq_len:\\n            return\\n\\n        keys_on_seq_dim_1 = {\\\"input_ids\\\", \\\"labels\\\", \\\"attention_mask\\\", \\\"token_type_ids\\\"}\\n        for key, value in list(features.items()):\\n            if not torch.is_tensor(value):\\n                continue\\n\\n            if key == \\\"position_ids\\\" and value.size(-1) == seq_len:\\n                features[key] = value.index_select(-1, non_padding_indices)\\n            elif (\\n                key == \\\"cross_attention_mask\\\" and value.dim() >= 2 and value.size(0) == 1 and value.size(1) == seq_len\\n            ):\\n                features[key] = value.index_select(1, non_padding_indices)\\n            elif key in keys_on_seq_dim_1 and value.dim() == 2 and value.size(0) == 1 and value.size(1) == seq_len:\\n                features[key] = value.index_select(1, non_padding_indices)\\n\\n    def __call__(self, features: list[dict[str, Any]]) -> dict[str, \\\"torch.Tensor\\\"]:\\n        features = super().__call__(features)\\n        has_dummy_image = features.pop(\\\"has_dummy_image\\\", False)\\n        if self.block_diag_attn and self.attn_implementation != \\\"flash_attention_2\\\":\\n            features[\\\"attention_mask\\\"] = prepare_4d_attention_mask(features[\\\"attention_mask\\\"], self.compute_dtype)\\n\\n        if self.neat_packing and self.attn_implementation == \\\"flash_attention_2\\\":  # FIXME compatibility fa3/fa4\\n            assert features[\\\"input_ids\\\"].shape[0] == 1, \\\"bsz should be 1 for neat packing\\\"\\n            if not has_dummy_image:\\n                self._unpad_packed_features(features)\\n\\n            features[\\\"attention_mask\\\"] = None  # let transformers handle causal packed mask.\\n        else:\\n            # `DataCollatorForSeq2Seq(pad_to_multiple_of=...)` pads `input_ids`/`attention_mask`\\n            # but leaves `position_ids` untouched (it is not in `model_input_names`). On the\\n            # non-FA2 packing path we do not unpad, so `position_ids` stays shorter than\\n            # `input_ids`, which makes cos/sin shorter than query and crashes\\n            # `apply_rotary_pos_emb`. Right-pad `position_ids` to the padded length to match.\\n            position_ids = features.get(\\\"position_ids\\\")\\n            if torch.is_tensor(position_ids):\\n                pad_len = features[\\\"input_ids\\\"].shape[-1] - position_ids.shape[-1]\\n                if pad_len > 0:\\n                    features[\\\"position_ids\\\"] = F.pad(position_ids, (0, pad_len), value=0)\\n\\n        for key, value in features.items():  # cast data dtype for paligemma\\n            if torch.is_tensor(value) and torch.is_floating_point(value):\\n                features[key] = value.to(self.compute_dtype)\\n\\n        return features\\n\\n\\n@dataclass\\nclass PairwiseDataCollatorWithPadding(MultiModalDataCollatorForSeq2Seq):\\n    r\\\"\\\"\\\"Data collator for pairwise data.\\\"\\\"\\\"\\n\\n    def __call__(self, features: list[dict[str, Any]]) -> dict[str, \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Pad batched data to the longest sequence in the batch.\\n\\n        We generate 2 * n examples where the first n examples represent chosen examples and\\n        the last n examples represent rejected examples.\\n        \\\"\\\"\\\"\\n        concatenated_features = []\\n        for key in (\\\"chosen\\\", \\\"rejected\\\"):\\n            for feature in features:\\n                target_feature = {\\n                    \\\"input_ids\\\": feature[f\\\"{key}_input_ids\\\"],\\n                    \\\"attention_mask\\\": feature[f\\\"{key}_attention_mask\\\"],\\n                    \\\"labels\\\": feature[f\\\"{key}_labels\\\"],\\n                    \\\"images\\\": feature[\\\"images\\\"],\\n                    \\\"videos\\\": feature[\\\"videos\\\"],\\n                    \\\"audios\\\": feature[\\\"audios\\\"],\\n                }\\n                concatenated_features.append(target_feature)\\n\\n        return super().__call__(concatenated_features)\\n\\n\\n@dataclass\\nclass KTODataCollatorWithPadding(MultiModalDataCollatorForSeq2Seq):\\n    r\\\"\\\"\\\"Data collator for KTO data.\\\"\\\"\\\"\\n\\n    def __call__(self, features: list[dict[str, Any]]) -> dict[str, \\\"torch.Tensor\\\"]:\\n        target_features = []\\n        kl_features = []\\n        kto_tags = []\\n        for feature in features:\\n            target_feature = {\\n                \\\"input_ids\\\": feature[\\\"input_ids\\\"],\\n                \\\"attention_mask\\\": feature[\\\"attention_mask\\\"],\\n                \\\"labels\\\": feature[\\\"labels\\\"],\\n                \\\"images\\\": feature[\\\"images\\\"],\\n                \\\"videos\\\": feature[\\\"videos\\\"],\\n                \\\"audios\\\": feature[\\\"audios\\\"],\\n            }\\n            kl_feature = {\\n                \\\"input_ids\\\": feature[\\\"kl_input_ids\\\"],\\n                \\\"attention_mask\\\": feature[\\\"kl_attention_mask\\\"],\\n                \\\"labels\\\": feature[\\\"kl_labels\\\"],\\n                \\\"images\\\": feature[\\\"images\\\"],\\n                \\\"videos\\\": feature[\\\"videos\\\"],\\n                \\\"audios\\\": feature[\\\"audios\\\"],\\n            }\\n            target_features.append(target_feature)\\n            kl_features.append(kl_feature)\\n            kto_tags.append(feature[\\\"kto_tags\\\"])\\n\\n        batch = super().__call__(target_features)\\n        kl_batch = super().__call__(kl_features)\\n        batch[\\\"kl_input_ids\\\"] = kl_batch[\\\"input_ids\\\"]\\n        batch[\\\"kl_attention_mask\\\"] = kl_batch[\\\"attention_mask\\\"]\\n        batch[\\\"kl_labels\\\"] = kl_batch[\\\"labels\\\"]\\n        if \\\"cross_attention_mask\\\" in kl_batch:  # for mllama inputs\\n            batch[\\\"kl_cross_attention_mask\\\"] = kl_batch[\\\"cross_attention_mask\\\"]\\n\\n        if \\\"token_type_ids\\\" in kl_batch:\\n            batch[\\\"kl_token_type_ids\\\"] = kl_batch[\\\"token_type_ids\\\"]\\n\\n        batch[\\\"kto_tags\\\"] = torch.tensor(kto_tags)\\n        return batch\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/converter.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c596efb447fb50fc915f6aa5c4f228d5409fba83808e23015a1bcf3387a3ffbf\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\nimport json\\nimport os\\nfrom abc import abstractmethod\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Any, Union\\n\\nfrom ..extras import logging\\nfrom .data_utils import Role\\n\\n\\nif TYPE_CHECKING:\\n    from datasets import Dataset, IterableDataset\\n    from transformers import Seq2SeqTrainingArguments\\n\\n    from ..hparams import DataArguments\\n    from .mm_plugin import AudioInput, ImageInput, VideoInput\\n    from .parser import DatasetAttr\\n\\n    MediaType = Union[ImageInput, VideoInput, AudioInput]\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\n@dataclass\\nclass DatasetConverter:\\n    dataset_attr: \\\"DatasetAttr\\\"\\n    data_args: \\\"DataArguments\\\"\\n\\n    def _find_medias(self, medias: Union[\\\"MediaType\\\", list[\\\"MediaType\\\"], None]) -> list[\\\"MediaType\\\"] | None:\\n        r\\\"\\\"\\\"Optionally concatenate media path to media dir when loading from local disk.\\\"\\\"\\\"\\n        if medias is None:\\n            return None\\n        elif not isinstance(medias, list):\\n            medias = [medias]\\n        elif len(medias) == 0:\\n            return None\\n        else:\\n            medias = medias[:]\\n\\n        if self.dataset_attr.load_from in [\\\"script\\\", \\\"file\\\"]:\\n            if isinstance(medias[0], str):\\n                for i in range(len(medias)):\\n                    media_path = os.path.join(self.data_args.media_dir, medias[i])\\n                    if os.path.isfile(media_path):\\n                        medias[i] = media_path\\n                    else:\\n                        logger.warning_rank0_once(\\n                            f\\\"Media {medias[i]} does not exist in `media_dir`. Use original path.\\\"\\n                        )\\n            elif isinstance(medias[0], list):  # for processed video frames\\n                # medias is a list of lists, e.g., [[frame1.jpg, frame2.jpg], [frame3.jpg, frame4.jpg]]\\n                for i in range(len(medias)):\\n                    for j in range(len(medias[i])):\\n                        media_path = os.path.join(self.data_args.media_dir, medias[i][j])\\n                        if os.path.isfile(media_path):\\n                            medias[i][j] = media_path\\n                        else:\\n                            logger.warning_rank0_once(\\n                                f\\\"Media {medias[i][j]} does not exist in `media_dir`. Use original path.\\\"\\n                            )\\n\\n        return medias\\n\\n    @abstractmethod\\n    def __call__(self, example: dict[str, Any]) -> dict[str, Any]:\\n        r\\\"\\\"\\\"Convert a single example in the dataset to the standard format.\\\"\\\"\\\"\\n        ...\\n\\n\\n@dataclass\\nclass AlpacaDatasetConverter(DatasetConverter):\\n    def __call__(self, example: dict[str, Any]) -> dict[str, Any]:\\n        prompt = []\\n        if self.dataset_attr.history and isinstance(example[self.dataset_attr.history], list):\\n            for old_prompt, old_response in example[self.dataset_attr.history]:\\n                prompt.append({\\\"role\\\": Role.USER.value, \\\"content\\\": old_prompt})\\n                prompt.append({\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": old_response})\\n\\n        query = []\\n        if self.dataset_attr.prompt and example[self.dataset_attr.prompt]:\\n            query.append(example[self.dataset_attr.prompt])\\n\\n        if self.dataset_attr.query and example[self.dataset_attr.query]:\\n            query.append(example[self.dataset_attr.query])\\n\\n        prompt.append({\\\"role\\\": Role.USER.value, \\\"content\\\": \\\"\\\\n\\\".join(query)})  # \\\"prompt\\\\nquery\\\"\\n\\n        if self.dataset_attr.kto_tag and isinstance(example[self.dataset_attr.kto_tag], bool):  # kto example\\n            response = [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": example[self.dataset_attr.response]}]\\n            if example[self.dataset_attr.kto_tag]:\\n                response = response + [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}]\\n            else:\\n                response = [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}] + response\\n        elif (\\n            self.dataset_attr.ranking\\n            and isinstance(example[self.dataset_attr.chosen], str)\\n            and isinstance(example[self.dataset_attr.rejected], str)\\n        ):  # pairwise example\\n            response = [\\n                {\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": example[self.dataset_attr.chosen]},\\n                {\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": example[self.dataset_attr.rejected]},\\n            ]\\n        elif self.dataset_attr.response and isinstance(example[self.dataset_attr.response], str):  # normal example\\n            response = [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": example[self.dataset_attr.response]}]\\n        else:  # unsupervised\\n            response = []\\n\\n        output = {\\n            \\\"_prompt\\\": prompt,\\n            \\\"_response\\\": response,\\n            \\\"_system\\\": example[self.dataset_attr.system] if self.dataset_attr.system else \\\"\\\",\\n            \\\"_tools\\\": example[self.dataset_attr.tools] if self.dataset_attr.tools else \\\"\\\",\\n            \\\"_images\\\": self._find_medias(example[self.dataset_attr.images]) if self.dataset_attr.images else None,\\n            \\\"_videos\\\": self._find_medias(example[self.dataset_attr.videos]) if self.dataset_attr.videos else None,\\n            \\\"_audios\\\": self._find_medias(example[self.dataset_attr.audios]) if self.dataset_attr.audios else None,\\n        }\\n        return output\\n\\n\\n@dataclass\\nclass SharegptDatasetConverter(DatasetConverter):\\n    def __call__(self, example: dict[str, Any]) -> dict[str, Any]:\\n        tag_mapping = {\\n            self.dataset_attr.user_tag: Role.USER.value,\\n            self.dataset_attr.assistant_tag: Role.ASSISTANT.value,\\n            self.dataset_attr.observation_tag: Role.OBSERVATION.value,\\n            self.dataset_attr.function_tag: Role.FUNCTION.value,\\n            self.dataset_attr.system_tag: Role.SYSTEM.value,\\n        }\\n        odd_tags = (self.dataset_attr.user_tag, self.dataset_attr.observation_tag)\\n        even_tags = (self.dataset_attr.assistant_tag, self.dataset_attr.function_tag)\\n        accept_tags = (odd_tags, even_tags)\\n        messages = example[self.dataset_attr.messages]\\n        if (\\n            self.dataset_attr.system_tag\\n            and len(messages) != 0\\n            and messages[0][self.dataset_attr.role_tag] == self.dataset_attr.system_tag\\n        ):\\n            system = messages[0][self.dataset_attr.content_tag]\\n            messages = messages[1:]\\n        else:\\n            system = example[self.dataset_attr.system] if self.dataset_attr.system else \\\"\\\"\\n\\n        aligned_messages = []\\n        broken_data = False\\n        for turn_idx, message in enumerate(messages):\\n            if message[self.dataset_attr.role_tag] not in accept_tags[turn_idx % 2]:\\n                logger.warning_rank0(f\\\"Invalid role tag in {messages}.\\\")\\n                broken_data = True\\n                break\\n\\n            aligned_messages.append(\\n                {\\n                    \\\"role\\\": tag_mapping[message[self.dataset_attr.role_tag]],\\n                    \\\"content\\\": message[self.dataset_attr.content_tag],\\n                }\\n            )\\n\\n        if (not self.dataset_attr.ranking and len(aligned_messages) % 2 != 0) or (\\n            self.dataset_attr.ranking and len(aligned_messages) % 2 == 0\\n        ):\\n            logger.warning_rank0(f\\\"Invalid message count in {messages}.\\\")\\n            broken_data = True\\n\\n        if broken_data:\\n            logger.warning_rank0(\\\"Skipping this abnormal example.\\\")\\n            prompt, response = [], []\\n        elif self.dataset_attr.kto_tag and isinstance(example[self.dataset_attr.kto_tag], bool):  # kto example\\n            prompt = aligned_messages[:-1]\\n            response = aligned_messages[-1:]\\n            if example[self.dataset_attr.kto_tag]:\\n                response = response + [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}]\\n            else:\\n                response = [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}] + response\\n        elif (\\n            self.dataset_attr.ranking\\n            and isinstance(example[self.dataset_attr.chosen], dict)\\n            and isinstance(example[self.dataset_attr.rejected], dict)\\n        ):  # pairwise example\\n            chosen = example[self.dataset_attr.chosen]\\n            rejected = example[self.dataset_attr.rejected]\\n            if (\\n                chosen[self.dataset_attr.role_tag] not in accept_tags[-1]\\n                or rejected[self.dataset_attr.role_tag] not in accept_tags[-1]\\n            ):\\n                logger.warning_rank0(f\\\"Invalid role tag in {[chosen, rejected]}.\\\")\\n                broken_data = True\\n\\n            prompt = aligned_messages\\n            response = [\\n                {\\n                    \\\"role\\\": tag_mapping[chosen[self.dataset_attr.role_tag]],\\n                    \\\"content\\\": chosen[self.dataset_attr.content_tag],\\n                },\\n                {\\n                    \\\"role\\\": tag_mapping[rejected[self.dataset_attr.role_tag]],\\n                    \\\"content\\\": rejected[self.dataset_attr.content_tag],\\n                },\\n            ]\\n        else:  # normal example\\n            prompt = aligned_messages[:-1]\\n            response = aligned_messages[-1:]\\n\\n        output = {\\n            \\\"_prompt\\\": prompt,\\n            \\\"_response\\\": response,\\n            \\\"_system\\\": system,\\n            \\\"_tools\\\": example[self.dataset_attr.tools] if self.dataset_attr.tools else \\\"\\\",\\n            \\\"_images\\\": self._find_medias(example[self.dataset_attr.images]) if self.dataset_attr.images else None,\\n            \\\"_videos\\\": self._find_medias(example[self.dataset_attr.videos]) if self.dataset_attr.videos else None,\\n            \\\"_audios\\\": self._find_medias(example[self.dataset_attr.audios]) if self.dataset_attr.audios else None,\\n        }\\n        return output\\n\\n\\n@dataclass\\nclass OpenAIDatasetConverter(DatasetConverter):\\n    def __call__(self, example: dict[str, Any]) -> dict[str, Any]:\\n        tag_mapping = {\\n            self.dataset_attr.user_tag: Role.USER.value,\\n            self.dataset_attr.assistant_tag: Role.ASSISTANT.value,\\n            self.dataset_attr.observation_tag: Role.OBSERVATION.value,\\n            self.dataset_attr.function_tag: Role.FUNCTION.value,\\n            self.dataset_attr.system_tag: Role.SYSTEM.value,\\n        }\\n\\n        messages = example[self.dataset_attr.messages]\\n        if (\\n            self.dataset_attr.system_tag\\n            and len(messages) != 0\\n            and messages[0][self.dataset_attr.role_tag] == self.dataset_attr.system_tag\\n        ):\\n            system = messages[0][self.dataset_attr.content_tag]\\n            messages = messages[1:]\\n        else:\\n            system = example.get(self.dataset_attr.system, \\\"\\\") if self.dataset_attr.system else \\\"\\\"\\n\\n        aligned_messages = []\\n        tool_responses = []\\n        broken_data = False\\n        for turn_idx, message in enumerate(messages):\\n            role = message[self.dataset_attr.role_tag]\\n            content = message[self.dataset_attr.content_tag]\\n\\n            if role in [self.dataset_attr.assistant_tag, self.dataset_attr.function_tag]:\\n                if tool_calls := message.get(\\\"tool_calls\\\"):\\n                    tool_calls_list = [tool[\\\"function\\\"] for tool in tool_calls]\\n                    content = json.dumps(tool_calls_list, ensure_ascii=False)\\n                    role = self.dataset_attr.function_tag\\n\\n            if role == self.dataset_attr.observation_tag:\\n                tool_responses.append(content)\\n                continue\\n            elif len(tool_responses) > 0:\\n                _content = \\\"\\\\n</tool_response>\\\\n<tool_response>\\\\n\\\".join(tool_responses)\\n                aligned_messages.append(\\n                    {\\n                        \\\"role\\\": Role.OBSERVATION.value,\\n                        \\\"content\\\": _content,\\n                    }\\n                )\\n                tool_responses = []\\n\\n            aligned_messages.append(\\n                {\\n                    \\\"role\\\": tag_mapping[role],\\n                    \\\"content\\\": content,\\n                }\\n            )\\n\\n        odd_tags = (Role.USER.value, Role.OBSERVATION.value)\\n        even_tags = (Role.ASSISTANT.value, Role.FUNCTION.value)\\n        accept_tags = (odd_tags, even_tags)\\n        for turn_idx, message in enumerate(aligned_messages):\\n            if message[\\\"role\\\"] not in accept_tags[turn_idx % 2]:\\n                logger.warning_rank0(f\\\"Invalid role tag in {messages}.\\\")\\n                broken_data = True\\n                break\\n\\n        if (not self.dataset_attr.ranking and len(aligned_messages) % 2 != 0) or (\\n            self.dataset_attr.ranking and len(aligned_messages) % 2 == 0\\n        ):\\n            logger.warning_rank0(f\\\"Invalid message count in {messages}.\\\")\\n            broken_data = True\\n\\n        if broken_data:\\n            logger.warning_rank0(\\\"Skipping this abnormal example.\\\")\\n            prompt, response = [], []\\n        elif self.dataset_attr.kto_tag and isinstance(example[self.dataset_attr.kto_tag], bool):  # kto example\\n            prompt = aligned_messages[:-1]\\n            response = aligned_messages[-1:]\\n            if example[self.dataset_attr.kto_tag]:\\n                response = response + [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}]\\n            else:\\n                response = [{\\\"role\\\": Role.ASSISTANT.value, \\\"content\\\": \\\"\\\"}] + response\\n        elif (\\n            self.dataset_attr.ranking\\n            and isinstance(example[self.dataset_attr.chosen], dict)\\n            and isinstance(example[self.dataset_attr.rejected], dict)\\n        ):  # pairwise example\\n            chosen = example[self.dataset_attr.chosen]\\n            rejected = example[self.dataset_attr.rejected]\\n            if (\\n                chosen[self.dataset_attr.role_tag] not in accept_tags[-1]\\n                or rejected[self.dataset_attr.role_tag] not in accept_tags[-1]\\n            ):\\n                logger.warning_rank0(f\\\"Invalid role tag in {[chosen, rejected]}.\\\")\\n                broken_data = True\\n\\n            prompt = aligned_messages\\n            response = [\\n                {\\n                    \\\"role\\\": tag_mapping[chosen[self.dataset_attr.role_tag]],\\n                    \\\"content\\\": chosen[self.dataset_attr.content_tag],\\n                },\\n                {\\n                    \\\"role\\\": tag_mapping[rejected[self.dataset_attr.role_tag]],\\n                    \\\"content\\\": rejected[self.dataset_attr.content_tag],\\n                },\\n            ]\\n        else:  # normal example\\n            prompt = aligned_messages[:-1]\\n            response = aligned_messages[-1:]\\n\\n        tools = example.get(self.dataset_attr.tools, \\\"\\\") if self.dataset_attr.tools else \\\"\\\"\\n        if isinstance(tools, dict) or isinstance(tools, list):\\n            tools = json.dumps(tools, ensure_ascii=False)\\n\\n        short_system_prompt = \\\"detailed thinking off\\\"\\n        if not system:\\n            if not tools:\\n                system = short_system_prompt\\n            else:\\n                pass\\n        else:\\n            if not tools:\\n                if \\\"detailed thinking on\\\" in system or \\\"detailed thinking off\\\" in system:\\n                    pass\\n                else:\\n                    system += \\\"\\\\n\\\" + short_system_prompt\\n            else:\\n                system += \\\"\\\\n\\\"\\n\\n        output = {\\n            \\\"_prompt\\\": prompt,\\n            \\\"_response\\\": response,\\n            \\\"_system\\\": system,\\n            \\\"_tools\\\": tools,\\n            \\\"_images\\\": self._find_medias(example[self.dataset_attr.images]) if self.dataset_attr.images else None,\\n            \\\"_videos\\\": self._find_medias(example[self.dataset_attr.videos]) if self.dataset_attr.videos else None,\\n            \\\"_audios\\\": self._find_medias(example[self.dataset_attr.audios]) if self.dataset_attr.audios else None,\\n        }\\n        return output\\n\\n\\nDATASET_CONVERTERS = {\\n    \\\"alpaca\\\": AlpacaDatasetConverter,\\n    \\\"sharegpt\\\": SharegptDatasetConverter,\\n    \\\"openai\\\": OpenAIDatasetConverter,\\n}\\n\\n\\ndef register_dataset_converter(name: str, dataset_converter: type[\\\"DatasetConverter\\\"]) -> None:\\n    r\\\"\\\"\\\"Register a new dataset converter.\\\"\\\"\\\"\\n    if name in DATASET_CONVERTERS:\\n        raise ValueError(f\\\"Dataset converter {name} already exists.\\\")\\n\\n    DATASET_CONVERTERS[name] = dataset_converter\\n\\n\\ndef get_dataset_converter(name: str, dataset_attr: \\\"DatasetAttr\\\", data_args: \\\"DataArguments\\\") -> \\\"DatasetConverter\\\":\\n    r\\\"\\\"\\\"Get a dataset converter.\\\"\\\"\\\"\\n    if name not in DATASET_CONVERTERS:\\n        raise ValueError(f\\\"Dataset converter {name} not found.\\\")\\n\\n    return DATASET_CONVERTERS[name](dataset_attr, data_args)\\n\\n\\ndef align_dataset(\\n    dataset: Union[\\\"Dataset\\\", \\\"IterableDataset\\\"],\\n    dataset_attr: \\\"DatasetAttr\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n) -> Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]:\\n    r\\\"\\\"\\\"Align the dataset to a specific format.\\n\\n    Aligned dataset:\\n    _prompt: [{\\\"role\\\": \\\"user\\\", \\\"content\\\": \\\"...\\\"}] * (2T - 1)\\n    _response: [{\\\"role\\\": \\\"assistant\\\", \\\"content\\\": \\\"...\\\"}] * N (N > 1 for ranking dataset)\\n    _system: \\\"...\\\"\\n    _tools: \\\"...\\\"\\n    _images: []\\n    _videos: []\\n    _audios: []\\n    \\\"\\\"\\\"\\n    column_names = list(next(iter(dataset)).keys())\\n    kwargs = {}\\n    if not data_args.streaming:\\n        kwargs = dict(\\n            num_proc=data_args.preprocessing_num_workers,\\n            load_from_cache_file=(not data_args.overwrite_cache) or (training_args.local_process_index != 0),\\n            desc=\\\"Converting format of dataset\\\",\\n        )\\n\\n    dataset_converter = get_dataset_converter(dataset_attr.formatting, dataset_attr, data_args)\\n    return dataset.map(\\n        dataset_converter,\\n        batched=False,\\n        remove_columns=column_names,\\n        **kwargs,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/data_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4e25c8d0f44aef2dcfd454312b9b98ba98bfb0db99415b495c67f6883c1ac89f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nfrom enum import StrEnum, unique\\nfrom typing import TYPE_CHECKING, Any, Optional, TypedDict, Union\\n\\nimport fsspec\\nfrom datasets import DatasetDict, concatenate_datasets, interleave_datasets\\n\\nfrom ..extras import logging\\n\\n\\nif TYPE_CHECKING:\\n    from datasets import Dataset, IterableDataset\\n\\n    from ..hparams import DataArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nSLOTS = list[Union[str, set[str], dict[str, str]]]\\n\\n\\n@unique\\nclass Role(StrEnum):\\n    USER = \\\"user\\\"\\n    ASSISTANT = \\\"assistant\\\"\\n    SYSTEM = \\\"system\\\"\\n    FUNCTION = \\\"function\\\"\\n    OBSERVATION = \\\"observation\\\"\\n\\n\\nclass DatasetModule(TypedDict):\\n    train_dataset: Optional[Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]]\\n    eval_dataset: Optional[Union[\\\"Dataset\\\", \\\"IterableDataset\\\", dict[str, \\\"Dataset\\\"]]]\\n\\n\\ndef merge_dataset(\\n    all_datasets: list[Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]], data_args: \\\"DataArguments\\\", seed: int\\n) -> Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]:\\n    r\\\"\\\"\\\"Merge multiple datasets to a unified dataset.\\\"\\\"\\\"\\n    if len(all_datasets) == 1:\\n        return all_datasets[0]\\n\\n    elif data_args.mix_strategy == \\\"concat\\\":\\n        if data_args.streaming:\\n            logger.warning_rank0_once(\\\"The samples between different datasets will not be mixed in streaming mode.\\\")\\n\\n        return concatenate_datasets(all_datasets)\\n\\n    elif data_args.mix_strategy.startswith(\\\"interleave\\\"):\\n        if not data_args.streaming:\\n            logger.warning_rank0_once(\\\"We recommend using `mix_strategy=concat` in non-streaming mode.\\\")\\n\\n        strategy_map: str = {\\n            \\\"interleave_under\\\": \\\"first_exhausted\\\",\\n            \\\"interleave_over\\\": \\\"all_exhausted\\\",\\n            \\\"interleave_once\\\": \\\"all_exhausted_without_replacement\\\",\\n        }[data_args.mix_strategy]\\n\\n        return interleave_datasets(\\n            datasets=all_datasets,\\n            probabilities=data_args.interleave_probs,\\n            seed=seed,\\n            stopping_strategy=strategy_map,  # type: ignore\\n        )\\n\\n    else:\\n        raise ValueError(f\\\"Unknown mixing strategy: {data_args.mix_strategy}.\\\")\\n\\n\\ndef split_dataset(\\n    dataset: Optional[Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]],\\n    eval_dataset: Optional[Union[\\\"Dataset\\\", \\\"IterableDataset\\\", dict[str, \\\"Dataset\\\"]]],\\n    data_args: \\\"DataArguments\\\",\\n    seed: int,\\n) -> tuple[dict, dict]:\\n    r\\\"\\\"\\\"Split the dataset and returns two dicts containing train set and validation set.\\n\\n    Support both map dataset and iterable dataset.\\n\\n    Returns:\\n        train_dict: Dictionary containing training data with key \\\"train\\\"\\n        eval_dict: Dictionary containing evaluation data with keys \\\"validation\\\" or \\\"validation_{name}\\\"\\n    \\\"\\\"\\\"\\n    if eval_dataset is not None and data_args.val_size > 1e-6:\\n        raise ValueError(\\\"Cannot specify `val_size` if `eval_dataset` is not None.\\\")\\n\\n    # the train and eval better to in dict dtype and separately return for cpode clearly and good handle outside\\n    train_dict, eval_dict = {}, {}\\n\\n    if dataset is not None:\\n        if data_args.streaming:\\n            dataset = dataset.shuffle(buffer_size=data_args.buffer_size, seed=seed)\\n\\n        if data_args.val_size > 1e-6:\\n            if data_args.streaming:\\n                eval_dict[\\\"validation\\\"] = dataset.take(int(data_args.val_size))\\n                train_dict[\\\"train\\\"] = dataset.skip(int(data_args.val_size))\\n            else:\\n                val_size = int(data_args.val_size) if data_args.val_size > 1 else data_args.val_size\\n                split_result = dataset.train_test_split(test_size=val_size, seed=seed)\\n                train_dict[\\\"train\\\"] = split_result[\\\"train\\\"]\\n                eval_dict[\\\"validation\\\"] = split_result[\\\"test\\\"]\\n        else:\\n            train_dict[\\\"train\\\"] = dataset\\n\\n    if eval_dataset is not None:\\n        if isinstance(eval_dataset, dict):\\n            for name, data in eval_dataset.items():\\n                eval_dict[f\\\"validation_{name}\\\"] = data\\n        else:\\n            if data_args.streaming:\\n                eval_dataset = eval_dataset.shuffle(buffer_size=data_args.buffer_size, seed=seed)\\n\\n            eval_dict[\\\"validation\\\"] = eval_dataset\\n\\n    return train_dict, eval_dict\\n\\n\\ndef get_dataset_module(dataset: Union[\\\"Dataset\\\", \\\"DatasetDict\\\"]) -> \\\"DatasetModule\\\":\\n    r\\\"\\\"\\\"Convert dataset or dataset dict to dataset module.\\\"\\\"\\\"\\n    dataset_module: DatasetModule = {}\\n    if isinstance(dataset, DatasetDict):  # dataset dict\\n        if \\\"train\\\" in dataset:\\n            dataset_module[\\\"train_dataset\\\"] = dataset[\\\"train\\\"]\\n\\n        if \\\"validation\\\" in dataset:\\n            dataset_module[\\\"eval_dataset\\\"] = dataset[\\\"validation\\\"]\\n        else:\\n            eval_dataset = {}\\n            for key in dataset.keys():\\n                if key.startswith(\\\"validation_\\\"):\\n                    eval_dataset[key[len(\\\"validation_\\\") :]] = dataset[key]\\n\\n            if len(eval_dataset):\\n                dataset_module[\\\"eval_dataset\\\"] = eval_dataset\\n\\n    else:  # single dataset\\n        dataset_module[\\\"train_dataset\\\"] = dataset\\n\\n    return dataset_module\\n\\n\\ndef setup_fs(path: str, anon: bool = False) -> \\\"fsspec.AbstractFileSystem\\\":\\n    r\\\"\\\"\\\"Set up a filesystem object based on the path protocol.\\\"\\\"\\\"\\n    storage_options = {\\\"anon\\\": anon} if anon else {}\\n    if path.startswith(\\\"s3://\\\"):\\n        fs = fsspec.filesystem(\\\"s3\\\", **storage_options)\\n    elif path.startswith((\\\"gs://\\\", \\\"gcs://\\\")):\\n        fs = fsspec.filesystem(\\\"gcs\\\", **storage_options)\\n    else:\\n        raise ValueError(f\\\"Unsupported protocol in path: {path}. Use 's3://' or 'gs://'.\\\")\\n\\n    if not fs.exists(path):\\n        raise ValueError(f\\\"Path does not exist: {path}.\\\")\\n\\n    return fs\\n\\n\\ndef _read_json_with_fs(fs: \\\"fsspec.AbstractFileSystem\\\", path: str) -> list[Any]:\\n    r\\\"\\\"\\\"Helper function to read JSON/JSONL files using fsspec.\\\"\\\"\\\"\\n    with fs.open(path, \\\"r\\\") as f:\\n        if path.endswith(\\\".jsonl\\\"):\\n            return [json.loads(line) for line in f if line.strip()]\\n        else:\\n            return json.load(f)\\n\\n\\ndef read_cloud_json(cloud_path: str) -> list[Any]:\\n    r\\\"\\\"\\\"Read a JSON/JSONL file from cloud storage (S3 or GCS).\\n\\n    Args:\\n        cloud_path: str\\n            Cloud path in the format:\\n            - 's3://bucket-name/file.json' for AWS S3\\n            - 'gs://bucket-name/file.jsonl' or 'gcs://bucket-name/file.jsonl' for Google Cloud Storage\\n    \\\"\\\"\\\"\\n    try:\\n        fs = setup_fs(cloud_path, anon=True)  # try with anonymous access first\\n    except Exception:\\n        fs = setup_fs(cloud_path)  # try again with credentials\\n\\n    # filter out non-JSON files\\n    files = [x[\\\"Key\\\"] for x in fs.listdir(cloud_path)] if fs.isdir(cloud_path) else [cloud_path]\\n    files = list(filter(lambda file: file.endswith(\\\".json\\\") or file.endswith(\\\".jsonl\\\"), files))\\n    if not files:\\n        raise ValueError(f\\\"No JSON/JSONL files found in the specified path: {cloud_path}.\\\")\\n\\n    return sum([_read_json_with_fs(fs, file) for file in files], [])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/formatter.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"345728a904b0a0168003cd44424d068fcddf7ea0d3c2ec07718f68b19e879d77\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nimport re\\nfrom abc import ABC, abstractmethod\\nfrom dataclasses import dataclass, field\\n\\nfrom typing_extensions import override\\n\\nfrom .data_utils import SLOTS\\nfrom .tool_utils import FunctionCall, get_tool_utils\\n\\n\\n@dataclass\\nclass Formatter(ABC):\\n    slots: SLOTS = field(default_factory=list)\\n    tool_format: str | None = None\\n\\n    @abstractmethod\\n    def apply(self, **kwargs) -> SLOTS:\\n        r\\\"\\\"\\\"Forms a list of slots according to the inputs to encode.\\\"\\\"\\\"\\n        ...\\n\\n    def extract(self, content: str) -> str | list[\\\"FunctionCall\\\"]:\\n        r\\\"\\\"\\\"Extract a list of tuples from the response message if using tools.\\n\\n        Each tuple consists of function name and function arguments.\\n        \\\"\\\"\\\"\\n        raise NotImplementedError\\n\\n\\n@dataclass\\nclass EmptyFormatter(Formatter):\\n    def __post_init__(self):\\n        has_placeholder = False\\n        for slot in filter(lambda s: isinstance(s, str), self.slots):\\n            if re.search(r\\\"\\\\{\\\\{[a-zA-Z_][a-zA-Z0-9_]*\\\\}\\\\}\\\", slot):\\n                has_placeholder = True\\n\\n        if has_placeholder:\\n            raise ValueError(\\\"Empty formatter should not contain any placeholder.\\\")\\n\\n    @override\\n    def apply(self, **kwargs) -> SLOTS:\\n        return self.slots\\n\\n\\n@dataclass\\nclass StringFormatter(Formatter):\\n    def __post_init__(self):\\n        has_placeholder = False\\n        for slot in filter(lambda s: isinstance(s, str), self.slots):\\n            if re.search(r\\\"\\\\{\\\\{[a-zA-Z_][a-zA-Z0-9_]*\\\\}\\\\}\\\", slot):\\n                has_placeholder = True\\n\\n        if not has_placeholder:\\n            raise ValueError(\\\"A placeholder is required in the string formatter.\\\")\\n\\n    @override\\n    def apply(self, **kwargs) -> SLOTS:\\n        elements = []\\n        for slot in self.slots:\\n            if isinstance(slot, str):\\n                for name, value in kwargs.items():\\n                    if not isinstance(value, str):\\n                        raise RuntimeError(f\\\"Expected a string, got {value}\\\")\\n\\n                    slot = slot.replace(\\\"{{\\\" + name + \\\"}}\\\", value, 1)\\n                elements.append(slot)\\n            elif isinstance(slot, (dict, set)):\\n                elements.append(slot)\\n            else:\\n                raise RuntimeError(f\\\"Input must be string, set[str] or dict[str, str], got {type(slot)}.\\\")\\n\\n        return elements\\n\\n\\n@dataclass\\nclass FunctionFormatter(StringFormatter):\\n    def __post_init__(self):\\n        super().__post_init__()\\n        self.tool_utils = get_tool_utils(self.tool_format)\\n\\n    @override\\n    def apply(self, **kwargs) -> SLOTS:\\n        content: str = kwargs.pop(\\\"content\\\")\\n        thought_words = kwargs.pop(\\\"thought_words\\\", None)\\n        tool_call_words = kwargs.pop(\\\"tool_call_words\\\", None)\\n\\n        def _parse_functions(json_content: str) -> list[\\\"FunctionCall\\\"]:\\n            try:\\n                tool_calls = json.loads(json_content)\\n                if not isinstance(tool_calls, list):  # parallel function call\\n                    tool_calls = [tool_calls]\\n\\n                return [FunctionCall(tc[\\\"name\\\"], json.dumps(tc[\\\"arguments\\\"], ensure_ascii=False)) for tc in tool_calls]\\n            except json.JSONDecodeError:\\n                raise RuntimeError(f\\\"Invalid JSON format in function message: {str([content])}.\\\")\\n\\n        tool_call_match = None\\n        if tool_call_words and len(tool_call_words) == 2:\\n            tool_call_regex = re.compile(\\n                rf\\\"{re.escape(tool_call_words[0])}(.*?){re.escape(tool_call_words[1])}\\\", re.DOTALL\\n            )\\n            tool_call_match = re.search(tool_call_regex, content)\\n\\n        if tool_call_match is None:\\n            thought_match = None\\n            if thought_words and len(thought_words) == 2:\\n                regex = re.compile(rf\\\"{re.escape(thought_words[0])}(.*?){re.escape(thought_words[1])}\\\", re.DOTALL)\\n                thought_match = re.search(regex, content)\\n\\n            if thought_match:\\n                json_part = content.replace(thought_match.group(0), \\\"\\\")\\n            else:\\n                json_part = content\\n\\n            functions = _parse_functions(json_part)\\n            function_str = self.tool_utils.function_formatter(functions)\\n            if thought_match:\\n                function_str = thought_match.group(0) + function_str\\n        else:\\n            thought_content = content.replace(tool_call_match.group(0), \\\"\\\")\\n            functions = _parse_functions(tool_call_match.group(1))\\n            function_str = self.tool_utils.function_formatter(functions)\\n            function_str = thought_content + function_str\\n\\n        return super().apply(content=function_str)\\n\\n\\n@dataclass\\nclass ToolFormatter(Formatter):\\n    def __post_init__(self):\\n        self.tool_utils = get_tool_utils(self.tool_format)\\n\\n    @override\\n    def apply(self, **kwargs) -> SLOTS:\\n        content = kwargs.pop(\\\"content\\\")\\n        try:\\n            tools = json.loads(content)\\n            return [self.tool_utils.tool_formatter(tools) if len(tools) != 0 else \\\"\\\"]\\n        except json.JSONDecodeError:\\n            raise RuntimeError(f\\\"Invalid JSON format in tool description: {str([content])}.\\\")  # flat string\\n\\n    @override\\n    def extract(self, content: str) -> str | list[\\\"FunctionCall\\\"]:\\n        return self.tool_utils.tool_extractor(content)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/loader.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f5f59ae8dcb65f95f16052d3c79645adbb02304ba3425682036a41728d0340d0\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nfrom typing import TYPE_CHECKING, Literal, Optional, Union\\n\\nimport numpy as np\\nfrom datasets import Dataset, DatasetDict, load_dataset, load_from_disk\\n\\nfrom ..extras import logging\\nfrom ..extras.constants import FILEEXT2TYPE\\nfrom ..extras.misc import check_version, has_tokenized_data\\nfrom .converter import align_dataset\\nfrom .data_utils import get_dataset_module, merge_dataset, read_cloud_json, split_dataset\\nfrom .parser import get_dataset_list\\nfrom .processor import (\\n    FeedbackDatasetProcessor,\\n    PackedSupervisedDatasetProcessor,\\n    PairwiseDatasetProcessor,\\n    PretrainDatasetProcessor,\\n    SupervisedDatasetProcessor,\\n    UnsupervisedDatasetProcessor,\\n)\\n\\n\\nif TYPE_CHECKING:\\n    from datasets import Dataset, IterableDataset\\n    from transformers import PreTrainedTokenizer, ProcessorMixin, Seq2SeqTrainingArguments\\n\\n    from ..hparams import DataArguments, ModelArguments\\n    from .data_utils import DatasetModule\\n    from .parser import DatasetAttr\\n    from .processor import DatasetProcessor\\n    from .template import Template\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef _load_single_dataset(\\n    dataset_attr: \\\"DatasetAttr\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n) -> Union[\\\"Dataset\\\", \\\"IterableDataset\\\"]:\\n    r\\\"\\\"\\\"Load a single dataset and aligns it to the standard format.\\\"\\\"\\\"\\n    logger.info_rank0(f\\\"Loading dataset {dataset_attr}...\\\")\\n    data_path, data_name, data_dir, data_files = None, None, None, None\\n    if dataset_attr.load_from in [\\\"hf_hub\\\", \\\"ms_hub\\\", \\\"om_hub\\\"]:\\n        data_path = dataset_attr.dataset_name\\n        data_name = dataset_attr.subset\\n        data_dir = dataset_attr.folder\\n\\n    elif dataset_attr.load_from == \\\"script\\\":\\n        data_path = os.path.join(data_args.dataset_dir, dataset_attr.dataset_name)\\n        data_name = dataset_attr.subset\\n        data_dir = dataset_attr.folder\\n\\n    elif dataset_attr.load_from == \\\"cloud_file\\\":\\n        data_path = dataset_attr.dataset_name\\n\\n    elif dataset_attr.load_from == \\\"file\\\":\\n        data_files = []\\n        local_path = os.path.join(data_args.dataset_dir, dataset_attr.dataset_name)\\n        if os.path.isdir(local_path):  # is directory\\n            for file_name in os.listdir(local_path):\\n                data_files.append(os.path.join(local_path, file_name))\\n        elif os.path.isfile(local_path):  # is file\\n            data_files.append(local_path)\\n        else:\\n            raise ValueError(f\\\"File {local_path} not found.\\\")\\n\\n        data_path = FILEEXT2TYPE.get(os.path.splitext(data_files[0])[-1][1:], None)\\n        if data_path is None:\\n            raise ValueError(\\\"Allowed file types: {}.\\\".format(\\\",\\\".join(FILEEXT2TYPE.keys())))\\n\\n        if any(data_path != FILEEXT2TYPE.get(os.path.splitext(data_file)[-1][1:], None) for data_file in data_files):\\n            raise ValueError(\\\"File types should be identical.\\\")\\n    else:\\n        raise NotImplementedError(f\\\"Unknown load type: {dataset_attr.load_from}.\\\")\\n\\n    if dataset_attr.load_from == \\\"ms_hub\\\":\\n        check_version(\\\"modelscope>=1.14.0\\\", mandatory=True)\\n        from modelscope import MsDataset  # type: ignore\\n        from modelscope.utils.config_ds import MS_DATASETS_CACHE  # type: ignore\\n\\n        cache_dir = model_args.cache_dir or MS_DATASETS_CACHE\\n        dataset = MsDataset.load(\\n            dataset_name=data_path,\\n            subset_name=data_name,\\n            data_dir=data_dir,\\n            data_files=data_files,\\n            split=dataset_attr.split,\\n            cache_dir=cache_dir,\\n            token=model_args.ms_hub_token,\\n            use_streaming=data_args.streaming,\\n        )\\n        if isinstance(dataset, MsDataset):\\n            dataset = dataset.to_hf_dataset()\\n\\n    elif dataset_attr.load_from == \\\"om_hub\\\":\\n        check_version(\\\"openmind>=0.8.0\\\", mandatory=True)\\n        from openmind import OmDataset  # type: ignore\\n        from openmind.utils.hub import OM_DATASETS_CACHE  # type: ignore\\n\\n        cache_dir = model_args.cache_dir or OM_DATASETS_CACHE\\n        dataset = OmDataset.load_dataset(\\n            path=data_path,\\n            name=data_name,\\n            data_dir=data_dir,\\n            data_files=data_files,\\n            split=dataset_attr.split,\\n            cache_dir=cache_dir,\\n            token=model_args.om_hub_token,\\n            streaming=data_args.streaming,\\n        )\\n    elif dataset_attr.load_from == \\\"cloud_file\\\":\\n        dataset = Dataset.from_list(read_cloud_json(data_path), split=dataset_attr.split)\\n    else:\\n        dataset = load_dataset(\\n            path=data_path,\\n            name=data_name,\\n            data_dir=data_dir,\\n            data_files=data_files,\\n            split=dataset_attr.split,\\n            cache_dir=model_args.cache_dir,\\n            token=model_args.hf_hub_token,\\n            num_proc=data_args.preprocessing_num_workers,\\n            streaming=data_args.streaming and dataset_attr.load_from != \\\"file\\\",\\n        )\\n        if data_args.streaming and dataset_attr.load_from == \\\"file\\\":\\n            dataset = dataset.to_iterable_dataset(num_shards=training_args.dataloader_num_workers)\\n\\n    if dataset_attr.num_samples is not None and not data_args.streaming:\\n        target_num = dataset_attr.num_samples\\n        indexes = np.random.permutation(len(dataset))[:target_num]  # all samples should be included\\n        target_num -= len(indexes)\\n        if target_num > 0:\\n            expand_indexes = np.random.choice(len(dataset), target_num)\\n            indexes = np.concatenate((indexes, expand_indexes), axis=0)\\n\\n        assert len(indexes) == dataset_attr.num_samples, \\\"Sample num mismatched.\\\"\\n        dataset = dataset.select(indexes)\\n        logger.info_rank0(f\\\"Sampled {dataset_attr.num_samples} examples from dataset {dataset_attr}.\\\")\\n\\n    if data_args.max_samples is not None:  # truncate dataset\\n        max_samples = min(data_args.max_samples, len(dataset))\\n        dataset = dataset.select(range(max_samples))\\n\\n    return align_dataset(dataset, dataset_attr, data_args, training_args)\\n\\n\\ndef _get_merged_dataset(\\n    dataset_names: list[str] | None,\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    stage: Literal[\\\"pt\\\", \\\"sft\\\", \\\"rm\\\", \\\"ppo\\\", \\\"kto\\\"],\\n    return_dict: bool = False,\\n) -> Union[\\\"Dataset\\\", \\\"IterableDataset\\\", dict[str, \\\"Dataset\\\"]] | None:\\n    r\\\"\\\"\\\"Return the merged datasets in the standard format.\\\"\\\"\\\"\\n    if dataset_names is None:\\n        return None\\n\\n    datasets = {}\\n    for dataset_name, dataset_attr in zip(dataset_names, get_dataset_list(dataset_names, data_args.dataset_dir)):\\n        if (stage == \\\"rm\\\" and dataset_attr.ranking is False) or (stage != \\\"rm\\\" and dataset_attr.ranking is True):\\n            raise ValueError(\\\"The dataset is not applicable in the current training stage.\\\")\\n\\n        datasets[dataset_name] = _load_single_dataset(dataset_attr, model_args, data_args, training_args)\\n\\n    if return_dict:\\n        return datasets\\n    else:\\n        return merge_dataset(list(datasets.values()), data_args, seed=training_args.seed)\\n\\n\\ndef _get_dataset_processor(\\n    data_args: \\\"DataArguments\\\",\\n    stage: Literal[\\\"pt\\\", \\\"sft\\\", \\\"rm\\\", \\\"ppo\\\", \\\"kto\\\"],\\n    template: \\\"Template\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    processor: Optional[\\\"ProcessorMixin\\\"],\\n    do_generate: bool = False,\\n) -> \\\"DatasetProcessor\\\":\\n    r\\\"\\\"\\\"Return the corresponding dataset processor.\\\"\\\"\\\"\\n    if stage == \\\"pt\\\":\\n        dataset_processor_class = PretrainDatasetProcessor\\n    elif stage == \\\"sft\\\" and not do_generate:\\n        if data_args.packing:\\n            if data_args.neat_packing:  # hack datasets to have int32 attention mask\\n                from datasets.arrow_writer import OptimizedTypedSequence, TypedSequence\\n\\n                def __init__(self, data, **kwargs):\\n                    return TypedSequence.__init__(\\n                        self,\\n                        data,\\n                        type=kwargs.pop(\\\"type\\\", None),\\n                        try_type=kwargs.pop(\\\"try_type\\\", None),\\n                        optimized_int_type=kwargs.pop(\\\"optimized_int_type\\\", None),\\n                    )\\n\\n                OptimizedTypedSequence.__init__ = __init__\\n            dataset_processor_class = PackedSupervisedDatasetProcessor\\n        else:\\n            dataset_processor_class = SupervisedDatasetProcessor\\n\\n    elif stage == \\\"rm\\\":\\n        dataset_processor_class = PairwiseDatasetProcessor\\n    elif stage == \\\"kto\\\":\\n        dataset_processor_class = FeedbackDatasetProcessor\\n    else:\\n        dataset_processor_class = UnsupervisedDatasetProcessor\\n\\n    return dataset_processor_class(template=template, tokenizer=tokenizer, processor=processor, data_args=data_args)\\n\\n\\ndef _get_preprocessed_dataset(\\n    dataset: Union[\\\"Dataset\\\", \\\"IterableDataset\\\"] | None,\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    stage: Literal[\\\"pt\\\", \\\"sft\\\", \\\"rm\\\", \\\"ppo\\\", \\\"kto\\\"],\\n    template: \\\"Template\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    processor: Optional[\\\"ProcessorMixin\\\"] = None,\\n    is_eval: bool = False,\\n) -> Union[\\\"Dataset\\\", \\\"IterableDataset\\\"] | None:\\n    r\\\"\\\"\\\"Preprocesses the dataset, including format checking and tokenization.\\\"\\\"\\\"\\n    if dataset is None:\\n        return None\\n\\n    dataset_processor = _get_dataset_processor(\\n        data_args, stage, template, tokenizer, processor, do_generate=(training_args.predict_with_generate and is_eval)\\n    )\\n    column_names = list(next(iter(dataset)).keys())\\n    kwargs = {}\\n    if not data_args.streaming:\\n        kwargs = dict(\\n            num_proc=data_args.preprocessing_num_workers,\\n            load_from_cache_file=(not data_args.overwrite_cache) or (training_args.local_process_index != 0),\\n            desc=\\\"Running tokenizer on dataset\\\",\\n        )\\n\\n    dataset = dataset.map(\\n        dataset_processor.preprocess_dataset,\\n        batched=True,\\n        batch_size=data_args.preprocessing_batch_size,\\n        remove_columns=column_names,\\n        **kwargs,\\n    )\\n\\n    if training_args.should_log:\\n        try:\\n            print(\\\"eval example:\\\" if is_eval else \\\"training example:\\\")\\n            dataset_processor.print_data_example(next(iter(dataset)))\\n        except StopIteration:\\n            if stage == \\\"pt\\\":\\n                raise RuntimeError(\\\"Cannot find sufficient samples, consider increasing dataset size.\\\")\\n            else:\\n                raise RuntimeError(\\\"Cannot find valid samples, check `data/README.md` for the data format.\\\")\\n\\n    return dataset\\n\\n\\ndef get_dataset(\\n    template: \\\"Template\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    stage: Literal[\\\"pt\\\", \\\"sft\\\", \\\"rm\\\", \\\"ppo\\\", \\\"kto\\\"],\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    processor: Optional[\\\"ProcessorMixin\\\"] = None,\\n) -> \\\"DatasetModule\\\":\\n    r\\\"\\\"\\\"Get the train dataset and optionally gets the evaluation dataset.\\\"\\\"\\\"\\n    # Load tokenized dataset if path exists\\n    if data_args.tokenized_path is not None:\\n        if has_tokenized_data(data_args.tokenized_path):\\n            logger.warning_rank0(\\\"Loading dataset from disk will ignore other data arguments.\\\")\\n            tokenized_data = load_from_disk(data_args.tokenized_path)\\n            dataset_module = get_dataset_module(tokenized_data)\\n            if data_args.streaming:\\n                dataset_module[\\\"train_dataset\\\"] = dataset_module[\\\"train_dataset\\\"].to_iterable_dataset()\\n\\n            logger.info_rank0(f\\\"Loaded tokenized dataset from {data_args.tokenized_path}.\\\")\\n            return dataset_module\\n\\n        if data_args.streaming:\\n            raise ValueError(\\\"Turn off `streaming` when saving dataset to disk.\\\")\\n\\n    # Load and preprocess dataset\\n    with training_args.main_process_first(desc=\\\"load dataset\\\", local=(not data_args.data_shared_file_system)):\\n        dataset = _get_merged_dataset(data_args.dataset, model_args, data_args, training_args, stage)\\n        eval_dataset = _get_merged_dataset(\\n            data_args.eval_dataset,\\n            model_args,\\n            data_args,\\n            training_args,\\n            stage,\\n            return_dict=data_args.eval_on_each_dataset,\\n        )\\n\\n    with training_args.main_process_first(desc=\\\"pre-process dataset\\\", local=(not data_args.data_shared_file_system)):\\n        # move front to make sure eval_dataset(if contain or split) can preprocessed appropriately\\n        train_dict, eval_dict = split_dataset(dataset, eval_dataset, data_args, seed=training_args.seed)\\n\\n        if \\\"train\\\" in train_dict:\\n            train_dict[\\\"train\\\"] = _get_preprocessed_dataset(\\n                train_dict[\\\"train\\\"], data_args, training_args, stage, template, tokenizer, processor, is_eval=False\\n            )\\n\\n        for key in eval_dict:\\n            eval_dict[key] = _get_preprocessed_dataset(\\n                eval_dict[key], data_args, training_args, stage, template, tokenizer, processor, is_eval=True\\n            )\\n\\n        # Combine train and eval dictionaries\\n        dataset_dict = DatasetDict({**train_dict, **eval_dict})\\n\\n        if data_args.tokenized_path is not None:  # save tokenized dataset to disk\\n            if training_args.should_save:\\n                dataset_dict.save_to_disk(data_args.tokenized_path)\\n                logger.info_rank0(f\\\"Tokenized dataset is saved at {data_args.tokenized_path}.\\\")\\n                logger.info_rank0(f\\\"Please launch the training with `tokenized_path: {data_args.tokenized_path}`.\\\")\\n\\n        return get_dataset_module(dataset_dict)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/data/mm_plugin.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b3a46744dac669f8941534e967b678466b47f76e3108d6f997ad0da0d9871ec9\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's Transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/src/transformers/models/llava/processing_llava.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport inspect\\nimport math\\nimport os\\nimport re\\nfrom copy import deepcopy\\nfrom dataclasses import dataclass\\nfrom io import BytesIO\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING, Any, BinaryIO, Literal, NotRequired, Optional, TypedDict, Union\\n\\nimport numpy as np\\nimport torch\\nimport torchaudio\\nfrom transformers.image_utils import get_image_size, is_valid_image, make_flat_list_of_images, to_numpy_array\\nfrom transformers.models.mllama.processing_mllama import (\\n    convert_sparse_cross_attention_mask_to_dense,\\n    get_cross_attention_token_mask,\\n)\\nfrom transformers.video_utils import make_batched_videos\\nfrom typing_extensions import override\\n\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IGNORE_INDEX, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER\\nfrom ..extras.packages import is_pillow_available, is_pyav_available, is_transformers_version_greater_than\\n\\n\\nif is_pillow_available():\\n    from PIL import Image\\n    from PIL.Image import Image as ImageObject\\n\\n\\nif is_pyav_available():\\n    import av\\n\\n\\nif TYPE_CHECKING:\\n    from av.stream import Stream\\n    from numpy.typing import NDArray\\n    from transformers import PreTrainedTokenizer, ProcessorMixin\\n    from transformers.feature_extraction_sequence_utils import SequenceFeatureExtractor\\n    from transformers.image_processing_utils import BaseImageProcessor\\n    from transformers.video_processing_utils import BaseVideoProcessor\\n\\n    class EncodedImage(TypedDict):\\n        path: str | None\\n        bytes: bytes | None\\n\\n    ImageInput = Union[str, bytes, EncodedImage, BinaryIO, ImageObject]\\n    VideoInput = Union[str, BinaryIO, list[list[ImageInput]]]\\n    AudioInput = Union[str, BinaryIO, NDArray]\\n\\n    class RegularizedImageOutput(TypedDict):\\n        images: list[ImageObject]\\n\\n    class RegularizedVideoOutput(TypedDict):\\n        videos: list[list[ImageObject]]\\n        durations: list[float]\\n        fps_per_video: NotRequired[list[float]]\\n\\n    class RegularizedAudioOutput(TypedDict):\\n        audios: list[NDArray]\\n        sampling_rates: list[float]\\n\\n    class MMProcessor(ProcessorMixin):\\n        patch_size: int\\n        image_seq_length: int\\n        num_additional_image_tokens: int\\n        vision_feature_select_strategy: Literal[\\\"default\\\", \\\"full\\\"]\\n\\n        def _get_number_of_features(self, orig_height: int, orig_width: int, height: int, width: int) -> int:\\n            pass\\n\\n\\ndef _get_paligemma_token_type_ids(imglens: list[int], seqlens: list[int], processor: \\\"MMProcessor\\\") -> list[list[int]]:\\n    r\\\"\\\"\\\"Get paligemma token type ids for computing loss.\\n\\n    It is slightly different with the original token type ids where the prompt part is 0.\\n\\n    Returns:\\n        batch_token_type_ids: shape (batch_size, seq_length)\\n\\n    \\\"\\\"\\\"\\n    batch_token_type_ids = []\\n    for imglen, seqlen in zip(imglens, seqlens):\\n        image_seqlen = imglen * processor.image_seq_length\\n        batch_token_type_ids.append([0] * image_seqlen + [1] * (seqlen - image_seqlen))\\n\\n    return batch_token_type_ids\\n\\n\\ndef _get_gemma3_token_type_ids(batch_ids: list[list[int]], processor: \\\"MMProcessor\\\"):\\n    r\\\"\\\"\\\"Get gemma3 token type ids for computing loss.\\n\\n    Returns:\\n        batch_token_type_ids: shape (batch_size, seq_length)\\n\\n    \\\"\\\"\\\"\\n    image_token_id: int = getattr(processor, \\\"image_token_id\\\")\\n    batch_token_type_ids = []\\n    for token_ids in batch_ids:\\n        token_ids = np.array(token_ids)\\n        token_type_ids = np.zeros_like(token_ids)\\n        token_type_ids[token_ids == image_token_id] = 1\\n        batch_token_type_ids.append(token_type_ids.tolist())\\n\\n    return batch_token_type_ids\\n\\n\\ndef _make_batched_images(images: list[\\\"ImageObject\\\"], imglens: list[int]) -> list[list[\\\"ImageObject\\\"]]:\\n    r\\\"\\\"\\\"Make nested list of images.\\\"\\\"\\\"\\n    batch_images = []\\n    for imglen in imglens:\\n        batch_images.append(images[:imglen])\\n        images = images[imglen:]\\n\\n    return batch_images\\n\\n\\ndef _check_video_is_nested_images(video: \\\"VideoInput\\\") -> bool:\\n    r\\\"\\\"\\\"Check if the video is nested images.\\\"\\\"\\\"\\n    return isinstance(video, list) and all(isinstance(frame, (str, BinaryIO, dict, ImageObject)) for frame in video)\\n\\n\\n@dataclass\\nclass MMPluginMixin:\\n    image_token: str | None\\n    video_token: str | None\\n    audio_token: str | None\\n    expand_mm_tokens: bool = True\\n\\n    def _validate_input(\\n        self,\\n        processor: Optional[\\\"MMProcessor\\\"],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n    ) -> None:\\n        r\\\"\\\"\\\"Validate if this model accepts the input modalities.\\\"\\\"\\\"\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseImageProcessor = getattr(\\n            processor, \\\"video_processor\\\", getattr(processor, \\\"image_processor\\\", None)\\n        )\\n        feature_extractor: SequenceFeatureExtractor = getattr(processor, \\\"feature_extractor\\\", None) or getattr(\\n            processor, \\\"audio_processor\\\", None\\n        )\\n        if len(images) != 0 and self.image_token is None:\\n            raise ValueError(\\n                \\\"This model does not support image input. Please check whether the correct `template` is used.\\\"\\n            )\\n\\n        if len(videos) != 0 and self.video_token is None:\\n            raise ValueError(\\n                \\\"This model does not support video input. Please check whether the correct `template` is used.\\\"\\n            )\\n\\n        if len(audios) != 0 and self.audio_token is None:\\n            raise ValueError(\\n                \\\"This model does not support audio input. Please check whether the correct `template` is used.\\\"\\n            )\\n\\n        if self.image_token is not None and processor is None:\\n            raise ValueError(\\\"Processor was not found, please check and update your model file.\\\")\\n\\n        if self.image_token is not None and image_processor is None:\\n            raise ValueError(\\\"Image processor was not found, please check and update your model file.\\\")\\n\\n        if self.video_token is not None and video_processor is None:\\n            raise ValueError(\\\"Video processor was not found, please check and update your model file.\\\")\\n\\n        if self.audio_token is not None and feature_extractor is None:\\n            raise ValueError(\\\"Audio feature extractor was not found, please check and update your model file.\\\")\\n\\n    def _validate_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n    ):\\n        r\\\"\\\"\\\"Validate if the number of images, videos and audios match the number of placeholders in messages.\\\"\\\"\\\"\\n        num_image_tokens, num_video_tokens, num_audio_tokens = 0, 0, 0\\n        for message in messages:\\n            num_image_tokens += message[\\\"content\\\"].count(IMAGE_PLACEHOLDER)\\n            num_video_tokens += message[\\\"content\\\"].count(VIDEO_PLACEHOLDER)\\n            num_audio_tokens += message[\\\"content\\\"].count(AUDIO_PLACEHOLDER)\\n\\n        if len(images) != num_image_tokens:\\n            raise ValueError(\\n                f\\\"The number of images does not match the number of {IMAGE_PLACEHOLDER} tokens in {messages}.\\\"\\n            )\\n\\n        if len(videos) != num_video_tokens:\\n            raise ValueError(\\n                f\\\"The number of videos does not match the number of {VIDEO_PLACEHOLDER} tokens in {messages}.\\\"\\n            )\\n\\n        if len(audios) != num_audio_tokens:\\n            raise ValueError(\\n                f\\\"The number of audios does not match the number of {AUDIO_PLACEHOLDER} tokens in {messages}.\\\"\\n            )\\n\\n    def _preprocess_image(\\n        self, image: \\\"ImageObject\\\", image_max_pixels: int, image_min_pixels: int, **kwargs\\n    ) -> \\\"ImageObject\\\":\\n        r\\\"\\\"\\\"Pre-process a single image.\\\"\\\"\\\"\\n        if (image.width * image.height) > image_max_pixels:\\n            resize_factor = math.sqrt(image_max_pixels / (image.width * image.height))\\n            width, height = int(image.width * resize_factor), int(image.height * resize_factor)\\n            image = image.resize((width, height))\\n\\n        if (image.width * image.height) < image_min_pixels:\\n            resize_factor = math.sqrt(image_min_pixels / (image.width * image.height))\\n            width, height = int(image.width * resize_factor), int(image.height * resize_factor)\\n            image = image.resize((width, height))\\n\\n        if image.mode != \\\"RGB\\\":\\n            image = image.convert(\\\"RGB\\\")\\n\\n        return image\\n\\n    def _get_video_sample_indices(\\n        self, video_stream: \\\"Stream\\\", video_fps: float, video_maxlen: int, **kwargs\\n    ) -> list[int]:\\n        r\\\"\\\"\\\"Compute video sample indices according to fps.\\\"\\\"\\\"\\n        total_frames = video_stream.frames\\n        if total_frames == 0:  # infinite video\\n            return np.linspace(0, video_maxlen - 1, video_maxlen).astype(np.int32)\\n\\n        sample_frames = max(1, math.floor(float(video_stream.duration * video_stream.time_base) * video_fps))\\n        sample_frames = min(total_frames, video_maxlen, sample_frames)\\n        return np.linspace(0, total_frames - 1, sample_frames).astype(np.int32)\\n\\n    def _get_video_token_metadata(\\n        self,\\n        videos: list[\\\"VideoInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> Optional[dict[str, Any]]:\\n        r\\\"\\\"\\\"Build metadata used to expand video tokens without decoding frames.\\\"\\\"\\\"\\n        return None\\n\\n    def _regularize_images(self, images: list[\\\"ImageInput\\\"], **kwargs) -> \\\"RegularizedImageOutput\\\":\\n        r\\\"\\\"\\\"Regularize images to avoid error. Including reading and pre-processing.\\\"\\\"\\\"\\n        results = []\\n        for image in images:\\n            if isinstance(image, (str, BinaryIO)):\\n                image = Image.open(image)\\n            elif isinstance(image, bytes):\\n                image = Image.open(BytesIO(image))\\n            elif isinstance(image, dict):\\n                if image[\\\"bytes\\\"] is not None:\\n                    image = Image.open(BytesIO(image[\\\"bytes\\\"]))\\n                else:\\n                    image = Image.open(image[\\\"path\\\"])\\n\\n            if not isinstance(image, ImageObject):\\n                raise ValueError(f\\\"Expect input is a list of images, but got {type(image)}.\\\")\\n\\n            results.append(self._preprocess_image(image, **kwargs))\\n\\n        return {\\\"images\\\": results}\\n\\n    def _regularize_videos(self, videos: list[\\\"VideoInput\\\"], **kwargs) -> \\\"RegularizedVideoOutput\\\":\\n        r\\\"\\\"\\\"Regularizes videos to avoid error. Including reading, resizing and converting.\\\"\\\"\\\"\\n        results = []\\n        durations = []\\n        for video in videos:\\n            frames: list[ImageObject] = []\\n            if _check_video_is_nested_images(video):\\n                for frame in video:\\n                    if not is_valid_image(frame) and not isinstance(frame, dict) and not os.path.exists(frame):\\n                        raise ValueError(\\\"Invalid image found in video frames.\\\")\\n                frames = video\\n                durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n            else:\\n                container = av.open(video, \\\"r\\\")\\n                video_stream = next(stream for stream in container.streams if stream.type == \\\"video\\\")\\n                sample_indices = self._get_video_sample_indices(video_stream, **kwargs)\\n                container.seek(0)\\n                for frame_idx, frame in enumerate(container.decode(video_stream)):\\n                    if frame_idx in sample_indices:\\n                        frames.append(frame.to_image())\\n\\n                if video_stream.duration is None:\\n                    durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n                else:\\n                    durations.append(float(video_stream.duration * video_stream.time_base))\\n\\n            frames = self._regularize_images(frames, **kwargs)[\\\"images\\\"]\\n            results.append(frames)\\n\\n        return {\\\"videos\\\": results, \\\"durations\\\": durations}\\n\\n    def _regularize_audios(\\n        self, audios: list[\\\"AudioInput\\\"], sampling_rate: float, **kwargs\\n    ) -> \\\"RegularizedAudioOutput\\\":\\n        r\\\"\\\"\\\"Regularizes audios to avoid error. Including reading and resampling.\\\"\\\"\\\"\\n        results, sampling_rates = [], []\\n        for audio in audios:\\n            if not isinstance(audio, np.ndarray):\\n                audio, sr = torchaudio.load(audio)\\n                if audio.shape[0] > 1:\\n                    audio = audio.mean(dim=0, keepdim=True)\\n\\n                if sr != sampling_rate:\\n                    audio = torchaudio.functional.resample(audio, sr, sampling_rate)\\n\\n                audio = audio.squeeze(0).numpy()\\n\\n            results.append(audio)\\n            sampling_rates.append(sampling_rate)\\n\\n        return {\\\"audios\\\": results, \\\"sampling_rates\\\": sampling_rates}\\n\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n        imglens: list[int] | None = None,\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Process visual inputs.\\n\\n        Returns: (llava and paligemma)\\n            pixel_values: tensor with shape (B, C, H, W)\\n\\n        Returns: (qwen2-vl)\\n            pixel_values: tensor with shape (num_patches, patch_dim)\\n            image_grid_thw: tensor with shape (num_images, 3), where the three numbers are time, width, height\\n                            where num_patches == torch.prod(image_grid_thw)\\n\\n        Returns: (mllama)\\n            pixel_values: tensor with shape\\n                          (batch_size, max_num_images, max_image_tiles, channels, tile_height, tile_width)\\n                          For example, (2, 1, 4, 3, 560, 560).\\n            aspect_ratio_ids: tensor with shape (batch_size, max_num_images). For example, (2, 1).\\n            aspect_ratio_mask: tensor with shape (batch_size, max_num_images, max_image_tiles). For example, (2, 1, 4).\\n            num_tiles: List[List[int]] with shape (batch_size, num_images_in_batch). For example, (2, 1).\\n\\n        \\\"\\\"\\\"\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            if imglens is not None:  # if imglens are provided, make batched images\\n                images = _make_batched_images(images, imglens)\\n\\n            image_processor_kwargs = {}\\n            if getattr(processor, \\\"image_do_pan_and_scan\\\", False):  # gemma3 image processor\\n                image_processor_kwargs.update(\\n                    {\\n                        \\\"do_pan_and_scan\\\": True,\\n                        \\\"pan_and_scan_min_crop_size\\\": 256,\\n                        \\\"pan_and_scan_max_num_crops\\\": 4,\\n                        \\\"pan_and_scan_min_ratio_to_activate\\\": 1.2,\\n                    }\\n                )\\n\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\", **image_processor_kwargs))\\n\\n        if len(videos) != 0:\\n            video_processor: BaseImageProcessor = getattr(\\n                processor, \\\"video_processor\\\", getattr(processor, \\\"image_processor\\\", None)\\n            )\\n            videos = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )[\\\"videos\\\"]\\n            if \\\"videos\\\" in inspect.signature(video_processor.preprocess).parameters:  # for qwen2_vl and video_llava\\n                mm_inputs.update(video_processor(images=None, videos=videos, return_tensors=\\\"pt\\\"))\\n            else:  # for llava_next_video\\n                mm_inputs.update(video_processor(videos, return_tensors=\\\"pt\\\"))\\n\\n        if len(audios) != 0:\\n            feature_extractor: SequenceFeatureExtractor = getattr(processor, \\\"feature_extractor\\\", None) or getattr(\\n                processor, \\\"audio_processor\\\", None\\n            )\\n            audios = self._regularize_audios(\\n                audios,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )[\\\"audios\\\"]\\n            mm_inputs.update(\\n                feature_extractor(\\n                    audios,\\n                    sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n                    return_attention_mask=True,\\n                    padding=\\\"max_length\\\",\\n                    return_tensors=\\\"pt\\\",\\n                )\\n            )\\n            mm_inputs[\\\"feature_attention_mask\\\"] = mm_inputs.pop(\\\"attention_mask\\\", None)  # prevent conflicts\\n\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass BasePlugin(MMPluginMixin):\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        r\\\"\\\"\\\"Pre-process input messages before tokenization for VLMs.\\\"\\\"\\\"\\n        self._validate_input(processor, images, videos, audios)\\n        return messages\\n\\n    def process_token_ids(\\n        self,\\n        input_ids: list[int],\\n        labels: list[int] | None,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> tuple[list[int], list[int] | None]:\\n        r\\\"\\\"\\\"Pre-process token ids after tokenization for VLMs.\\\"\\\"\\\"\\n        self._validate_input(processor, images, videos, audios)\\n        return input_ids, labels\\n\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Build batched multimodal inputs for VLMs.\\n\\n        Arguments:\\n            images: a list of image inputs, shape (num_images,)\\n            videos: a list of video inputs, shape (num_videos,)\\n            audios: a list of audio inputs, shape (num_audios,)\\n            imglens: number of images in each sample, shape (batch_size,)\\n            vidlens: number of videos in each sample, shape (batch_size,)\\n            audlens: number of audios in each sample, shape (batch_size,)\\n            batch_ids: token ids of input samples, shape (batch_size, seq_len)\\n            processor: a processor for pre-processing images and videos\\n\\n        \\\"\\\"\\\"\\n        self._validate_input(processor, images, videos, audios)\\n        return self._get_mm_inputs(images, videos, audios, processor)\\n\\n\\n@dataclass\\nclass MossVLPlugin(BasePlugin):\\n    vision_bos_token: str = \\\"<|vision_start|>\\\"\\n    vision_eos_token: str = \\\"<|vision_end|>\\\"\\n    time_bos_token: str = \\\"<|time_start|>\\\"\\n    time_eos_token: str = \\\"<|time_end|>\\\"\\n\\n    @staticmethod\\n    def _split_pixel_values(\\n        pixel_values: \\\"torch.Tensor\\\",\\n        grid_thw: \\\"torch.Tensor\\\",\\n    ) -> list[\\\"torch.Tensor\\\"]:\\n        patch_counts = [int(grid.prod().item()) for grid in grid_thw]\\n        return list(torch.split(pixel_values, patch_counts))\\n\\n    @staticmethod\\n    def _create_cross_attention_mask(\\n        input_ids: Union[list[list[int]], \\\"torch.Tensor\\\"],\\n        grid_thw: \\\"torch.Tensor\\\",\\n        media_nums_per_sample: list[int],\\n        image_token_id: int,\\n        attention_mask: Optional[\\\"torch.Tensor\\\"] = None,\\n        padding_side: Literal[\\\"left\\\", \\\"right\\\"] = \\\"right\\\",\\n    ) -> \\\"torch.Tensor\\\":\\n        r\\\"\\\"\\\"Create the native MOSS-VL frame-level causal cross-attention mask.\\\"\\\"\\\"\\n        if isinstance(input_ids, list):\\n            max_text_len = max(len(token_ids) for token_ids in input_ids)\\n            input_ids_tensor = torch.full((len(input_ids), max_text_len), -1, dtype=torch.long)\\n            attention_mask_tensor = torch.zeros_like(input_ids_tensor, dtype=torch.bool)\\n            for batch_index, token_ids in enumerate(input_ids):\\n                seq_len = len(token_ids)\\n                start = max_text_len - seq_len if padding_side == \\\"left\\\" else 0\\n                input_ids_tensor[batch_index, start : start + seq_len] = torch.tensor(token_ids, dtype=torch.long)\\n                attention_mask_tensor[batch_index, start : start + seq_len] = True\\n        else:\\n            input_ids_tensor = input_ids\\n            attention_mask_tensor = (\\n                torch.ones_like(input_ids_tensor, dtype=torch.bool)\\n                if attention_mask is None\\n                else attention_mask.bool()\\n            )\\n\\n        total_frames_per_sample = []\\n        media_index = 0\\n        for num_media in media_nums_per_sample:\\n            sample_grid = grid_thw[media_index : media_index + num_media]\\n            total_frames_per_sample.append(int(sample_grid[:, 0].sum().item()))\\n            media_index += num_media\\n\\n        max_num_frames = max(total_frames_per_sample)\\n        frame_indices = torch.arange(max_num_frames, device=input_ids_tensor.device).view(1, 1, -1)\\n        visible_mask = (input_ids_tensor == image_token_id).cumsum(dim=1).unsqueeze(-1) > frame_indices\\n        visible_mask &= attention_mask_tensor.unsqueeze(-1)\\n        valid_frames = frame_indices < torch.tensor(\\n            total_frames_per_sample,\\n            device=input_ids_tensor.device,\\n        ).view(-1, 1, 1)\\n        visible_mask &= valid_frames\\n        return (~visible_mask).unsqueeze(1)\\n\\n    def _get_video_inputs(\\n        self,\\n        videos: list[\\\"VideoInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n        return_metadata: bool,\\n    ) -> dict[str, Any]:\\n        video_kwargs = {\\\"return_tensors\\\": \\\"pt\\\", \\\"return_metadata\\\": return_metadata}\\n        if getattr(processor, \\\"video_fps\\\", None) is not None:\\n            video_kwargs[\\\"video_fps\\\"] = processor.video_fps\\n        if getattr(processor, \\\"video_maxlen\\\", None) is not None:\\n            video_kwargs[\\\"max_frames\\\"] = processor.video_maxlen\\n\\n        video_min_pixels = getattr(processor, \\\"video_min_pixels\\\", None)\\n        video_max_pixels = getattr(processor, \\\"video_max_pixels\\\", None)\\n        if video_min_pixels is not None and video_max_pixels is not None:\\n            video_kwargs[\\\"size\\\"] = {\\n                \\\"shortest_edge\\\": video_min_pixels,\\n                \\\"longest_edge\\\": video_max_pixels,\\n            }\\n\\n        return dict(processor.video_processor(videos=videos, **video_kwargs))\\n\\n    def _get_media_order_from_ids(\\n        self,\\n        input_ids: list[int],\\n        processor: \\\"MMProcessor\\\",\\n        num_images: int,\\n        num_videos: int,\\n        expected_video_frames: Optional[list[int]] = None,\\n    ) -> list[str]:\\n        media_order = []\\n        video_frame_counts = []\\n        in_video = False\\n        current_video_frames = 0\\n        for token_id in input_ids:\\n            if token_id == processor.vision_start_token_id:\\n                if in_video:\\n                    raise ValueError(\\n                        \\\"MOSS-VL encountered nested video token blocks after tokenization. \\\"\\n                        \\\"Please increase `cutoff_len` if a video placeholder was truncated.\\\"\\n                    )\\n\\n                media_order.append(\\\"video\\\")\\n                in_video = True\\n                current_video_frames = 0\\n            elif token_id == processor.vision_end_token_id:\\n                if not in_video:\\n                    raise ValueError(\\n                        \\\"MOSS-VL encountered a video end token without a matching start token after tokenization. \\\"\\n                        \\\"Please increase `cutoff_len` if a video placeholder was truncated.\\\"\\n                    )\\n\\n                video_frame_counts.append(current_video_frames)\\n                in_video = False\\n            elif token_id == processor.image_token_id:\\n                if in_video:\\n                    current_video_frames += 1\\n                else:\\n                    media_order.append(\\\"image\\\")\\n\\n        if in_video:\\n            raise ValueError(\\n                \\\"MOSS-VL encountered an incomplete video token block after tokenization. \\\"\\n                \\\"Please increase `cutoff_len` or reduce `video_maxlen`.\\\"\\n            )\\n\\n        if media_order.count(\\\"image\\\") != num_images or media_order.count(\\\"video\\\") != num_videos:\\n            raise ValueError(\\n                \\\"MOSS-VL media tokens do not match the provided media after tokenization: \\\"\\n                f\\\"order={media_order}, images={num_images}, videos={num_videos}. \\\"\\n                \\\"Please increase `cutoff_len` if a visual placeholder was truncated.\\\"\\n            )\\n\\n        if expected_video_frames is not None and video_frame_counts != expected_video_frames:\\n            raise ValueError(\\n                \\\"MOSS-VL video frame tokens do not match the processed video after tokenization: \\\"\\n                f\\\"tokens={video_frame_counts}, frames={expected_video_frames}. \\\"\\n                \\\"Please increase `cutoff_len` or reduce `video_maxlen`.\\\"\\n            )\\n\\n        return media_order\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n\\n        video_inputs = self._get_video_inputs(videos, processor, return_metadata=True) if videos else {}\\n        video_grid_thw = video_inputs.get(\\\"video_grid_thw\\\", [])\\n        video_metadata = video_inputs.get(\\\"video_metadata\\\", [])\\n        video_index = 0\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            content = content.replace(IMAGE_PLACEHOLDER, self.image_token)\\n            while VIDEO_PLACEHOLDER in content:\\n                metadata = video_metadata[video_index]\\n                if metadata.fps is None:\\n                    metadata.fps = 24\\n\\n                timestamps = processor._calculate_timestamps(\\n                    metadata.frames_indices,\\n                    metadata.total_num_frames,\\n                    metadata.fps,\\n                    metadata.duration,\\n                    processor.video_processor.temporal_patch_size,\\n                    actual_timestamps=getattr(metadata, \\\"actual_timestamps\\\", None),\\n                )\\n                num_frames = int(video_grid_thw[video_index][0].item())\\n                frame_tokens = [\\n                    f\\\"{self.time_bos_token}{timestamps[frame_idx]:.1f} seconds{self.time_eos_token}{self.image_token}\\\"\\n                    for frame_idx in range(num_frames)\\n                ]\\n                video_tokens = f\\\"{self.vision_bos_token}{''.join(frame_tokens)}{self.vision_eos_token}\\\"\\n                content = content.replace(VIDEO_PLACEHOLDER, video_tokens, 1)\\n                video_index += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        if audios:\\n            raise ValueError(\\\"MOSS-VL does not support audio inputs.\\\")\\n\\n        if not (len(imglens) == len(vidlens) == len(batch_ids)):\\n            raise ValueError(\\\"MOSS-VL batch metadata must have one entry per sample.\\\")\\n        final_pixel_values = []\\n        final_grid_thw = []\\n        media_nums_per_sample = []\\n        image_offset = 0\\n        video_offset = 0\\n        for imglen, vidlen, input_ids in zip(imglens, vidlens, batch_ids):\\n            sample_images = images[image_offset : image_offset + imglen]\\n            sample_videos = videos[video_offset : video_offset + vidlen]\\n            image_offset += imglen\\n            video_offset += vidlen\\n            image_chunks, image_grids = [], []\\n            if sample_images:\\n                regularized_images = self._regularize_images(\\n                    sample_images,\\n                    image_max_pixels=2**63 - 1,\\n                    image_min_pixels=1,\\n                )[\\\"images\\\"]\\n                image_kwargs = {\\\"return_tensors\\\": \\\"pt\\\"}\\n                if getattr(processor, \\\"image_min_pixels\\\", None) is not None:\\n                    image_kwargs[\\\"min_pixels\\\"] = processor.image_min_pixels\\n                if getattr(processor, \\\"image_max_pixels\\\", None) is not None:\\n                    image_kwargs[\\\"max_pixels\\\"] = processor.image_max_pixels\\n\\n                image_inputs = processor.image_processor(images=regularized_images, **image_kwargs)\\n                image_grids = list(image_inputs[\\\"image_grid_thw\\\"])\\n                image_chunks = self._split_pixel_values(image_inputs[\\\"pixel_values\\\"], image_inputs[\\\"image_grid_thw\\\"])\\n\\n            video_chunks, video_grids = [], []\\n            if sample_videos:\\n                video_inputs = self._get_video_inputs(sample_videos, processor, return_metadata=False)\\n                video_grids = list(video_inputs[\\\"video_grid_thw\\\"])\\n                video_chunks = self._split_pixel_values(\\n                    video_inputs[\\\"pixel_values_videos\\\"],\\n                    video_inputs[\\\"video_grid_thw\\\"],\\n                )\\n\\n            media_order = self._get_media_order_from_ids(\\n                input_ids,\\n                processor,\\n                imglen,\\n                vidlen,\\n                expected_video_frames=[int(grid[0].item()) for grid in video_grids],\\n            )\\n\\n            if not media_order:\\n                patch_size = getattr(processor.image_processor, \\\"patch_size\\\", None)\\n                if patch_size is None:  # lightweight/test processors without the native MOSS-VL contract\\n                    blank_image = Image.new(\\\"RGB\\\", (128, 128), (255, 255, 255))\\n                    blank_inputs = processor.image_processor(images=[blank_image], return_tensors=\\\"pt\\\")\\n                    final_pixel_values.append(blank_inputs[\\\"pixel_values\\\"])\\n                    final_grid_thw.append(blank_inputs[\\\"image_grid_thw\\\"][0])\\n                else:\\n                    temporal_patch_size = getattr(processor.image_processor, \\\"temporal_patch_size\\\", None) or 1\\n                    merge_size = getattr(processor.image_processor, \\\"merge_size\\\", None) or 2\\n                    factor = patch_size * merge_size\\n                    side = math.ceil(128 / factor) * factor\\n                    grid_thw = torch.tensor([1, side // patch_size, side // patch_size])\\n                    feature_dim = 3 * temporal_patch_size * patch_size * patch_size\\n                    final_pixel_values.append(torch.zeros((int(grid_thw.prod()), feature_dim), dtype=torch.float32))\\n                    final_grid_thw.append(grid_thw)\\n                media_nums_per_sample.append(1)\\n                continue\\n\\n            image_index = 0\\n            video_index = 0\\n            for modality in media_order:\\n                if modality == \\\"image\\\":\\n                    final_pixel_values.append(image_chunks[image_index])\\n                    final_grid_thw.append(image_grids[image_index])\\n                    image_index += 1\\n                else:\\n                    final_pixel_values.append(video_chunks[video_index])\\n                    final_grid_thw.append(video_grids[video_index])\\n                    video_index += 1\\n\\n            media_nums_per_sample.append(len(media_order))\\n\\n        if image_offset != len(images) or video_offset != len(videos):\\n            raise ValueError(\\\"MOSS-VL media lengths do not consume all provided inputs.\\\")\\n\\n        mm_inputs = {\\n            \\\"pixel_values\\\": torch.cat(final_pixel_values, dim=0),\\n            \\\"grid_thw\\\": torch.stack(final_grid_thw),\\n            \\\"media_nums_per_sample\\\": media_nums_per_sample,\\n        }\\n        mm_inputs[\\\"cross_attention_mask\\\"] = self._create_cross_attention_mask(\\n            batch_ids,\\n            mm_inputs[\\\"grid_thw\\\"],\\n            media_nums_per_sample,\\n            processor.image_token_id,\\n            padding_side=processor.tokenizer.padding_side,\\n        )\\n        return mm_inputs\\n\\n    def post_process_mossvl_inputs(\\n        self,\\n        features: dict[str, \\\"torch.Tensor\\\"],\\n        mm_inputs: dict[str, Any],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, Any]:\\n        r\\\"\\\"\\\"Create MOSS-VL batch-only inputs after the text batch has been padded.\\\"\\\"\\\"\\n        input_ids = features[\\\"input_ids\\\"]\\n        attention_mask = features[\\\"attention_mask\\\"].bool()\\n        mm_inputs[\\\"cross_attention_mask\\\"] = self._create_cross_attention_mask(\\n            input_ids,\\n            mm_inputs[\\\"grid_thw\\\"],\\n            mm_inputs[\\\"media_nums_per_sample\\\"],\\n            processor.image_token_id,\\n            attention_mask,\\n        )\\n\\n        dummy_image_tokens = (input_ids == processor.image_token_id) & ~attention_mask\\n        input_ids.masked_fill_(dummy_image_tokens, processor.tokenizer.pad_token_id)\\n\\n        labels = features.get(\\\"labels\\\")\\n        if labels is not None:\\n            control_token_ids = {\\n                processor.image_token_id,\\n                processor.video_token_id,\\n                processor.vision_start_token_id,\\n                processor.vision_end_token_id,\\n                processor.tokenizer.convert_tokens_to_ids(self.time_bos_token),\\n                processor.tokenizer.convert_tokens_to_ids(self.time_eos_token),\\n            }\\n            for batch_index, token_ids in enumerate(input_ids):\\n                in_vision = False\\n                for token_index, token_id in enumerate(token_ids.tolist()):\\n                    if token_id == processor.vision_start_token_id:\\n                        in_vision = True\\n                    if in_vision or token_id in control_token_ids:\\n                        labels[batch_index, token_index] = IGNORE_INDEX\\n                    if token_id == processor.vision_end_token_id:\\n                        in_vision = False\\n\\n            # Native MOSS-VL labels_spans supervise through <|im_end|>, but not its trailing newline.\\n            im_end_token_id = processor.tokenizer.convert_tokens_to_ids(\\\"<|im_end|>\\\")\\n            labels[:, 1:].masked_fill_(input_ids[:, :-1] == im_end_token_id, IGNORE_INDEX)\\n\\n        features.pop(\\\"position_ids\\\", None)\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass ErnieVLPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n\\n        merge_length: int = getattr(image_processor, \\\"merge_size\\\") ** 2\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            image_grid_thw = mm_inputs.get(\\\"image_grid_thw\\\", [])\\n            video_grid_thw = mm_inputs.get(\\\"video_grid_thw\\\", [])\\n        else:\\n            image_grid_thw = [None] * len(images)\\n            video_grid_thw = [None] * len(videos)\\n\\n        image_idx, video_idx = 0, 0\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            image_token = self.image_token or \\\"<|IMAGE_PLACEHOLDER|>\\\"\\n            video_token = self.video_token or \\\"<|VIDEO_PLACEHOLDER|>\\\"\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = image_grid_thw[image_idx].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"Picture {image_idx + 1}:<|IMAGE_START|>{image_token * image_seqlen}<|IMAGE_END|>\\\",\\n                    1,\\n                )\\n                image_idx += 1\\n            while VIDEO_PLACEHOLDER in content:\\n                video_seqlen = video_grid_thw[video_idx].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    VIDEO_PLACEHOLDER,\\n                    f\\\"Video {video_idx + 1}:<|VIDEO_START|>{video_token * video_seqlen}<|VIDEO_END|>\\\",\\n                    1,\\n                )\\n                video_idx += 1\\n            message[\\\"content\\\"] = content\\n        return messages\\n\\n\\n@dataclass\\nclass Gemma3Plugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        boi_token: str = getattr(processor, \\\"boi_token\\\")\\n        full_image_sequence: str = getattr(processor, \\\"full_image_sequence\\\")\\n        image_str = full_image_sequence if self.expand_mm_tokens else boi_token\\n\\n        do_pan_and_scan: bool = getattr(processor, \\\"image_do_pan_and_scan\\\", False)\\n        if do_pan_and_scan:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                if do_pan_and_scan:\\n                    image_placeholder_str = (\\n                        \\\"Here is the original image {{image}} and here are some crops to help you see better \\\"\\n                        + \\\" \\\".join([\\\"{{image}}\\\"] * mm_inputs[\\\"num_crops\\\"][0][num_image_tokens])\\n                    )\\n                else:\\n                    image_placeholder_str = \\\"{{image}}\\\"\\n\\n                content = content.replace(IMAGE_PLACEHOLDER, image_placeholder_str, 1)\\n                num_image_tokens += 1\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", image_str)\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        mm_inputs.pop(\\\"num_crops\\\", None)\\n        mm_inputs[\\\"token_type_ids\\\"] = _get_gemma3_token_type_ids(batch_ids, processor)\\n        return mm_inputs\\n\\n\\nclass Gemma3nPlugin(Gemma3Plugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n        boi_token: str = getattr(processor, \\\"boi_token\\\")\\n        boa_token: str = getattr(processor, \\\"boa_token\\\")\\n        full_image_sequence: str = getattr(processor, \\\"full_image_sequence\\\")\\n        full_audio_sequence: str = getattr(processor, \\\"full_audio_sequence\\\")\\n        image_str = full_image_sequence if self.expand_mm_tokens else boi_token\\n        audio_str = full_audio_sequence if self.expand_mm_tokens else boa_token\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, image_str, 1)\\n\\n            while AUDIO_PLACEHOLDER in content:\\n                content = content.replace(AUDIO_PLACEHOLDER, audio_str, 1)\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\n@dataclass\\nclass Gemma4Plugin(BasePlugin):\\n    r\\\"\\\"\\\"Plugin for the Gemma4 multimodal model.\\\"\\\"\\\"\\n\\n    @override\\n    def _regularize_videos(self, videos: list[\\\"VideoInput\\\"], **kwargs) -> \\\"RegularizedVideoOutput\\\":\\n        r\\\"\\\"\\\"Regularize videos, also tracking per-video FPS and frame indices for timestamp generation.\\\"\\\"\\\"\\n        results, fps_per_video, durations, frames_indices = [], [], [], []\\n        for video in videos:\\n            frames: list[ImageObject] = []\\n            if _check_video_is_nested_images(video):\\n                frames = video\\n                fps_per_video.append(kwargs.get(\\\"video_fps\\\", 2.0))\\n                durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n                frames_indices.append(list(range(len(frames))))\\n            else:\\n                container = av.open(video, \\\"r\\\")\\n                video_stream = next(stream for stream in container.streams if stream.type == \\\"video\\\")\\n                sample_indices = self._get_video_sample_indices(video_stream, **kwargs)\\n                original_fps = float(video_stream.average_rate)\\n                # for correctly calculate timestamps\\n                frames_indices.append([idx / original_fps * kwargs.get(\\\"video_fps\\\", 2.0) for idx in sample_indices])\\n                container.seek(0)\\n                for frame_idx, frame in enumerate(container.decode(video_stream)):\\n                    if frame_idx in sample_indices:\\n                        frames.append(frame.to_image())\\n\\n                if video_stream.duration is None:\\n                    durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n                else:\\n                    durations.append(float(video_stream.duration * video_stream.time_base))\\n\\n            frames = self._regularize_images(frames, **kwargs)[\\\"images\\\"]\\n            results.append(frames)\\n\\n        return {\\n            \\\"videos\\\": results,\\n            \\\"fps_per_video\\\": fps_per_video,\\n            \\\"durations\\\": durations,\\n            \\\"frames_indices\\\": frames_indices,\\n        }\\n\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        image_processor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor = getattr(processor, \\\"video_processor\\\", None)\\n        feature_extractor = getattr(processor, \\\"feature_extractor\\\", None)\\n        mm_inputs = {}\\n\\n        if len(images) != 0:\\n            regularized = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(regularized, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            video_data = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )\\n            video_metadata = [\\n                {\\n                    \\\"fps\\\": getattr(processor, \\\"video_fps\\\", 2.0),\\n                    \\\"duration\\\": duration,\\n                    \\\"total_num_frames\\\": len(video),\\n                    \\\"frames_indices\\\": sample_indices,\\n                }\\n                for video, duration, sample_indices in zip(\\n                    video_data[\\\"videos\\\"], video_data[\\\"durations\\\"], video_data[\\\"frames_indices\\\"]\\n                )\\n            ]\\n            mm_inputs.update(\\n                video_processor(\\n                    videos=video_data[\\\"videos\\\"],\\n                    video_metadata=video_metadata,\\n                    return_tensors=\\\"pt\\\",\\n                    return_metadata=True,\\n                    do_sample_frames=False,\\n                )\\n            )\\n\\n        if len(audios) != 0:  # only for gemma4n\\n            audios = self._regularize_audios(\\n                audios,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )[\\\"audios\\\"]\\n\\n            mm_inputs.update(\\n                feature_extractor(\\n                    audios,\\n                    padding=\\\"max_length\\\",\\n                    return_tensors=\\\"pt\\\",\\n                )\\n            )\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n\\n        boi_token: str = getattr(processor, \\\"boi_token\\\")\\n        eoi_token: str = getattr(processor, \\\"eoi_token\\\")\\n        boa_token: str = getattr(processor, \\\"boa_token\\\")\\n        eoa_token: str = getattr(processor, \\\"eoa_token\\\")\\n        image_token: str = getattr(processor, \\\"image_token\\\")\\n        video_token: str = getattr(processor, \\\"video_token\\\")\\n        audio_token: str = getattr(processor, \\\"audio_token\\\")\\n\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            num_image_soft_tokens: list[int] = list(\\n                mm_inputs.get(\\\"num_soft_tokens_per_image\\\", [getattr(processor, \\\"image_seq_length\\\", 256)] * len(images))\\n            )\\n            num_video_soft_tokens: list[int] = list(mm_inputs.get(\\\"num_soft_tokens_per_video\\\", [1] * len(videos)))\\n            video_metadata = mm_inputs.get(\\\"video_metadata\\\", [])\\n        else:\\n            num_image_soft_tokens = [1] * len(images)\\n            num_video_soft_tokens = [1] * len(videos)\\n            video_metadata = [None] * len(videos)\\n\\n        audio_iter = iter(audios)\\n        image_iter = iter(num_image_soft_tokens)\\n        video_iter = iter(zip(num_video_soft_tokens, video_metadata))\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n\\n            while IMAGE_PLACEHOLDER in content:\\n                n = next(image_iter)\\n                content = content.replace(IMAGE_PLACEHOLDER, f\\\"{boi_token}{image_token * n}{eoi_token}\\\", 1)\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                num_soft_tokens_per_frame, metadata = next(video_iter)\\n                if self.expand_mm_tokens:\\n                    timestamp_strs = [f\\\"{int(t // 60):02d}:{int(t % 60):02d}\\\" for t in metadata.timestamps]\\n                    frame_strs = [\\n                        f\\\"{ts} {boi_token}{video_token * num_soft_tokens_per_frame}{eoi_token}\\\"\\n                        for ts in timestamp_strs\\n                    ]\\n                    video_str = \\\" \\\".join(frame_strs)\\n                else:\\n                    video_str = f\\\"{boi_token}{video_token * num_soft_tokens_per_frame}{eoi_token}\\\"\\n                content = content.replace(VIDEO_PLACEHOLDER, video_str, 1)\\n\\n            while AUDIO_PLACEHOLDER in content:\\n                current_audio = next(audio_iter)\\n                if self.expand_mm_tokens:\\n                    num_audio_tokens = processor._compute_audio_num_tokens(\\n                        current_audio, processor.feature_extractor.sampling_rate\\n                    )\\n                    audio_str = f\\\"{boa_token}{audio_token * num_audio_tokens}{eoa_token}\\\"\\n                else:\\n                    audio_str = f\\\"{boa_token}{audio_token}{eoa_token}\\\"\\n\\n                content = content.replace(AUDIO_PLACEHOLDER, audio_str, 1)\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        # Pop metadata keys that must not be passed to the model.\\n        for key in (\\n            \\\"num_soft_tokens_per_image\\\",\\n            \\\"num_soft_tokens_per_video\\\",\\n            \\\"video_metadata\\\",\\n            \\\"_gemma4_fps_per_video\\\",\\n            \\\"_gemma4_frames_indices\\\",\\n            \\\"_gemma4_num_audio_soft_tokens\\\",\\n        ):\\n            mm_inputs.pop(key, None)\\n\\n        mm_inputs[\\\"mm_token_type_ids\\\"] = processor.create_mm_token_type_ids(batch_ids)\\n\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass InternVLPlugin(BasePlugin):\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"ProcessorMixin\\\",\\n        **kwargs,\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        image_processor_kwargs = {}\\n        if getattr(processor, \\\"crop_to_patches\\\", False):\\n            image_processor_kwargs.update(\\n                {\\n                    \\\"crop_to_patches\\\": True,\\n                    \\\"max_patches\\\": 12,\\n                    \\\"min_patches\\\": 1,\\n                }\\n            )\\n\\n        mm_inputs = {}\\n        image_video_patches = []\\n\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 1024 * 1024),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n\\n        if len(videos) != 0:\\n            videos = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )[\\\"videos\\\"]\\n\\n        if len(images) != 0:\\n            images = make_flat_list_of_images(images)\\n            image_inputs = image_processor(images=images, return_tensors=\\\"pt\\\", **image_processor_kwargs)\\n            image_num_patches = image_inputs.pop(\\\"num_patches\\\")\\n            image_pixel_values = image_inputs.pop(\\\"pixel_values\\\")\\n            image_num_patches_indices = np.cumsum(image_num_patches)\\n\\n        if len(videos) != 0:\\n            videos = make_batched_videos(videos)\\n            num_frames_per_video = [len(video) for video in videos]\\n            patch_indices = np.cumsum(num_frames_per_video)\\n            image_processor_kwargs[\\\"crop_to_patches\\\"] = False\\n            video_inputs = image_processor(images=videos, return_tensors=\\\"pt\\\", **image_processor_kwargs)\\n            video_num_patches = video_inputs.pop(\\\"num_patches\\\")\\n            video_pixel_values = video_inputs.pop(\\\"pixel_values\\\")\\n            video_num_patches_indices = np.cumsum(video_num_patches)\\n\\n        # NOT SUPPORT IMAGE VIDEO INTERLEAVED\\n        if len(images) != 0 and image_pixel_values is not None:\\n            for i in range(len(images)):\\n                start_index = image_num_patches_indices[i - 1] if i > 0 else 0\\n                end_index = image_num_patches_indices[i]\\n                image_video_patches.append(image_pixel_values[start_index:end_index])\\n\\n        if len(videos) != 0 and video_pixel_values is not None:\\n            patch_indices_with_prefix = [0] + list(patch_indices)\\n            for i in range(len(videos)):\\n                current_patch_index = patch_indices_with_prefix[i]\\n                end_patch_index = patch_indices_with_prefix[i + 1]\\n                start_index = video_num_patches_indices[current_patch_index - 1] if i > 0 else 0\\n                end_index = video_num_patches_indices[end_patch_index - 1]\\n                image_video_patches.append(video_pixel_values[start_index:end_index])\\n\\n        if len(images) != 0 or len(videos) != 0:\\n            mm_inputs[\\\"pixel_values\\\"] = torch.cat(image_video_patches, dim=0)\\n\\n        if len(images) != 0:\\n            mm_inputs.update({\\\"image_num_patches\\\": image_num_patches})\\n\\n        if len(videos) != 0:\\n            mm_inputs.update({\\\"video_patch_indices\\\": patch_indices})\\n            mm_inputs.update({\\\"video_num_patches\\\": video_num_patches})\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens = 0, 0\\n        image_seqlen = getattr(processor, \\\"image_seq_length\\\") if self.expand_mm_tokens else 1\\n        messages = deepcopy(messages)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n\\n        image_pixel_patch_list = mm_inputs.get(\\\"image_num_patches\\\")  # patches of images\\n        video_num_patches = mm_inputs.get(\\\"video_num_patches\\\")  # all patches for frames of videos\\n        video_patch_indices = mm_inputs.get(\\\"video_patch_indices\\\")  # num frames of per video\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"<img>{'<IMG_CONTEXT>' * image_seqlen * image_pixel_patch_list[num_image_tokens]}</img>\\\",\\n                    1,\\n                )\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                current_patch_index = video_patch_indices[num_video_tokens - 1] if num_video_tokens > 0 else 0\\n                end_patch_index = video_patch_indices[num_video_tokens]\\n                num_patches = list(video_num_patches[current_patch_index:end_patch_index])\\n                video_replaced_prompt = \\\"\\\\n\\\".join(\\n                    f\\\"Frame{i + 1}: <img>{'<IMG_CONTEXT>' * image_seqlen * num_patches[i]}</img>\\\"\\n                    for i in range(len(num_patches))\\n                )\\n                content = content.replace(VIDEO_PLACEHOLDER, video_replaced_prompt, 1)\\n                num_video_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        mm_inputs.pop(\\\"image_num_patches\\\", None)\\n        mm_inputs.pop(\\\"video_patch_indices\\\", None)\\n        mm_inputs.pop(\\\"video_num_patches\\\", None)\\n        return mm_inputs\\n\\n\\nclass KimiVLPlugin(BasePlugin):\\n    @override\\n    def process_messages(self, messages, images, videos, audios, processor):\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            image_grid_hws = mm_inputs.get(\\\"image_grid_hws\\\", [])\\n        else:\\n            image_grid_hws = [None] * len(images)\\n\\n        num_image_tokens = 0\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        merge_length = math.prod(image_processor.merge_kernel_size)\\n        messages = deepcopy(messages)\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = image_grid_hws[num_image_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"<|media_start|>image<|media_content|>{self.image_token * image_seqlen}<|media_end|>\\\",\\n                    1,\\n                )\\n                num_image_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\n@dataclass\\nclass Llama4Plugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values\\\" in mm_inputs:\\n                image_height, image_width = mm_inputs[\\\"pixel_values\\\"][0].shape[-2:]\\n                num_patches_per_chunk = int(\\n                    (image_height // processor.patch_size)\\n                    * (image_width // processor.patch_size)\\n                    // processor.downsample_ratio\\n                )\\n                aspect_ratios = mm_inputs.pop(\\\"aspect_ratios\\\")\\n\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            if self.expand_mm_tokens:\\n                placeholder_count = content.count(IMAGE_PLACEHOLDER)\\n                prompt_splits = content.split(IMAGE_PLACEHOLDER)\\n                new_content = []\\n                for local_image_index, split_part in enumerate(prompt_splits):\\n                    new_content.append(split_part)\\n                    if local_image_index < placeholder_count:\\n                        tokens_for_this_image = processor._prompt_split_image(\\n                            aspect_ratios[num_image_tokens], num_patches_per_chunk\\n                        )\\n                        num_image_tokens += 1\\n                        new_content.append(tokens_for_this_image)\\n\\n                content = \\\"\\\".join(new_content)\\n            else:\\n                content = content.replace(IMAGE_PLACEHOLDER, self.image_token)\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        mm_inputs.pop(\\\"aspect_ratios\\\", None)\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass LlavaPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values\\\" in mm_inputs:\\n                height, width = get_image_size(to_numpy_array(mm_inputs[\\\"pixel_values\\\"][0]))\\n                image_seqlen = (height // processor.patch_size) * (\\n                    width // processor.patch_size\\n                ) + processor.num_additional_image_tokens\\n                if processor.vision_feature_select_strategy == \\\"default\\\":\\n                    image_seqlen -= 1\\n        else:\\n            image_seqlen = 1\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\" * image_seqlen, 1)\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", self.image_token)\\n\\n        return messages\\n\\n\\n@dataclass\\nclass LlavaNextPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values\\\" in mm_inputs:\\n                image_sizes = iter(mm_inputs[\\\"image_sizes\\\"].tolist())\\n                height, width = get_image_size(to_numpy_array(mm_inputs[\\\"pixel_values\\\"][0][0]))\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                if self.expand_mm_tokens:\\n                    orig_height, orig_width = next(image_sizes)\\n                    image_seqlen = processor._get_number_of_features(orig_height, orig_width, height, width)\\n                    if processor.vision_feature_select_strategy == \\\"default\\\":\\n                        image_seqlen -= 1\\n                else:\\n                    image_seqlen = 1\\n\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\" * image_seqlen, 1)\\n                num_image_tokens += 1\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", self.image_token)\\n\\n        return messages\\n\\n\\n@dataclass\\nclass LlavaNextVideoPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values\\\" in mm_inputs:\\n                image_sizes = iter(mm_inputs[\\\"image_sizes\\\"].tolist())\\n                height, width = get_image_size(to_numpy_array(mm_inputs[\\\"pixel_values\\\"][0][0]))\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                if self.expand_mm_tokens:\\n                    orig_height, orig_width = next(image_sizes)\\n                    image_seqlen = processor._get_number_of_features(orig_height, orig_width, height, width)\\n                    if processor.vision_feature_select_strategy == \\\"default\\\":\\n                        image_seqlen -= 1\\n                else:\\n                    image_seqlen = 1\\n\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\" * image_seqlen, 1)\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", self.image_token)\\n\\n        if self.expand_mm_tokens:\\n            if \\\"pixel_values_videos\\\" in mm_inputs:\\n                one_video = to_numpy_array(mm_inputs.get(\\\"pixel_values_videos\\\")[0])\\n                height, width = get_image_size(one_video[0])\\n                num_frames = one_video.shape[0]  # frame dim is always after batch dim\\n                image_seqlen = (height // processor.patch_size) * (width // processor.patch_size)\\n                video_seqlen = image_seqlen // 4 * num_frames  # divide by 4 needed for avg pooling layer\\n        else:\\n            video_seqlen = 1\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while VIDEO_PLACEHOLDER in content:\\n                content = content.replace(VIDEO_PLACEHOLDER, \\\"{{video}}\\\" * video_seqlen, 1)\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{video}}\\\", self.video_token)\\n\\n        return messages\\n\\n\\n@dataclass\\nclass MiniCPMVPlugin(BasePlugin):\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n        **kwargs,\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            if \\\"valid_image_nums_ls\\\" in kwargs:\\n                valid_image_nums_ls = kwargs[\\\"valid_image_nums_ls\\\"]\\n                new_images = []\\n                idx = 0\\n                for valid_image_nums in valid_image_nums_ls:\\n                    new_images.append(images[idx : idx + valid_image_nums])\\n                    idx += valid_image_nums\\n\\n                images = new_images\\n\\n            image_inputs = image_processor(\\n                images, do_pad=True, max_slice_nums=image_processor.max_slice_nums, return_tensors=\\\"pt\\\"\\n            )\\n            mm_inputs.update(image_inputs)\\n\\n        if len(videos) != 0:\\n            videos = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )[\\\"videos\\\"]\\n            video_inputs = image_processor(videos, do_pad=True, max_slice_nums=2, return_tensors=\\\"pt\\\")\\n            mm_inputs.update(video_inputs)\\n\\n        if len(audios) != 0:\\n            audios = self._regularize_audios(\\n                audios,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )[\\\"audios\\\"]\\n            if \\\"valid_audio_nums_ls\\\" in kwargs:\\n                valid_audio_nums_ls = kwargs[\\\"valid_audio_nums_ls\\\"]\\n                audios_ls = []\\n                idx = 0\\n                for valid_audio_nums in valid_audio_nums_ls:\\n                    audios_ls.append(audios[idx : idx + valid_audio_nums])\\n                    idx += valid_audio_nums\\n            else:\\n                audios_ls = [audios]\\n\\n            audio_features, audio_feature_lens, audio_phs = processor.audio_feature_extract(\\n                audios_ls,\\n                chunk_input=True,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )\\n            audio_feature_lens = [\\n                x.clone().detach() if isinstance(x, torch.Tensor) else torch.tensor(x) for x in audio_feature_lens\\n            ]\\n            mm_inputs.update({\\\"audio_features\\\": audio_features, \\\"audio_feature_lens\\\": audio_feature_lens})\\n            if kwargs.get(\\\"ret_phs\\\", False):\\n                mm_inputs.update({\\\"audio_phs\\\": audio_phs})\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens, num_audio_tokens = 0, 0, 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        mm_inputs, audio_inputs = {}, {}\\n        if len(images) != 0 and len(videos) != 0:\\n            raise ValueError(\\\"MiniCPM-V model does not support input images and videos at the same time.\\\")\\n\\n        if len(videos) != 0:\\n            max_slice_nums = 2\\n            use_image_id = False\\n            mm_inputs = self._get_mm_inputs([], videos, [], processor)\\n        else:\\n            max_slice_nums = image_processor.max_slice_nums\\n            use_image_id = image_processor.use_image_id\\n\\n        for i, message in enumerate(messages):\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\", 1)\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                video_seqlen = len(mm_inputs[\\\"image_sizes\\\"][num_video_tokens]) if self.expand_mm_tokens else 1\\n                content = content.replace(VIDEO_PLACEHOLDER, \\\"{{image}}\\\" * video_seqlen, 1)\\n                num_video_tokens += 1\\n\\n            while AUDIO_PLACEHOLDER in content:\\n                content = content.replace(AUDIO_PLACEHOLDER, \\\"{{audio}}\\\", 1)\\n                num_audio_tokens += 1\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", \\\"(<image>./</image>)\\\").replace(\\n                \\\"{{audio}}\\\", \\\"(<audio>./</audio>)\\\"\\n            )\\n\\n        if len(images):\\n            mm_inputs = self._get_mm_inputs(images, [], [], processor)\\n\\n        if len(audios):\\n            audio_inputs = self._get_mm_inputs([], [], audios, processor, ret_phs=True)\\n\\n        if self.expand_mm_tokens and mm_inputs:\\n            pattern = \\\"(<image>./</image>)\\\"\\n            image_sizes = mm_inputs[\\\"image_sizes\\\"]\\n            idx = 0\\n            for index, message in enumerate(messages):\\n                text = message[\\\"content\\\"]\\n                image_tags = re.findall(pattern, text)\\n                text_chunks = text.split(pattern)\\n                final_text = \\\"\\\"\\n                for i in range(len(image_tags)):\\n                    final_text = (\\n                        final_text\\n                        + text_chunks[i]\\n                        + image_processor.get_slice_image_placeholder(\\n                            image_sizes[0][idx], idx, max_slice_nums, use_image_id\\n                        )\\n                    )\\n                    idx += 1\\n\\n                final_text += text_chunks[-1]\\n                messages[index][\\\"content\\\"] = final_text\\n\\n        if self.expand_mm_tokens and audio_inputs:\\n            pattern = \\\"(<audio>./</audio>)\\\"\\n            idx = 0\\n            for index, message in enumerate(messages):\\n                text = message[\\\"content\\\"]\\n                audio_tags = re.findall(pattern, text)\\n                text_chunks = text.split(pattern)\\n                final_text = \\\"\\\"\\n                for i in range(len(audio_tags)):\\n                    audio_placeholder = audio_inputs[\\\"audio_phs\\\"][0][idx]\\n                    final_text = final_text + text_chunks[i] + audio_placeholder\\n                    idx += 1\\n\\n                final_text += text_chunks[-1]\\n                messages[index][\\\"content\\\"] = final_text\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        # image bound\\n        image_bounds_list = []\\n        valid_image_nums_ls = []\\n        for i, input_ids in enumerate(batch_ids):\\n            input_ids_ = torch.tensor(input_ids)\\n            start_cond = (input_ids_ == processor.tokenizer.im_start_id) | (\\n                input_ids_ == processor.tokenizer.slice_start_id\\n            )\\n            end_cond = (input_ids_ == processor.tokenizer.im_end_id) | (input_ids_ == processor.tokenizer.slice_end_id)\\n            image_start_tokens = torch.where(start_cond)[0]\\n            image_start_tokens += 1\\n            image_end_tokens = torch.where(end_cond)[0]\\n            valid_image_nums_ls.append(imglens[i])\\n            image_bounds = torch.hstack(\\n                [\\n                    image_start_tokens.unsqueeze(-1),\\n                    image_end_tokens.unsqueeze(-1),\\n                ]\\n            )\\n            image_bounds_list.append(image_bounds)\\n\\n        mm_inputs = self._get_mm_inputs(images, videos, [], processor, valid_image_nums_ls=valid_image_nums_ls)\\n        if \\\"tgt_sizes\\\" not in mm_inputs:\\n            dummy_data = [torch.empty(0) for _ in range(len(batch_ids))]\\n            mm_inputs.update({\\\"tgt_sizes\\\": dummy_data, \\\"pixel_values\\\": dummy_data, \\\"image_sizes\\\": dummy_data})\\n\\n        mm_inputs.update({\\\"image_bound\\\": image_bounds_list})\\n\\n        if len(audios) > 0:\\n            # audio bound\\n            audio_bounds_ls = []\\n            spk_bounds_ls = []\\n            valid_audio_nums_ls = []\\n\\n            for input_ids, audiolen in zip(batch_ids, audlens):\\n                input_ids_ = torch.tensor(input_ids)\\n                audio_start_idx = torch.where(input_ids_ == processor.tokenizer.audio_start_id)[0]\\n                audio_end_idx = torch.where(input_ids_ == processor.tokenizer.audio_end_id)[0]\\n                assert len(audio_start_idx) == len(audio_end_idx)\\n                audio_bounds = torch.hstack([(audio_start_idx + 1).unsqueeze(-1), audio_end_idx.unsqueeze(-1)])\\n                audio_bounds_ls.append(audio_bounds)\\n                valid_audio_nums_ls.append(audiolen)\\n\\n                spk_start_idx = torch.where(input_ids_ == processor.tokenizer.spk_start_id)[0]\\n                spk_end_idx = torch.where(input_ids_ == processor.tokenizer.spk_end_id)[0]\\n                assert len(spk_start_idx) == len(spk_end_idx)\\n                spk_bounds = torch.hstack([(spk_start_idx + 1).unsqueeze(-1), spk_end_idx.unsqueeze(-1)])\\n                spk_bounds_ls.append(spk_bounds)\\n\\n            audio_inputs = self._get_mm_inputs([], [], audios, processor, valid_audio_nums_ls=valid_audio_nums_ls)\\n            mm_inputs.update(audio_inputs)\\n            mm_inputs.update({\\\"audio_bounds\\\": audio_bounds_ls, \\\"spk_bounds\\\": spk_bounds_ls})\\n\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass MiniCPMV4_6Plugin(BasePlugin):\\n    \\\"\\\"\\\"Plugin for MiniCPM-V-4.6 with new transformers (NaViT vision + get_placeholder_mask API).\\\"\\\"\\\"\\n\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n        **kwargs,\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor = getattr(processor, \\\"image_processor\\\")\\n        video_processor = getattr(processor, \\\"video_processor\\\", None)\\n        mm_inputs = {}\\n\\n        if len(images) != 0:\\n            # The image_processor ignores downsample_mode; target_sizes are always based on patch_size.\\n            # downsample_mode only affects the token divisor in _build_v4_6_placeholder and model forward.\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            if video_processor is not None:\\n                video_inputs = video_processor(videos, return_tensors=\\\"pt\\\")\\n                mm_inputs[\\\"pixel_values_videos\\\"] = video_inputs[\\\"pixel_values_videos\\\"]\\n                mm_inputs[\\\"target_sizes_videos\\\"] = video_inputs[\\\"target_sizes_videos\\\"]\\n            else:\\n                video_inputs = image_processor(videos, return_tensors=\\\"pt\\\")\\n                mm_inputs[\\\"pixel_values_videos\\\"] = video_inputs[\\\"pixel_values\\\"]\\n                mm_inputs[\\\"target_sizes_videos\\\"] = video_inputs[\\\"target_sizes\\\"]\\n\\n        if len(audios) != 0:\\n            audio_features, audio_feature_lens, audio_phs = processor.audio_feature_extract(\\n                [audios],\\n                chunk_input=True,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )\\n            audio_feature_lens = [\\n                x.clone().detach() if isinstance(x, torch.Tensor) else torch.tensor(x) for x in audio_feature_lens\\n            ]\\n            mm_inputs.update({\\\"audio_features\\\": audio_features, \\\"audio_feature_lens\\\": audio_feature_lens})\\n            if kwargs.get(\\\"ret_phs\\\", False):\\n                mm_inputs.update({\\\"audio_phs\\\": audio_phs})\\n\\n        return mm_inputs\\n\\n    def _build_v4_6_placeholder(\\n        self,\\n        image_inputs: dict[str, Any],\\n        image_idx: int,\\n        use_image_id: bool,\\n        processor: \\\"MMProcessor\\\",\\n    ) -> str:\\n        \\\"\\\"\\\"Build image placeholder for MiniCPM-V-4.6 using NaViT token count computation.\\\"\\\"\\\"\\n        grids = image_inputs.get(\\\"grids\\\", [[0, 0]])\\n        num_patches_per_image = image_inputs.get(\\\"num_patches_per_image\\\", [1])\\n        target_sizes = image_inputs.get(\\\"target_sizes\\\")\\n\\n        downsample_mode = os.getenv(\\\"DOWNSAMPLE_MODE\\\")\\n        if downsample_mode is None:\\n            image_processor = getattr(processor, \\\"image_processor\\\")\\n            downsample_mode = getattr(image_processor, \\\"downsample_mode\\\", \\\"16x\\\")\\n        token_divisor = 4 if downsample_mode == \\\"4x\\\" else 16\\n\\n        flat_index = 0\\n        for idx in range(image_idx):\\n            flat_index += num_patches_per_image[idx]\\n        n_patches = num_patches_per_image[image_idx]\\n\\n        img_target_sizes = target_sizes[flat_index : flat_index + n_patches]\\n        num_tokens_per_patch = img_target_sizes.prod(-1) // token_divisor\\n        num_rows, num_cols = grids[image_idx]\\n\\n        image_start = getattr(processor, \\\"image_start_token\\\", \\\"<image>\\\")\\n        image_end = getattr(processor, \\\"image_end_token\\\", \\\"</image>\\\")\\n        slice_start = getattr(processor, \\\"slice_start_token\\\", \\\"<slice>\\\")\\n        slice_end = getattr(processor, \\\"slice_end_token\\\", \\\"</slice>\\\")\\n        image_id_start = getattr(processor, \\\"image_id_start_token\\\", \\\"<image_id>\\\")\\n        image_id_end = getattr(processor, \\\"image_id_end_token\\\", \\\"</image_id>\\\")\\n        image_token = (\\n            getattr(processor, \\\"image_token\\\", None)\\n            or getattr(getattr(processor, \\\"tokenizer\\\", None), \\\"image_token\\\", None)\\n            or \\\"<image>\\\"\\n        )\\n\\n        image_placeholder = image_start + \\\"<|ph|>\\\" * int(num_tokens_per_patch[0]) + image_end\\n        if use_image_id:\\n            image_placeholder = f\\\"{image_id_start}{image_idx}{image_id_end}\\\" + image_placeholder\\n\\n        slice_mode = getattr(processor, \\\"slice_mode\\\", True)\\n        if slice_mode and num_rows > 0 and num_cols > 0:\\n            per_slice_tokens = int(num_tokens_per_patch[1]) if len(num_tokens_per_patch) > 1 else 0\\n            slice_placeholder = slice_start + \\\"<|ph|>\\\" * per_slice_tokens + slice_end\\n            slices = [slice_placeholder * num_cols for _ in range(num_rows)]\\n            image_placeholder += \\\"\\\\n\\\".join(slices)\\n\\n        return image_placeholder.replace(\\\"<|ph|>\\\", image_token)\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens, num_audio_tokens = 0, 0, 0\\n        messages = deepcopy(messages)\\n        mm_inputs, audio_inputs = {}, {}\\n        if len(images) != 0 and len(videos) != 0:\\n            raise ValueError(\\\"MiniCPM-V model does not support input images and videos at the same time.\\\")\\n\\n        use_image_id = getattr(processor, \\\"default_use_image_id\\\", True)\\n\\n        if len(videos) != 0:\\n            use_image_id = False\\n            mm_inputs = self._get_mm_inputs([], videos, [], processor)\\n\\n        for i, message in enumerate(messages):\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\", 1)\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                num_frames = 1\\n                if \\\"num_frames_per_video\\\" in mm_inputs:\\n                    num_frames = sum(mm_inputs[\\\"num_frames_per_video\\\"])\\n                content = content.replace(VIDEO_PLACEHOLDER, \\\"{{image}}\\\" * num_frames, 1)\\n                num_video_tokens += 1\\n\\n            while AUDIO_PLACEHOLDER in content:\\n                content = content.replace(AUDIO_PLACEHOLDER, \\\"{{audio}}\\\", 1)\\n                num_audio_tokens += 1\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", \\\"(<image>./</image>)\\\").replace(\\n                \\\"{{audio}}\\\", \\\"(<audio>./</audio>)\\\"\\n            )\\n\\n        if len(images):\\n            mm_inputs = self._get_mm_inputs(images, [], [], processor)\\n\\n        if len(audios):\\n            audio_inputs = self._get_mm_inputs([], [], audios, processor, ret_phs=True)\\n\\n        if self.expand_mm_tokens and mm_inputs:\\n            pattern = \\\"(<image>./</image>)\\\"\\n            idx = 0\\n            for index, message in enumerate(messages):\\n                text = message[\\\"content\\\"]\\n                image_tags = re.findall(pattern, text)\\n                text_chunks = text.split(pattern)\\n                final_text = \\\"\\\"\\n                for i in range(len(image_tags)):\\n                    image_placeholder = self._build_v4_6_placeholder(mm_inputs, idx, use_image_id, processor)\\n                    final_text = final_text + text_chunks[i] + image_placeholder\\n                    idx += 1\\n                final_text += text_chunks[-1]\\n                messages[index][\\\"content\\\"] = final_text\\n\\n        if self.expand_mm_tokens and audio_inputs:\\n            pattern = \\\"(<audio>./</audio>)\\\"\\n            idx = 0\\n            for index, message in enumerate(messages):\\n                text = message[\\\"content\\\"]\\n                audio_tags = re.findall(pattern, text)\\n                text_chunks = text.split(pattern)\\n                final_text = \\\"\\\"\\n                for i in range(len(audio_tags)):\\n                    audio_placeholder = audio_inputs[\\\"audio_phs\\\"][0][idx]\\n                    final_text = final_text + text_chunks[i] + audio_placeholder\\n                    idx += 1\\n                final_text += text_chunks[-1]\\n                messages[index][\\\"content\\\"] = final_text\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n\\n        # v4.6 does NOT use image_bound \u2014 the model finds image tokens via get_placeholder_mask\\n        # Ensure target_sizes key name matches the model's expected input\\n        if \\\"target_sizes\\\" not in mm_inputs and \\\"tgt_sizes\\\" in mm_inputs:\\n            mm_inputs[\\\"target_sizes\\\"] = mm_inputs.pop(\\\"tgt_sizes\\\")\\n\\n        if \\\"target_sizes\\\" not in mm_inputs:\\n            mm_inputs[\\\"target_sizes\\\"] = torch.empty(0, 2, dtype=torch.int32)\\n\\n        if \\\"pixel_values\\\" not in mm_inputs:\\n            mm_inputs[\\\"pixel_values\\\"] = torch.empty(1, 3, 14, 0)\\n\\n        # Pass downsample_mode to model forward so it matches the placeholder divisor\\n        _ds = os.getenv(\\\"DOWNSAMPLE_MODE\\\")\\n        if _ds is None:\\n            _ds = getattr(getattr(processor, \\\"image_processor\\\", None), \\\"downsample_mode\\\", \\\"16x\\\")\\n        mm_inputs[\\\"downsample_mode\\\"] = _ds\\n\\n        if len(audios) > 0:\\n            audio_inputs = self._get_mm_inputs([], [], audios, processor)\\n            mm_inputs.update(audio_inputs)\\n\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass MllamaPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            num_image_tokens += content.count(IMAGE_PLACEHOLDER)\\n            message[\\\"content\\\"] = content.replace(IMAGE_PLACEHOLDER, self.image_token)\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor, imglens)\\n        if mm_inputs:\\n            num_tiles = mm_inputs.pop(\\\"num_tiles\\\")\\n            image_token_id: int = getattr(processor, \\\"image_token_id\\\")\\n            max_image_tiles: int = getattr(processor.image_processor, \\\"max_image_tiles\\\")\\n            cross_attention_token_mask = [\\n                get_cross_attention_token_mask(input_ids, image_token_id) for input_ids in batch_ids\\n            ]\\n            mm_inputs[\\\"cross_attention_mask\\\"] = torch.from_numpy(\\n                convert_sparse_cross_attention_mask_to_dense(\\n                    cross_attention_token_mask,\\n                    num_tiles=num_tiles,\\n                    max_num_tiles=max_image_tiles,\\n                    length=max(len(input_ids) for input_ids in batch_ids),\\n                )\\n            )  # shape: (batch_size, length, max_num_images, max_num_tiles)\\n\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass PaliGemmaPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"\\\", 1)\\n                num_image_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def process_token_ids(\\n        self,\\n        input_ids: list[int],\\n        labels: list[int] | None,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> tuple[list[int], list[int] | None]:\\n        self._validate_input(processor, images, videos, audios)\\n        num_images = len(images)\\n        image_seqlen = processor.image_seq_length if self.expand_mm_tokens else 0  # skip mm token\\n        image_token_id = tokenizer.convert_tokens_to_ids(self.image_token)\\n        input_ids = [image_token_id] * num_images * image_seqlen + input_ids\\n        if labels is not None:\\n            labels = [IGNORE_INDEX] * num_images * image_seqlen + labels\\n\\n        return input_ids, labels\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        seqlens = [len(input_ids) for input_ids in batch_ids]\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        mm_inputs[\\\"token_type_ids\\\"] = _get_paligemma_token_type_ids(imglens, seqlens, processor)\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass PixtralPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values\\\" in mm_inputs:\\n                # BC for transformers < 4.49.0\\n                if isinstance(mm_inputs[\\\"image_sizes\\\"], list):\\n                    image_sizes = iter(mm_inputs[\\\"image_sizes\\\"][0])\\n                else:\\n                    image_sizes = iter(mm_inputs[\\\"image_sizes\\\"].tolist())\\n\\n                image_break_token: str = getattr(processor, \\\"image_break_token\\\")\\n                image_end_token: str = getattr(processor, \\\"image_end_token\\\")\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                if self.expand_mm_tokens:\\n                    patch_size = processor.patch_size * getattr(processor, \\\"spatial_merge_size\\\", 1)\\n                    height, width = next(image_sizes)\\n                    num_height_tokens = height // patch_size\\n                    num_width_tokens = width // patch_size\\n                    replace_tokens = [[self.image_token] * num_width_tokens + [image_break_token]] * num_height_tokens\\n                    replace_tokens = [item for sublist in replace_tokens for item in sublist]  # flatten list\\n                    replace_tokens[-1] = image_end_token\\n                    replace_str = \\\"\\\".join(replace_tokens)\\n                else:\\n                    replace_str = self.image_token\\n\\n                content = content.replace(IMAGE_PLACEHOLDER, replace_str, 1)\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        # ref to this commit https://github.com/huggingface/transformers/pull/35122\\n        # after transformers 4.49.0, the `image_sizes` is mandatory as an input parameter for Pixtral VisionEncoder forwarding.\\n        # it can be passed into `LlavaConditionalGeneration` as a parameter.\\n        if not is_transformers_version_greater_than(\\\"4.49.0\\\"):\\n            mm_inputs.pop(\\\"image_sizes\\\", None)\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass Qwen2AudioPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        bos_token: str = getattr(processor, \\\"audio_bos_token\\\")\\n        eos_token: str = getattr(processor, \\\"audio_eos_token\\\")\\n        messages = deepcopy(messages)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs([], [], audios, processor)\\n            if \\\"feature_attention_mask\\\" in mm_inputs:\\n                audio_lengths = mm_inputs[\\\"feature_attention_mask\\\"].sum(-1).tolist()\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while AUDIO_PLACEHOLDER in content:\\n                if self.expand_mm_tokens:\\n                    audio_length = audio_lengths.pop(0)\\n                    input_length = (audio_length - 1) // 2 + 1\\n                    audio_seqlen = (input_length - 2) // 2 + 1\\n                else:\\n                    audio_seqlen = 1\\n\\n                content = content.replace(\\n                    AUDIO_PLACEHOLDER, f\\\"{bos_token}{self.audio_token * audio_seqlen}{eos_token}\\\", 1\\n                )\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        return self._get_mm_inputs(images, videos, audios, processor)\\n\\n\\n@dataclass\\nclass Qwen2VLPlugin(BasePlugin):\\n    vision_bos_token: str = \\\"<|vision_start|>\\\"\\n    vision_eos_token: str = \\\"<|vision_end|>\\\"\\n\\n    @override\\n    def _preprocess_image(self, image: \\\"ImageObject\\\", **kwargs) -> \\\"ImageObject\\\":\\n        image = super()._preprocess_image(image, **kwargs)\\n        if min(image.width, image.height) < 28:\\n            width, height = max(image.width, 28), max(image.height, 28)\\n            image = image.resize((width, height))\\n\\n        if image.width / image.height > 200:\\n            width, height = image.height * 180, image.height\\n            image = image.resize((width, height))\\n\\n        if image.height / image.width > 200:\\n            width, height = image.width, image.width * 180\\n            image = image.resize((width, height))\\n\\n        return image\\n\\n    @override\\n    def _regularize_videos(self, videos: list[\\\"VideoInput\\\"], **kwargs) -> \\\"RegularizedVideoOutput\\\":\\n        results, fps_per_video, durations, frames_indices = [], [], [], []\\n        for video in videos:\\n            frames: list[ImageObject] = []\\n            if _check_video_is_nested_images(video):\\n                # we assume already sample frames from videos\\n                for frame in video:\\n                    if not is_valid_image(frame) and not isinstance(frame, dict) and not os.path.exists(frame):\\n                        raise ValueError(\\\"Invalid image found in video frames.\\\")\\n\\n                frames = video\\n                fps_per_video.append(kwargs.get(\\\"video_fps\\\", 2.0))\\n                durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n                frames_indices.append(list(range(len(frames))))\\n            else:\\n                container = av.open(video, \\\"r\\\")\\n                video_stream = next(stream for stream in container.streams if stream.type == \\\"video\\\")\\n                sample_indices = self._get_video_sample_indices(video_stream, **kwargs)\\n                original_fps = float(video_stream.average_rate)\\n                # for qwen3vl video timestamp calculation\\n                frames_indices.append(\\n                    [idx / original_fps * kwargs.get(\\\"video_fps\\\", 2.0) for idx in sample_indices]\\n                )  # hack usage when do_sample_frames=False\\n                container.seek(0)\\n                for frame_idx, frame in enumerate(container.decode(video_stream)):\\n                    if frame_idx in sample_indices:\\n                        frames.append(frame.to_image())\\n\\n                if video_stream.duration is None:\\n                    fps_per_video.append(kwargs.get(\\\"video_fps\\\", 2.0))\\n                    durations.append(len(frames) / kwargs.get(\\\"video_fps\\\", 2.0))\\n                else:\\n                    fps_per_video.append(len(sample_indices) / float(video_stream.duration * video_stream.time_base))\\n                    durations.append(float(video_stream.duration * video_stream.time_base))\\n\\n            if len(frames) % 2 != 0:\\n                frames.append(frames[-1])\\n\\n            frames = self._regularize_images(frames, **kwargs)[\\\"images\\\"]\\n            results.append(frames)\\n\\n        return {\\n            \\\"videos\\\": results,\\n            \\\"fps_per_video\\\": fps_per_video,\\n            \\\"durations\\\": durations,\\n            \\\"frames_indices\\\": frames_indices,\\n        }\\n\\n    def _get_qwen_video_size_after_regularization(\\n        self, width: int, height: int, image_max_pixels: int, image_min_pixels: int\\n    ) -> tuple[int, int]:\\n        r\\\"\\\"\\\"Compute the frame size produced by Qwen-VL image regularization.\\\"\\\"\\\"\\n        if (width * height) > image_max_pixels:\\n            resize_factor = math.sqrt(image_max_pixels / (width * height))\\n            width, height = int(width * resize_factor), int(height * resize_factor)\\n\\n        if (width * height) < image_min_pixels:\\n            resize_factor = math.sqrt(image_min_pixels / (width * height))\\n            width, height = int(width * resize_factor), int(height * resize_factor)\\n\\n        if min(width, height) < 28:\\n            width, height = max(width, 28), max(height, 28)\\n\\n        if width / height > 200:\\n            width, height = height * 180, height\\n\\n        if height / width > 200:\\n            width, height = width, width * 180\\n\\n        return width, height\\n\\n    def _get_qwen_video_stream_metadata(\\n        self,\\n        video: \\\"VideoInput\\\",\\n        video_fps: float,\\n        video_maxlen: int,\\n    ) -> Optional[dict[str, Any]]:\\n        if not is_pyav_available() or not isinstance(video, (str, os.PathLike)):\\n            return None\\n\\n        try:\\n            container = av.open(video, \\\"r\\\")\\n        except (av.FFmpegError, OSError):\\n            return None\\n\\n        try:\\n            video_stream = next((stream for stream in container.streams if stream.type == \\\"video\\\"), None)\\n            if video_stream is None:\\n                return None\\n\\n            if video_stream.duration is None or video_stream.average_rate is None:\\n                return None\\n\\n            average_fps = float(video_stream.average_rate)\\n            if average_fps <= 0:\\n                return None\\n\\n            sample_indices = self._get_video_sample_indices(\\n                video_stream, video_fps=video_fps, video_maxlen=video_maxlen\\n            )\\n            return {\\n                \\\"width\\\": video_stream.width,\\n                \\\"height\\\": video_stream.height,\\n                \\\"average_fps\\\": average_fps,\\n                \\\"sample_indices\\\": sample_indices,\\n            }\\n        finally:\\n            container.close()\\n\\n    def _get_qwen_video_resize(\\n        self,\\n        num_frames: int,\\n        height: int,\\n        width: int,\\n        patch_size: int,\\n        temporal_patch_size: int,\\n        merge_size: int,\\n        min_pixels: int,\\n        max_pixels: int,\\n    ) -> tuple[int, int]:\\n        from transformers.models.qwen2_vl.image_processing_qwen2_vl import smart_resize\\n\\n        return smart_resize(\\n            height=height,\\n            width=width,\\n            factor=patch_size * merge_size,\\n            min_pixels=min_pixels,\\n            max_pixels=max_pixels,\\n        )\\n\\n    def _get_qwen_video_grid_metadata(\\n        self,\\n        videos: list[\\\"VideoInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> Optional[dict[str, Any]]:\\n        if len(videos) == 0:\\n            return {\\\"video_grid_thw\\\": torch.empty((0, 3), dtype=torch.long), \\\"frames_indices\\\": [], \\\"fps\\\": 2.0}\\n\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseVideoProcessor = getattr(processor, \\\"video_processor\\\", None) or image_processor\\n        if image_processor is None or video_processor is None:\\n            return None\\n\\n        patch_size = getattr(video_processor, \\\"patch_size\\\", None)\\n        temporal_patch_size = getattr(video_processor, \\\"temporal_patch_size\\\", None)\\n        merge_size = getattr(video_processor, \\\"merge_size\\\", None)\\n        size = getattr(video_processor, \\\"size\\\", None)\\n        if patch_size is None or temporal_patch_size is None or merge_size is None or size is None:\\n            return None\\n\\n        if isinstance(size, dict):\\n            min_pixels = size.get(\\\"shortest_edge\\\")\\n            max_pixels = size.get(\\\"longest_edge\\\")\\n        else:\\n            min_pixels = getattr(size, \\\"shortest_edge\\\", None)\\n            max_pixels = getattr(size, \\\"longest_edge\\\", None)\\n\\n        if min_pixels is None or max_pixels is None:\\n            return None\\n\\n        video_fps = getattr(processor, \\\"video_fps\\\", 2.0)\\n        video_maxlen = getattr(processor, \\\"video_maxlen\\\", 128)\\n        image_max_pixels = getattr(processor, \\\"video_max_pixels\\\", 256 * 256)\\n        image_min_pixels = getattr(processor, \\\"video_min_pixels\\\", 16 * 16)\\n\\n        video_grid_thw = []\\n        frames_indices = []\\n        for video in videos:\\n            metadata = self._get_qwen_video_stream_metadata(video, video_fps, video_maxlen)\\n            if metadata is None:\\n                return None\\n\\n            width, height = self._get_qwen_video_size_after_regularization(\\n                metadata[\\\"width\\\"], metadata[\\\"height\\\"], image_max_pixels, image_min_pixels\\n            )\\n            num_frames = len(metadata[\\\"sample_indices\\\"])\\n            if num_frames % 2 != 0:\\n                num_frames += 1\\n\\n            resized_size = self._get_qwen_video_resize(\\n                num_frames,\\n                height,\\n                width,\\n                patch_size,\\n                temporal_patch_size,\\n                merge_size,\\n                min_pixels,\\n                max_pixels,\\n            )\\n\\n            resized_height, resized_width = resized_size\\n            video_grid_thw.append(\\n                [\\n                    math.ceil(num_frames / temporal_patch_size),\\n                    resized_height // patch_size,\\n                    resized_width // patch_size,\\n                ]\\n            )\\n            frames_indices.append([idx / metadata[\\\"average_fps\\\"] * video_fps for idx in metadata[\\\"sample_indices\\\"]])\\n\\n        return {\\n            \\\"video_grid_thw\\\": torch.tensor(video_grid_thw, dtype=torch.long),\\n            \\\"frames_indices\\\": frames_indices,\\n            \\\"fps\\\": video_fps,\\n        }\\n\\n    @override\\n    def _get_video_token_metadata(\\n        self,\\n        videos: list[\\\"VideoInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> Optional[dict[str, Any]]:\\n        video_metadata = self._get_qwen_video_grid_metadata(videos, processor)\\n        if video_metadata is None:\\n            return None\\n\\n        return {\\\"video_grid_thw\\\": video_metadata[\\\"video_grid_thw\\\"]}\\n\\n    def _get_mm_token_metadata(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> Optional[dict[str, Any]]:\\n        if len(audios) != 0:\\n            return None\\n\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            mm_inputs.update(self._get_mm_inputs(images, [], [], processor))\\n\\n        if len(videos) != 0:\\n            video_inputs = self._get_video_token_metadata(videos, processor)\\n            if video_inputs is None:\\n                return None\\n\\n            mm_inputs.update(video_inputs)\\n\\n        return mm_inputs\\n\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseVideoProcessor = getattr(processor, \\\"video_processor\\\", None)\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            video_data = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )\\n            mm_inputs.update(video_processor(videos=video_data[\\\"videos\\\"], return_tensors=\\\"pt\\\"))\\n            temporal_patch_size: int = getattr(image_processor, \\\"temporal_patch_size\\\", 2)\\n            if \\\"second_per_grid_ts\\\" in processor.model_input_names:\\n                mm_inputs[\\\"second_per_grid_ts\\\"] = [temporal_patch_size / fps for fps in video_data[\\\"fps_per_video\\\"]]\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens = 0, 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n\\n        merge_length: int = getattr(image_processor, \\\"merge_size\\\") ** 2\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_token_metadata(images, videos, audios, processor)\\n            if mm_inputs is None:\\n                mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n\\n            image_grid_thw = mm_inputs.get(\\\"image_grid_thw\\\", [])\\n            video_grid_thw = mm_inputs.get(\\\"video_grid_thw\\\", [])\\n        else:\\n            image_grid_thw = [None] * len(images)\\n            video_grid_thw = [None] * len(videos)\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = image_grid_thw[num_image_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"{self.vision_bos_token}{self.image_token * image_seqlen}{self.vision_eos_token}\\\",\\n                    1,\\n                )\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                video_seqlen = video_grid_thw[num_video_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    VIDEO_PLACEHOLDER,\\n                    f\\\"{self.vision_bos_token}{self.video_token * video_seqlen}{self.vision_eos_token}\\\",\\n                    1,\\n                )\\n                num_video_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\n@dataclass\\nclass Qwen3VLPlugin(Qwen2VLPlugin):\\n    @override\\n    def _get_qwen_video_resize(\\n        self,\\n        num_frames: int,\\n        height: int,\\n        width: int,\\n        patch_size: int,\\n        temporal_patch_size: int,\\n        merge_size: int,\\n        min_pixels: int,\\n        max_pixels: int,\\n    ) -> tuple[int, int]:\\n        from transformers.models.qwen3_vl.video_processing_qwen3_vl import smart_resize\\n\\n        return smart_resize(\\n            num_frames=num_frames,\\n            height=height,\\n            width=width,\\n            temporal_factor=temporal_patch_size,\\n            factor=patch_size * merge_size,\\n            min_pixels=min_pixels,\\n            max_pixels=max_pixels,\\n        )\\n\\n    @override\\n    def _get_video_token_metadata(\\n        self,\\n        videos: list[\\\"VideoInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> Optional[dict[str, Any]]:\\n        video_metadata = self._get_qwen_video_grid_metadata(videos, processor)\\n        if video_metadata is None:\\n            return None\\n\\n        return {\\n            \\\"video_grid_thw\\\": video_metadata[\\\"video_grid_thw\\\"],\\n            \\\"video_metadata\\\": [\\n                SimpleNamespace(\\n                    frames_indices=frames_indices,\\n                    fps=video_metadata[\\\"fps\\\"],\\n                )\\n                for frames_indices in video_metadata[\\\"frames_indices\\\"]\\n            ],\\n        }\\n\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseImageProcessor = getattr(processor, \\\"video_processor\\\", None)\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            videos = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )\\n            video_metadata = [\\n                {\\n                    \\\"fps\\\": getattr(processor, \\\"video_fps\\\", 2.0),\\n                    \\\"duration\\\": duration,\\n                    \\\"total_num_frames\\\": len(video),\\n                    \\\"frames_indices\\\": sample_indices,\\n                }\\n                for video, duration, sample_indices in zip(\\n                    videos[\\\"videos\\\"], videos[\\\"durations\\\"], videos[\\\"frames_indices\\\"]\\n                )\\n            ]\\n            mm_inputs.update(\\n                video_processor(\\n                    videos=videos[\\\"videos\\\"],\\n                    video_metadata=video_metadata,\\n                    fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                    return_metadata=True,\\n                    do_sample_frames=False,  # avoid changing frames_indices\\n                )\\n            )\\n            temporal_patch_size: int = getattr(image_processor, \\\"temporal_patch_size\\\", 2)\\n            if \\\"second_per_grid_ts\\\" in processor.model_input_names:\\n                mm_inputs[\\\"second_per_grid_ts\\\"] = [temporal_patch_size / fps for fps in videos[\\\"fps_per_video\\\"]]\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens = 0, 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        video_processor: BaseImageProcessor = getattr(processor, \\\"video_processor\\\")\\n\\n        image_merge_length: int = getattr(image_processor, \\\"merge_size\\\") ** 2\\n        video_merge_length: int = getattr(video_processor, \\\"merge_size\\\") ** 2\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_token_metadata(images, videos, audios, processor)\\n            if mm_inputs is None:\\n                mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n\\n            image_grid_thw = mm_inputs.get(\\\"image_grid_thw\\\", [])\\n            video_grid_thw = mm_inputs.get(\\\"video_grid_thw\\\", [])\\n            video_metadata = mm_inputs.get(\\\"video_metadata\\\", [])\\n\\n        else:\\n            image_grid_thw = [None] * len(images)\\n            video_grid_thw = [None] * len(videos)\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = (\\n                    image_grid_thw[num_image_tokens].prod() // image_merge_length if self.expand_mm_tokens else 1\\n                )\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"{self.vision_bos_token}{self.image_token * image_seqlen}{self.vision_eos_token}\\\",\\n                    1,\\n                )\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                if self.expand_mm_tokens:\\n                    video_grid = video_grid_thw[num_video_tokens]\\n                    num_frames = int(video_grid[0].item())\\n                    metadata = video_metadata[num_video_tokens]\\n                    timestamps = processor._calculate_timestamps(\\n                        metadata.frames_indices,\\n                        metadata.fps,\\n                        getattr(video_processor, \\\"temporal_patch_size\\\", 2),\\n                    )\\n                    video_structure = \\\"\\\"\\n                    video_seqlen = int((video_grid[1:].prod() // video_merge_length).item())\\n                    for frame_index in range(num_frames):\\n                        timestamp_sec = timestamps[frame_index]\\n                        frame_structure = (\\n                            f\\\"<{timestamp_sec:.1f} seconds>\\\"\\n                            f\\\"{self.vision_bos_token}{self.video_token * video_seqlen}{self.vision_eos_token}\\\"\\n                        )\\n                        video_structure += frame_structure\\n                else:\\n                    video_structure = f\\\"{self.vision_bos_token}{self.video_token}{self.vision_eos_token}\\\"\\n\\n                content = content.replace(VIDEO_PLACEHOLDER, video_structure, 1)\\n                num_video_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\n@dataclass\\nclass GLM4VPlugin(Qwen2VLPlugin):\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseImageProcessor = getattr(processor, \\\"video_processor\\\", None)\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            video_data = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )\\n            # prepare video metadata\\n            video_metadata = [\\n                {\\\"fps\\\": 2, \\\"duration\\\": duration, \\\"total_frames\\\": len(video)}\\n                for video, duration in zip(video_data[\\\"videos\\\"], video_data[\\\"durations\\\"])\\n            ]\\n            mm_inputs.update(video_processor(images=None, videos=video_data[\\\"videos\\\"], video_metadata=video_metadata))\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens = 0, 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n\\n        merge_length: int = getattr(image_processor, \\\"merge_size\\\") ** 2\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            image_grid_thw = mm_inputs.get(\\\"image_grid_thw\\\", [])\\n            video_grid_thw = mm_inputs.get(\\\"video_grid_thw\\\", [])\\n            num_frames = video_grid_thw[0][0] if len(video_grid_thw) > 0 else 0  # hard code for now\\n            timestamps = mm_inputs.get(\\\"timestamps\\\", [])\\n\\n            if hasattr(timestamps, \\\"tolist\\\"):\\n                timestamps = timestamps.tolist()\\n\\n            if not timestamps:\\n                timestamps_list = []\\n            elif isinstance(timestamps[0], list):\\n                timestamps_list = timestamps[0]\\n            else:\\n                timestamps_list = timestamps\\n\\n            unique_timestamps = timestamps_list.copy()\\n            selected_timestamps = unique_timestamps[:num_frames]\\n            while len(selected_timestamps) < num_frames:\\n                selected_timestamps.append(selected_timestamps[-1] if selected_timestamps else 0)\\n\\n        else:\\n            image_grid_thw = [None] * len(images)\\n            video_grid_thw = [None] * len(videos)\\n            num_frames = 0\\n            selected_timestamps = [0]\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = image_grid_thw[num_image_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER, f\\\"<|begin_of_image|>{self.image_token * image_seqlen}<|end_of_image|>\\\", 1\\n                )\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                video_structure = \\\"\\\"\\n                for frame_index in range(num_frames):\\n                    video_seqlen = (\\n                        video_grid_thw[num_video_tokens][1:].prod() // merge_length if self.expand_mm_tokens else 1\\n                    )\\n                    timestamp_sec = selected_timestamps[frame_index]\\n                    frame_structure = (\\n                        f\\\"<|begin_of_image|>{self.image_token * video_seqlen}<|end_of_image|>{timestamp_sec}\\\"\\n                    )\\n                    video_structure += frame_structure\\n\\n                if not self.expand_mm_tokens:\\n                    video_structure = self.video_token\\n\\n                content = content.replace(VIDEO_PLACEHOLDER, f\\\"<|begin_of_video|>{video_structure}<|end_of_video|>\\\", 1)\\n                num_video_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n    @override\\n    def get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        imglens: list[int],\\n        vidlens: list[int],\\n        audlens: list[int],\\n        batch_ids: list[list[int]],\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n    ) -> dict[str, Union[list[int], \\\"torch.Tensor\\\"]]:\\n        self._validate_input(processor, images, videos, audios)\\n        mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n        mm_inputs.pop(\\\"timestamps\\\", None)\\n        return mm_inputs\\n\\n\\n@dataclass\\nclass Qwen2OmniPlugin(Qwen2VLPlugin):\\n    audio_bos_token: str = \\\"<|audio_start|>\\\"\\n    audio_eos_token: str = \\\"<|audio_end|>\\\"\\n\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        video_processor: BaseVideoProcessor = getattr(processor, \\\"video_processor\\\", None)\\n        feature_extractor: SequenceFeatureExtractor = getattr(processor, \\\"feature_extractor\\\", None) or getattr(\\n            processor, \\\"audio_processor\\\", None\\n        )\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n\\n        if len(videos) != 0:\\n            video_dict = self._regularize_videos(\\n                videos,\\n                image_max_pixels=getattr(processor, \\\"video_max_pixels\\\", 256 * 256),\\n                image_min_pixels=getattr(processor, \\\"video_min_pixels\\\", 16 * 16),\\n                video_fps=getattr(processor, \\\"video_fps\\\", 2.0),\\n                video_maxlen=getattr(processor, \\\"video_maxlen\\\", 128),\\n            )\\n            mm_inputs.update(video_processor(videos=video_dict[\\\"videos\\\"], return_tensors=\\\"pt\\\"))\\n            temporal_patch_size: int = getattr(image_processor, \\\"temporal_patch_size\\\", 2)\\n            mm_inputs[\\\"video_second_per_grid\\\"] = torch.tensor(\\n                [temporal_patch_size / fps for fps in video_dict[\\\"fps_per_video\\\"]]\\n            )\\n\\n        if len(audios) != 0:\\n            audios = self._regularize_audios(\\n                audios,\\n                sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n            )[\\\"audios\\\"]\\n            mm_inputs.update(\\n                feature_extractor(\\n                    audios,\\n                    sampling_rate=getattr(processor, \\\"audio_sampling_rate\\\", 16000),\\n                    return_attention_mask=True,\\n                    padding=\\\"max_length\\\",\\n                    return_tensors=\\\"pt\\\",\\n                )\\n            )\\n            mm_inputs[\\\"feature_attention_mask\\\"] = mm_inputs.pop(\\\"attention_mask\\\")  # prevent conflicts\\n\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens, num_audio_tokens = 0, 0, 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n\\n        merge_length = processor.image_processor.merge_size**2\\n        use_audio_in_video = getattr(processor, \\\"use_audio_in_video\\\", False)\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            image_grid_thw = mm_inputs.get(\\\"image_grid_thw\\\", [])\\n            video_grid_thw = mm_inputs.get(\\\"video_grid_thw\\\", [])\\n            if \\\"feature_attention_mask\\\" in mm_inputs:\\n                if processor.__class__.__name__ == \\\"Qwen3OmniMoeProcessor\\\":  # for qwen3omni\\n                    input_lengths = mm_inputs[\\\"feature_attention_mask\\\"].sum(-1)\\n                    input_lengths_leave = input_lengths % 100\\n                    feature_lengths = (input_lengths_leave - 1) // 2 + 1\\n                    audio_lengths = ((feature_lengths - 1) // 2 + 1 - 1) // 2 + 1 + (input_lengths // 100) * 13\\n                else:\\n                    input_lengths = (mm_inputs[\\\"feature_attention_mask\\\"].sum(-1).numpy() - 1) // 2 + 1\\n                    audio_lengths = (input_lengths - 2) // 2 + 1\\n        else:\\n            mm_inputs = {}\\n            image_grid_thw = [None] * len(images)\\n            video_grid_thw = [None] * len(videos)\\n            audio_lengths = [None] * len(audios)\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                image_seqlen = image_grid_thw[num_image_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                content = content.replace(\\n                    IMAGE_PLACEHOLDER,\\n                    f\\\"{self.vision_bos_token}{self.image_token * image_seqlen}{self.vision_eos_token}\\\",\\n                    1,\\n                )\\n                num_image_tokens += 1\\n\\n            if (\\n                use_audio_in_video and len(audios) and len(videos)\\n            ):  # if use the audio of video # deal video token and audio token together\\n                if len(videos) != len(audios):\\n                    raise ValueError(\\n                        f\\\"Number of videos ({len(videos)}) must match number of audios ({len(audios)}) when using audio in video.\\\"\\n                    )\\n\\n                while VIDEO_PLACEHOLDER in content:\\n                    video_pos = content.find(VIDEO_PLACEHOLDER)\\n                    audio_pos = content.find(AUDIO_PLACEHOLDER, video_pos)\\n                    if audio_pos == -1 or audio_pos < video_pos:\\n                        raise ValueError(\\n                            f\\\"Each {VIDEO_PLACEHOLDER} must be followed by an {AUDIO_PLACEHOLDER} when using audio in video.\\\"\\n                        )\\n\\n                    position_id_per_seconds: int = getattr(processor, \\\"position_id_per_seconds\\\", 25)\\n                    audio_t_index = torch.arange(audio_lengths[num_audio_tokens])\\n                    video_t_index = (\\n                        torch.arange(video_grid_thw[num_video_tokens][0])\\n                        .view(-1, 1, 1)\\n                        .expand(\\n                            -1,\\n                            video_grid_thw[num_video_tokens][1] // image_processor.merge_size,\\n                            video_grid_thw[num_video_tokens][2] // image_processor.merge_size,\\n                        )\\n                        .flatten()\\n                        * mm_inputs[\\\"video_second_per_grid\\\"][num_video_tokens]\\n                        * position_id_per_seconds\\n                    ).long()\\n                    t_ntoken_per_chunk = position_id_per_seconds * 2\\n                    video_chunk_indices = processor.get_chunked_index(video_t_index, t_ntoken_per_chunk)\\n                    audio_chunk_indices = processor.get_chunked_index(audio_t_index, t_ntoken_per_chunk)\\n                    placeholder_string = \\\"\\\"\\n                    placeholder_string += self.vision_bos_token + self.audio_bos_token\\n                    for j in range(max(len(video_chunk_indices), len(audio_chunk_indices))):\\n                        video_chunk_index = video_chunk_indices[j] if j < len(video_chunk_indices) else None\\n                        audio_chunk_index = audio_chunk_indices[j] if j < len(audio_chunk_indices) else None\\n                        if video_chunk_index is not None:\\n                            placeholder_string += self.video_token * (video_chunk_index[1] - video_chunk_index[0])\\n\\n                        if audio_chunk_index is not None:\\n                            placeholder_string += self.audio_token * (audio_chunk_index[1] - audio_chunk_index[0])\\n\\n                    placeholder_string += self.audio_eos_token + self.vision_eos_token\\n                    content = content.replace(VIDEO_PLACEHOLDER, placeholder_string, 1)\\n                    content = content.replace(AUDIO_PLACEHOLDER, \\\"\\\", 1)\\n                    num_audio_tokens += 1\\n                    num_video_tokens += 1\\n            else:\\n                while AUDIO_PLACEHOLDER in content:\\n                    audio_seqlen = audio_lengths[num_audio_tokens] if self.expand_mm_tokens else 1\\n                    content = content.replace(\\n                        AUDIO_PLACEHOLDER,\\n                        f\\\"{self.audio_bos_token}{self.audio_token * audio_seqlen}{self.audio_eos_token}\\\",\\n                        1,\\n                    )\\n                    num_audio_tokens += 1\\n\\n                while VIDEO_PLACEHOLDER in content:\\n                    video_seqlen = (\\n                        video_grid_thw[num_video_tokens].prod() // merge_length if self.expand_mm_tokens else 1\\n                    )\\n                    content = content.replace(\\n                        VIDEO_PLACEHOLDER,\\n                        f\\\"{self.vision_bos_token}{self.video_token * video_seqlen}{self.vision_eos_token}\\\",\\n                        1,\\n                    )\\n                    num_video_tokens += 1\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\n@dataclass\\nclass VideoLlavaPlugin(BasePlugin):\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens, num_video_tokens = 0, 0\\n        messages = deepcopy(messages)\\n        num_frames = 0\\n        if self.expand_mm_tokens:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            if \\\"pixel_values_images\\\" in mm_inputs:\\n                height, width = get_image_size(to_numpy_array(mm_inputs[\\\"pixel_values_images\\\"][0]))\\n                num_frames = 1\\n\\n            if \\\"pixel_values_videos\\\" in mm_inputs:\\n                one_video = to_numpy_array(mm_inputs[\\\"pixel_values_videos\\\"][0])\\n                height, width = get_image_size(one_video[0])\\n                num_frames = one_video.shape[0]  # frame dim is always after batch dim\\n\\n            if \\\"pixel_values_images\\\" in mm_inputs or \\\"pixel_values_videos\\\" in mm_inputs:\\n                image_seqlen = (height // processor.patch_size) * (\\n                    width // processor.patch_size\\n                ) + processor.num_additional_image_tokens\\n                video_seqlen = image_seqlen * num_frames\\n                if processor.vision_feature_select_strategy == \\\"default\\\":\\n                    image_seqlen -= 1\\n        else:\\n            image_seqlen, video_seqlen = 1, 1\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\" * image_seqlen, 1)\\n                num_image_tokens += 1\\n\\n            while VIDEO_PLACEHOLDER in content:\\n                content = content.replace(VIDEO_PLACEHOLDER, \\\"{{video}}\\\" * video_seqlen, 1)\\n                num_video_tokens += 1\\n\\n            content = content.replace(\\\"{{image}}\\\", self.image_token)\\n            message[\\\"content\\\"] = content.replace(\\\"{{video}}\\\", self.video_token)\\n\\n        return messages\\n\\n\\n@dataclass\\nclass LFMVLPlugin(BasePlugin):\\n    r\\\"\\\"\\\"Plugin for LFM2.5-VL vision-language models.\\n\\n    LFM2.5-VL uses dynamic image token counts based on image resolution.\\n    The image processor returns spatial_shapes tensor with [height, width] grid dimensions.\\n    Token count per image = (spatial_h * spatial_w) / (downsample_factor^2)\\n    \\\"\\\"\\\"\\n\\n    @override\\n    def _get_mm_inputs(\\n        self,\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: \\\"MMProcessor\\\",\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\", None)\\n        mm_inputs = {}\\n        if len(images) != 0:\\n            images = self._regularize_images(\\n                images,\\n                image_max_pixels=getattr(processor, \\\"image_max_pixels\\\", 768 * 768),\\n                image_min_pixels=getattr(processor, \\\"image_min_pixels\\\", 32 * 32),\\n            )[\\\"images\\\"]\\n            mm_inputs.update(image_processor(images, return_tensors=\\\"pt\\\"))\\n        return mm_inputs\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        num_image_tokens = 0\\n        messages = deepcopy(messages)\\n        image_processor: BaseImageProcessor = getattr(processor, \\\"image_processor\\\")\\n        downsample_factor: int = getattr(image_processor, \\\"downsample_factor\\\", 2)\\n\\n        if self.expand_mm_tokens and len(images) > 0:\\n            mm_inputs = self._get_mm_inputs(images, videos, audios, processor)\\n            spatial_shapes = mm_inputs.get(\\\"spatial_shapes\\\", [])\\n        else:\\n            spatial_shapes = []\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            while IMAGE_PLACEHOLDER in content:\\n                if self.expand_mm_tokens and len(spatial_shapes) > num_image_tokens:\\n                    h, w = spatial_shapes[num_image_tokens].tolist()\\n                    image_seqlen = (h * w) // (downsample_factor * downsample_factor)\\n                else:\\n                    image_seqlen = 1\\n\\n                content = content.replace(IMAGE_PLACEHOLDER, \\\"{{image}}\\\" * image_seqlen, 1)\\n                num_image_tokens += 1\\n\\n            message[\\\"content\\\"] = content.replace(\\\"{{image}}\\\", self.image_token)\\n\\n        return messages\\n\\n\\n@dataclass\\nclass YoutuVLPlugin(BasePlugin):\\n    r\\\"\\\"\\\"Plugin for Youtu-VL vision-language models.\\\"\\\"\\\"\\n\\n    vision_bos_token: str = \\\"<|vision_start|>\\\"\\n    vision_eos_token: str = \\\"<|vision_end|>\\\"\\n\\n    @override\\n    def process_messages(\\n        self,\\n        messages: list[dict[str, str]],\\n        images: list[\\\"ImageInput\\\"],\\n        videos: list[\\\"VideoInput\\\"],\\n        audios: list[\\\"AudioInput\\\"],\\n        processor: Optional[\\\"MMProcessor\\\"],\\n    ) -> list[dict[str, str]]:\\n        self._validate_input(processor, images, videos, audios)\\n        self._validate_messages(messages, images, videos, audios)\\n        messages = deepcopy(messages)\\n\\n        for message in messages:\\n            content = message[\\\"content\\\"]\\n            content = content.replace(\\n                IMAGE_PLACEHOLDER, f\\\"{self.vision_bos_token}{self.image_token}{self.vision_eos_token}\\\"\\n            )\\n            content = content.replace(\\n                VIDEO_PLACEHOLDER, f\\\"{self.vision_bos_token}{self.video_token}{self.vision_eos_token}\\\"\\n            )\\n\\n            message[\\\"content\\\"] = content\\n\\n        return messages\\n\\n\\nPLUGINS = {\\n    \\\"base\\\": BasePlugin,\\n    \\\"ernie_vl\\\": ErnieVLPlugin,\\n    \\\"gemma3\\\": Gemma3Plugin,\\n    \\\"gemma3n\\\": Gemma3nPlugin,\\n    \\\"gemma4\\\": Gemma4Plugin,\\n    \\\"glm4v\\\": GLM4VPlugin,\\n    \\\"intern_vl\\\": InternVLPlugin,\\n    \\\"kimi_vl\\\": KimiVLPlugin,\\n    \\\"llama4\\\": Llama4Plugin,\\n    \\\"llava\\\": LlavaPlugin,\\n    \\\"llava_next\\\": LlavaNextPlugin,\\n    \\\"llava_next_video\\\": LlavaNextVideoPlugin,\\n    \\\"lfm2_vl\\\": LFMVLPlugin,\\n    \\\"minicpm_v\\\": MiniCPMVPlugin,\\n    \\\"minicpm_v_4_6\\\": MiniCPMV4_6Plugin,\\n    \\\"mllama\\\": MllamaPlugin,\\n    \\\"moss_vl\\\": MossVLPlugin,\\n    \\\"paligemma\\\": PaliGemmaPlugin,\\n    \\\"pixtral\\\": PixtralPlugin,\\n    \\\"qwen2_audio\\\": Qwen2AudioPlugin,\\n    \\\"qwen2_omni\\\": Qwen2OmniPlugin,\\n    \\\"qwen2_vl\\\": Qwen2VLPlugin,\\n    \\\"qwen3_vl\\\": Qwen3VLPlugin,\\n    \\\"video_llava\\\": VideoLlavaPlugin,\\n    \\\"youtu_vl\\\": YoutuVLPlugin,\\n}\\n\\n\\ndef register_mm_plugin(name: str, plugin_class: type[\\\"BasePlugin\\\"]) -> None:\\n    r\\\"\\\"\\\"Register a multimodal plugin.\\\"\\\"\\\"\\n    if name in PLUGINS:\\n        raise ValueError(f\\\"Multimodal plugin {name} already exists.\\\")\\n\\n    PLUGINS[name] = plugin_class\\n\\n\\ndef get_mm_plugin(\\n    name: str,\\n    image_token: str | None = None,\\n    video_token: str | None = None,\\n    audio_token: str | None = None,\\n    **kwargs,\\n) -> \\\"BasePlugin\\\":\\n    r\\\"\\\"\\\"Get plugin for multimodal inputs.\\\"\\\"\\\"\\n    if name not in PLUGINS:\\n        raise ValueError(f\\\"Multimodal plugin `{name}` not found.\\\"";
